// Talking in the world: text chat with speech bubbles, voice chat that gets
// quieter the further apart you are, and an arrow that points to your person.
import * as THREE from "three";
import { textCanvas, FONT } from "./textures.js";

const RTC = { iceServers: [{ urls: ["stun:stun.l.google.com:19302", "stun:stun1.l.google.com:19302"] }] };

function bubble() {
  const { ctx, tex } = textCanvas(512, 160);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: false }));
  s.scale.set(2.6, 0.8, 1);
  s.renderOrder = 8;
  s.visible = false;
  s.userData.say = (text) => {
    ctx.clearRect(0, 0, 512, 160);
    ctx.font = `600 34px ${FONT}`;
    const words = String(text).split(/\s+/);
    const lines = [];
    let line = "";
    for (const w of words) {
      const next = line ? `${line} ${w}` : w;
      if (ctx.measureText(next).width > 440 && line) {
        lines.push(line);
        line = w;
      } else line = next;
    }
    if (line) lines.push(line);
    const shown = lines.slice(0, 2);
    if (lines.length > 2) shown[1] = shown[1].slice(0, Math.max(1, shown[1].length - 1)) + "…";
    const w = Math.min(500, Math.max(...shown.map((l) => ctx.measureText(l).width)) + 50);
    const hgt = shown.length * 42 + 30;
    const y0 = 130 - hgt;
    ctx.fillStyle = "rgba(255,255,255,0.95)";
    ctx.beginPath();
    ctx.roundRect((512 - w) / 2, y0, w, hgt, 26);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(240, y0 + hgt);
    ctx.lineTo(256, y0 + hgt + 20);
    ctx.lineTo(272, y0 + hgt);
    ctx.fill();
    ctx.fillStyle = "#5b3a55";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    shown.forEach((l, i) => ctx.fillText(l, 256, y0 + 36 + i * 42));
    tex.needsUpdate = true;
    s.userData.life = 6 + Math.min(6, text.length / 12);
    s.visible = true;
  };
  return s;
}

export class Social {
  constructor({ scene, net, h, root, camera, player, avatar, audio, toast, myName, isGuest }) {
    Object.assign(this, { scene, net, h, root, camera, player, avatar, audio, toast, myName, isGuest });
    this.myBubble = bubble();
    scene.add(this.myBubble);
    this.bubbles = new Map();
    this.peers = new Map();
    this.voiceOn = false;
    this.mic = null;
    this.buildUI();
  }

  // ---- UI ------------------------------------------------------------------------
  buildUI() {
    const { h } = this;
    this.log = h("div", { class: "g3d-chatlog", "aria-live": "polite" });
    this.input = h("input", { class: "g3d-chat-input", type: "text", maxlength: 140, placeholder: "say something ♡", enterkeyhint: "send" });
    this.input.addEventListener("keydown", (e) => {
      e.stopPropagation();
      if (e.key === "Enter") this.send();
      if (e.key === "Escape") this.closeChat();
    });
    this.input.addEventListener("keyup", (e) => e.stopPropagation());
    this.box = h("div", { class: "g3d-chat", hidden: true },
      this.input,
      h("button", { class: "g3d-cwatch", type: "button", onclick: () => this.send() }, "send"),
      h("button", { class: "g3d-cbtn", type: "button", "aria-label": "close chat", onclick: () => this.closeChat() }, "✕"),
    );
    for (const type of ["touchstart", "touchmove", "touchend"]) this.box.addEventListener(type, (e) => e.stopPropagation(), { passive: true });
    this.pins = h("div", { class: "g3d-pins" });
    this.root.append(this.log, this.box, this.pins);
    this.pinEls = new Map();
  }

  openChat() {
    this.box.hidden = false;
    this.root.classList.add("chatting");
    setTimeout(() => this.input.focus(), 30);
  }
  closeChat() {
    this.box.hidden = true;
    this.root.classList.remove("chatting");
    this.input.blur();
  }
  get chatOpen() {
    return !this.box.hidden;
  }

  send() {
    const text = this.input.value.trim().slice(0, 140);
    if (!text) {
      this.closeChat();
      return;
    }
    this.input.value = "";
    this.net.send("chat", { text, name: this.myName() });
    this.say(null, text, this.myName());
    this.closeChat();
  }

  say(remote, text, name) {
    const b = remote ? this.bubbleFor(remote) : this.myBubble;
    b.userData.say(text);
    const line = this.h("div", { class: `g3d-chatline ${remote ? "" : "me"}` }, this.h("b", {}, `${name || "someone"}: `), text);
    this.log.append(line);
    while (this.log.children.length > 6) this.log.firstChild.remove();
    setTimeout(() => line.classList.add("old"), 12000);
    setTimeout(() => line.remove(), 14000);
    if (remote) this.audio.sfx("chat");
  }

  bubbleFor(r) {
    let b = this.bubbles.get(r.key);
    if (!b) {
      b = bubble();
      this.scene.add(b);
      this.bubbles.set(r.key, b);
    }
    return b;
  }

  onRemote(p, r) {
    if (p.t === "chat" && r) this.say(r, String(p.text || "").slice(0, 140), r.name || p.name);
    else if (p.t === "voice") this.onSignal(p, r);
  }

  // ---- voice ---------------------------------------------------------------------
  async toggleVoice() {
    if (this.voiceOn) {
      this.voiceOn = false;
      this.mic?.getTracks().forEach((t) => t.stop());
      this.mic = null;
      for (const peer of this.peers.values()) peer.sender?.replaceTrack(null).catch(() => {});
      this.toast("mic off 🔇");
      return false;
    }
    try {
      this.mic = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } });
    } catch {
      this.toast("couldn't use the mic. check the browser's permission ♡");
      return false;
    }
    this.voiceOn = true;
    const track = this.mic.getAudioTracks()[0];
    for (const peer of this.peers.values()) peer.sender?.replaceTrack(track).catch(() => {});
    this.toast(this.net.remotes.size ? "mic on 🎙️ they can hear you" : "mic on 🎙️ they'll hear you when they come");
    return true;
  }

  // one connection per person, made when either of us has the mic on.
  // the one with the smaller key calls; the mic is swapped in without
  // calling again, so turning it on and off is instant.
  syncPeers() {
    const me = this.net.myKey;
    for (const r of this.net.remotes.values()) {
      const want = this.voiceOn || r.vo;
      const peer = this.peers.get(r.key);
      if (want && !peer && me < r.key) this.call(r);
      if (!want && peer && Date.now() - peer.at > 4000) this.hangUp(r.key);
    }
    for (const key of [...this.peers.keys()]) if (!this.net.remotes.has(key)) this.hangUp(key);
  }

  makePeer(key) {
    const pc = new RTCPeerConnection(RTC);
    const audio = new Audio();
    audio.autoplay = true;
    audio.playsInline = true;
    const peer = { pc, audio, sender: null, at: Date.now() };
    pc.ontrack = (e) => {
      audio.srcObject = e.streams[0] || new MediaStream([e.track]);
      audio.play().catch(() => {});
    };
    pc.onicecandidate = (e) => {
      if (e.candidate) this.net.send("voice", { kind: "ice", c: e.candidate.toJSON() }, key);
    };
    pc.onconnectionstatechange = () => {
      if (pc.connectionState === "failed") this.hangUp(key);
    };
    this.peers.set(key, peer);
    return peer;
  }

  async call(r) {
    const peer = this.makePeer(r.key);
    const tr = peer.pc.addTransceiver("audio", { direction: "sendrecv" });
    peer.sender = tr.sender;
    if (this.mic) await tr.sender.replaceTrack(this.mic.getAudioTracks()[0]).catch(() => {});
    const offer = await peer.pc.createOffer();
    await peer.pc.setLocalDescription(offer);
    this.net.send("voice", { kind: "offer", sdp: offer.sdp }, r.key);
  }

  async onSignal(p, r) {
    if (!r) return;
    let peer = this.peers.get(r.key);
    try {
      if (p.kind === "offer") {
        if (peer) this.hangUp(r.key);
        peer = this.makePeer(r.key);
        await peer.pc.setRemoteDescription({ type: "offer", sdp: p.sdp });
        const tr = peer.pc.getTransceivers()[0];
        if (tr) {
          tr.direction = "sendrecv";
          peer.sender = tr.sender;
          if (this.mic) await tr.sender.replaceTrack(this.mic.getAudioTracks()[0]).catch(() => {});
        }
        const answer = await peer.pc.createAnswer();
        await peer.pc.setLocalDescription(answer);
        this.net.send("voice", { kind: "answer", sdp: answer.sdp }, r.key);
        (peer.queued || []).forEach((c) => peer.pc.addIceCandidate(c).catch(() => {}));
      } else if (p.kind === "answer" && peer) {
        await peer.pc.setRemoteDescription({ type: "answer", sdp: p.sdp });
        (peer.queued || []).forEach((c) => peer.pc.addIceCandidate(c).catch(() => {}));
      } else if (p.kind === "ice") {
        if (!peer) return;
        if (peer.pc.remoteDescription) await peer.pc.addIceCandidate(p.c).catch(() => {});
        else (peer.queued = peer.queued || []).push(p.c);
      }
    } catch (error) {
      console.warn("voice", error);
    }
  }

  hangUp(key) {
    const peer = this.peers.get(key);
    if (!peer) return;
    peer.pc.close();
    peer.audio.srcObject = null;
    this.peers.delete(key);
  }

  // ---- per frame ---------------------------------------------------------------------
  update(dt) {
    const { player, avatar, camera } = this;
    // bubbles follow heads and fade
    const place = (b, pos, height) => {
      if (!b.visible) return;
      b.userData.life -= dt;
      b.position.set(pos.x, pos.y + height + 0.95, pos.z);
      b.material.opacity = Math.min(1, b.userData.life * 2);
      if (b.userData.life <= 0) b.visible = false;
    };
    place(this.myBubble, player.pos, avatar.dims.height);
    for (const [key, b] of this.bubbles) {
      const r = this.net.remotes.get(key);
      if (!r) {
        this.scene.remove(b);
        this.bubbles.delete(key);
        continue;
      }
      place(b, r.pos, r.avatar.dims.height);
    }
    // voice gets quieter with distance
    this.peerTimer = (this.peerTimer || 0) - dt;
    if (this.peerTimer <= 0) {
      this.peerTimer = 1;
      this.syncPeers();
    }
    for (const [key, peer] of this.peers) {
      const r = this.net.remotes.get(key);
      if (!r) continue;
      const d = r.pos.distanceTo(player.pos);
      peer.audio.volume = Math.max(0.12, Math.min(1, 1.15 - d / 40));
    }
    // pins for people who are off screen or far away
    const W = window.innerWidth;
    const H = window.innerHeight;
    const v = new THREE.Vector3();
    const seen = new Set();
    for (const r of this.net.remotes.values()) {
      seen.add(r.key);
      let el = this.pinEls.get(r.key);
      if (!el) {
        el = this.h("div", { class: "g3d-pin" }, this.h("span", { class: "g3d-pin-arrow" }, "➤"), this.h("span", { class: "g3d-pin-text" }));
        this.pins.append(el);
        this.pinEls.set(r.key, el);
      }
      const d = r.pos.distanceTo(player.pos);
      v.copy(r.pos).setY(r.pos.y + r.avatar.dims.height + 0.9).project(camera);
      const behind = v.z > 1;
      let x = ((v.x + 1) / 2) * W;
      let y = ((1 - v.y) / 2) * H;
      if (behind) {
        x = W - x;
        y = H - y;
      }
      const m = 46;
      const onScreen = !behind && x > m && x < W - m && y > m && y < H - m;
      if (onScreen && d < 18) {
        el.hidden = true;
        continue;
      }
      el.hidden = false;
      const cx = W / 2;
      const cy = H / 2;
      let ang = 0;
      if (!onScreen) {
        // clamp to the screen edge, pointing toward them
        const dx = x - cx;
        const dy = y - cy;
        ang = Math.atan2(dy, dx);
        const s = Math.min((W / 2 - m) / Math.abs(dx || 1e-3), (H / 2 - m) / Math.abs(dy || 1e-3));
        x = cx + dx * s;
        y = cy + dy * s;
      }
      el.classList.toggle("edge", !onScreen);
      // keep the whole pill on screen: it grows inward from the edge
      const shift = x > W * 0.6 ? "calc(-100% + 32px)" : x < W * 0.4 ? "0px" : "calc(-50% + 16px)";
      el.style.transform = `translate(${x}px, ${y}px) translateX(${shift})`;
      el.firstChild.style.transform = `rotate(${ang}rad)`;
      const text = `💗 ${r.name || "your person"} · ${Math.round(d)}m${r.vo ? " 🎙️" : ""}`;
      if (el.lastChild.textContent !== text) el.lastChild.textContent = text;
    }
    for (const [key, el] of this.pinEls) {
      if (!seen.has(key)) {
        el.remove();
        this.pinEls.delete(key);
      }
    }
  }

  destroy() {
    this.mic?.getTracks().forEach((t) => t.stop());
    for (const key of [...this.peers.keys()]) this.hangUp(key);
    this.scene.remove(this.myBubble);
    for (const b of this.bubbles.values()) this.scene.remove(b);
    this.log.remove();
    this.box.remove();
    this.pins.remove();
  }
}
