// Our photo wall: a big shared album near the willow. Each of us carries a
// mini camera (poses, selfies, couple poses) and there's a tripod with a
// timer for pictures together. Photos are saved here and shared live.
import * as THREE from "three";
import { std, glow } from "./world.js";
import { texture, textCanvas, FONT, isImageData } from "./textures.js";

const STORE = "tdd3d.album";
const MAX = 24;

export const SOLO_POSES = [
  { id: "peace", emoji: "✌️", label: "peace" },
  { id: "hearthands", emoji: "🫶", label: "heart hands" },
  { id: "blowkiss", emoji: "😘", label: "blow a kiss" },
  { id: "shy", emoji: "🙈", label: "shy" },
  { id: "cheer", emoji: "🙌", label: "yay" },
  { id: "crossed", emoji: "😎", label: "cool" },
];
// couple poses: what I do, what you do, and where you stand
export const COUPLE_POSES = [
  { id: "cuddle", emoji: "💞", label: "cuddle", mine: "cuddle", theirs: "cuddle", place: "front" },
  { id: "kiss", emoji: "💋", label: "kiss", mine: "kiss", theirs: "kiss", place: "front" },
  { id: "heart", emoji: "💗", label: "make a heart", mine: "halfR", theirs: "halfL", place: "right" },
  { id: "back", emoji: "😎", label: "back to back", mine: "crossed", theirs: "crossed", place: "back" },
];

export class Album {
  constructor(ctx) {
    this.ctx = ctx;
    this.items = [];
    try {
      this.items = (JSON.parse(localStorage.getItem(STORE) || "[]") || []).filter((it) => isImageData(it?.src));
    } catch {}
    this.mode = null; // null | "camera"
    this.selfie = false;
    this.timer = 0;
    this.tripod = null;
    this.pose = null;
    this.buildWall(ctx.pos);
    this.buildUI();
    this.drawWall();
  }

  // ---- the wall ----------------------------------------------------------------
  buildWall(pos) {
    const { scene, world } = this.ctx;
    const g = new THREE.Group();
    g.position.copy(pos);
    // face the middle of the island
    g.rotation.y = Math.atan2(-pos.x, -pos.z + 4);
    scene.add(g);
    this.group = g;
    const wood = std("#ffffff", { map: texture("wood", ["#c9a27e", "#a07a58"]) });
    const W = 6.6;
    const H = 3.2;
    const box = (w, h, d, m, x, y, z) => {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      g.add(mesh);
      return mesh;
    };
    for (const s of [-1, 1]) box(0.22, 4.4, 0.22, wood, s * (W / 2 + 0.05), 2.2, 0);
    box(W + 0.5, H + 0.3, 0.16, wood, 0, 0.6 + H / 2 + 0.15, -0.1);
    box(W + 0.9, 0.18, 0.5, std("#e2557f"), 0, 0.6 + H + 0.4, -0.05);
    // the photo board
    this.wallCanvas = textCanvas(2048, Math.round((2048 * (H - 0.2)) / (W - 0.2)));
    const board = new THREE.Mesh(new THREE.PlaneGeometry(W - 0.2, H - 0.2), new THREE.MeshBasicMaterial({ map: this.wallCanvas.tex, toneMapped: false }));
    board.position.set(0, 0.6 + H / 2 + 0.15, 0.0);
    g.add(board);
    this.board = board;
    // string lights along the top
    for (let k = 0; k <= 16; k++) {
      const t = k / 16;
      const b = new THREE.Mesh(new THREE.IcosahedronGeometry(0.06, 0), k % 2 ? glow.warm : glow.pink);
      b.position.set(-W / 2 + W * t, 0.6 + H + 0.12 - Math.sin(t * Math.PI) * 0.18, 0.12);
      g.add(b);
    }
    // the posing spot (a star on the grass) and a tripod with a camera
    const star = new THREE.Shape();
    for (let k = 0; k < 10; k++) {
      const r = k % 2 ? 0.35 : 0.8;
      const a = (k / 10) * Math.PI * 2;
      k ? star.lineTo(Math.sin(a) * r, Math.cos(a) * r) : star.moveTo(Math.sin(a) * r, Math.cos(a) * r);
    }
    const starMesh = new THREE.Mesh(new THREE.ShapeGeometry(star), new THREE.MeshBasicMaterial({ color: "#ffd166", transparent: true, opacity: 0.8, depthWrite: false }));
    starMesh.rotation.x = -Math.PI / 2;
    starMesh.position.set(0, 0.03, 2.2);
    g.add(starMesh);
    const tri = new THREE.Group();
    tri.position.set(0, 0, 7.2);
    g.add(tri);
    const dark = std("#2b2633");
    for (let k = 0; k < 3; k++) {
      const a = (k / 3) * Math.PI * 2;
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 1.5, 4), dark);
      leg.position.set(Math.sin(a) * 0.22, 0.72, Math.cos(a) * 0.22);
      leg.rotation.set(Math.cos(a) * 0.3, 0, -Math.sin(a) * 0.3);
      tri.add(leg);
    }
    const cam = new THREE.Group();
    cam.position.y = 1.5;
    tri.add(cam);
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.24, 0.18), std("#ff8fb1"));
    cam.add(body);
    const lens = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.09, 0.12, 12), dark);
    lens.rotation.x = Math.PI / 2;
    lens.position.z = -0.14;
    cam.add(lens);
    const light = new THREE.Mesh(new THREE.SphereGeometry(0.03, 6, 4), new THREE.MeshBasicMaterial({ color: "#ff3b5c" }));
    light.position.set(0.12, 0.08, -0.09);
    cam.add(light);
    this.recLight = light;
    g.updateMatrixWorld(true);
    const toW = (x, y, z) => new THREE.Vector3(x, y, z).applyMatrix4(g.matrixWorld);
    this.spot = toW(0, 0, 2.2);
    this.tripodCam = toW(0, 1.55, 7.05);
    this.tripodLook = toW(0, 1.1, 2.0);
    for (const s of [-1, 1]) {
      const p = toW(s * (W / 2 + 0.05), 0, 0);
      world.circles.push({ x: p.x, z: p.z, r: 0.2 });
    }
    const a = toW(-W / 2, 0, -0.1);
    const b = toW(W / 2, 0, -0.1);
    world.segments.push({ ax: a.x, az: a.z, bx: b.x, bz: b.z, h: 4, room: "" });
    const tp = toW(0, 0, 7.2);
    world.circles.push({ x: tp.x, z: tp.z, r: 0.3 });
    // interactables (screens are handled by us, not the widget code)
    const room = this.ctx.room;
    const wallItem = { id: "album", label: "look at our photos 📸", pos: toW(0, 0, 1.4), radius: 2.4, action: { type: "album" }, room: room?.def.id, hits: [board] };
    board.userData.item = wallItem;
    const triItem = { id: "tripod", label: "take a photo together ⏱", pos: toW(0, 0, 7.9), radius: 1.5, action: { type: "tripod" }, room: room?.def.id, hits: [body] };
    body.userData.item = triItem;
    world.interactables.push(wallItem, triItem);
  }

  drawWall() {
    const shown = this.items.slice(0, 12);
    const ticket = (this.wallTicket = (this.wallTicket || 0) + 1);
    return Promise.all(shown.map((it) => loadImg(it.src).catch(() => null))).then((imgs) => {
      if (ticket === this.wallTicket) this.paintWall(shown, imgs);
    });
  }

  paintWall(shown, imgs) {
    const { ctx, tex } = this.wallCanvas;
    const CW = ctx.canvas.width;
    const CH = ctx.canvas.height;
    // cork board
    ctx.fillStyle = "#e7c49a";
    ctx.fillRect(0, 0, CW, CH);
    for (let i = 0; i < 2200; i++) {
      ctx.fillStyle = i % 3 ? "rgba(140,90,50,0.10)" : "rgba(255,255,255,0.12)";
      const x = (i * 977) % CW;
      const y = (i * 613) % CH;
      ctx.fillRect(x, y, 3, 3);
    }
    const cols = 6;
    const rows = 2;
    const cw = CW / cols;
    const rh = CH / rows;
    if (!shown.length) {
      ctx.fillStyle = "#7a5236";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.font = `700 64px ${FONT}`;
      ctx.fillText("˚₊‧ our photo wall ‧₊˚", CW / 2, CH / 2 - 40);
      ctx.font = `500 40px ${FONT}`;
      ctx.fillText("take a picture with your camera 📷 or the tripod ⏱", CW / 2, CH / 2 + 40);
    }
    shown.forEach((it, i) => {
      const img = imgs[i];
      if (!img) return;
      const c = i % cols;
      const r = Math.floor(i / cols);
      const x = c * cw + cw / 2;
      const y = r * rh + rh / 2;
      const rot = (((i * 37) % 11) - 5) * 0.012;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(rot);
      ctx.shadowColor = "rgba(60,30,20,0.35)";
      ctx.shadowBlur = 16;
      ctx.shadowOffsetY = 6;
      const scale = Math.min((cw * 0.8) / 600, (rh * 0.9) / 700);
      ctx.drawImage(img, (-600 * scale) / 2, (-700 * scale) / 2, 600 * scale, 700 * scale);
      ctx.shadowColor = "transparent";
      ctx.fillStyle = ["#e2557f", "#7b5cd6", "#ffd166", "#6fa8e8"][i % 4];
      ctx.beginPath();
      ctx.arc(0, (-700 * scale) / 2 + 12, 13, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    });
    tex.needsUpdate = true;
  }

  // ---- storage and sharing -----------------------------------------------------------
  save() {
    for (let n = this.items.length; n > 0; n--) {
      try {
        localStorage.setItem(STORE, JSON.stringify(this.items.slice(0, n)));
        return;
      } catch {}
    }
  }
  addItem(item, send = true) {
    if (!item?.id || !isImageData(item.src) || this.items.some((x) => x.id === item.id)) return false;
    this.items.unshift(item);
    this.items.sort((a, b) => b.at - a.at);
    this.items = this.items.slice(0, MAX);
    this.save();
    this.drawWall();
    if (send) this.ctx.net.send("photo", { item });
    return true;
  }
  removeItem(id, send = true) {
    const before = this.items.length;
    this.items = this.items.filter((x) => x.id !== id);
    if (this.items.length === before) return;
    this.save();
    this.drawWall();
    if (send) this.ctx.net.send("unphoto", { id });
  }
  // when your person arrives, hand them the photos they're missing
  shareWith(key) {
    this.items.slice(0, MAX).forEach((item, i) => setTimeout(() => this.ctx.net.send("photo", { item, sync: true }, key), 400 + i * 350));
  }
  onRemote(p, who) {
    if (p.t === "photo") {
      if (this.addItem(p.item, false) && !p.sync) this.ctx.toast(`${who || "your person"} pinned a new photo 📸`);
    } else if (p.t === "unphoto") this.removeItem(p.id, false);
    else if (p.t === "pose") this.onCouplePose(p, who);
    else if (p.t === "timer") this.ctx.toast(`📸 ${who || "your person"} set the timer: stand on the star ⭐`);
  }

  // ---- UI ---------------------------------------------------------------------------------
  buildUI() {
    const { h } = this.ctx;
    // camera mode: a viewfinder and a pose bar
    this.poseRow = h("div", { class: "g3d-cam-poses" });
    this.countEl = h("div", { class: "g3d-cam-count", hidden: true });
    this.shutter = h("button", { class: "g3d-cam-shutter", type: "button", "aria-label": "take the photo", onclick: () => this.snap() });
    this.selfieBtn = h("button", { class: "g3d-cbtn", type: "button", title: "selfie", "aria-label": "selfie", onclick: () => this.toggleSelfie() }, "🤳");
    this.timerBtn = h("button", { class: "g3d-cpill", type: "button", title: "3 second timer", onclick: () => this.toggleTimer() }, "⏱ off");
    this.camUI = h("div", { class: "g3d-cam", hidden: true },
      h("div", { class: "g3d-cam-frame" }, h("span"), h("span"), h("span"), h("span")),
      this.countEl,
      h("div", { class: "g3d-cam-bar" },
        this.poseRow,
        h("div", { class: "g3d-cam-row" },
          h("button", { class: "g3d-cbtn", type: "button", title: "put the camera away", "aria-label": "close camera", onclick: () => this.closeCamera() }, "✕"),
          this.timerBtn,
          this.shutter,
          this.selfieBtn,
          h("button", { class: "g3d-cbtn", type: "button", title: "our photo wall", "aria-label": "our photo wall", onclick: () => this.openWall() }, "🖼️"),
        ),
      ),
    );
    this.flash = h("div", { class: "g3d-cam-flash" });
    // after the photo: post it?
    this.previewImg = h("img", { class: "g3d-gallery-img g3d-photo-img", alt: "" });
    this.previewActions = h("div", { class: "g3d-gallery-actions" });
    this.preview = h("div", { class: "g3d-overlay g3d-photo-preview", hidden: true, role: "dialog", "aria-label": "your photo" },
      h("div", { class: "g3d-sheet" },
        h("header", { class: "g3d-panel-head" }, h("h2", { class: "g3d-sheet-title" }, "˚₊‧ cute! ‧₊˚"), h("button", { class: "g3d-close", type: "button", "aria-label": "close", onclick: () => (this.preview.hidden = true) }, "✕")),
        h("div", { class: "g3d-help-body g3d-gallery-body" }, this.previewImg, this.previewActions),
      ),
    );
    // the album: every photo, tap one to see it big
    this.grid = h("div", { class: "g3d-album-grid" });
    this.viewer = h("div", { class: "g3d-album-viewer", hidden: true });
    this.wallView = h("div", { class: "g3d-overlay g3d-album", hidden: true, role: "dialog", "aria-label": "our photo wall" },
      h("div", { class: "g3d-sheet g3d-album-sheet" },
        h("header", { class: "g3d-panel-head" }, h("h2", { class: "g3d-sheet-title" }, "˚₊‧ our photo wall ‧₊˚"), h("button", { class: "g3d-close", type: "button", "aria-label": "close", onclick: () => this.closeWall() }, "✕")),
        this.grid,
        this.viewer,
      ),
    );
    for (const el of [this.camUI, this.preview, this.wallView]) {
      for (const type of ["touchstart", "touchmove", "touchend"]) el.addEventListener(type, (e) => e.stopPropagation(), { passive: true });
    }
    document.body.append(this.camUI, this.flash, this.preview, this.wallView);
    this.renderPoses();
  }

  renderPoses() {
    const { h } = this.ctx;
    const chip = (p, couple) =>
      h("button", { class: `g3d-pose ${this.pose === p.id ? "on" : ""}`, type: "button", title: p.label, onclick: () => (couple ? this.couplePose(p) : this.setPose(p.id)) }, h("span", {}, p.emoji), h("small", {}, p.label));
    this.poseRow.replaceChildren(
      h("div", { class: "g3d-pose-group" }, h("span", { class: "g3d-cinema-label" }, "poses"), ...SOLO_POSES.map((p) => chip(p, false))),
      h("div", { class: "g3d-pose-group" }, h("span", { class: "g3d-cinema-label" }, "together"), ...COUPLE_POSES.map((p) => chip(p, true))),
    );
  }

  setPose(id, quiet = false) {
    this.pose = this.pose === id ? null : id;
    this.ctx.avatar.pose = this.pose;
    if (!quiet) this.ctx.audio.sfx("pop");
    this.renderPoses();
  }

  couplePose(p) {
    const { net, player, toast } = this.ctx;
    const near = net.nearest(player.pos, 10);
    if (!near) {
      toast("couple poses need your person close by ♡");
      return;
    }
    // tap it again to let go (for both of you)
    if (this.pose === p.id) {
      this.clearPose();
      return;
    }
    this.pose = p.id;
    this.ctx.avatar.pose = p.mine;
    this.renderPoses();
    // where the photo is taken from: face it for side-by-side poses,
    // face each other for cuddles and kisses
    const cam = this.ctx.camera.position;
    const toCam = Math.atan2(cam.x - player.pos.x, cam.z - player.pos.z);
    // cuddles and kisses: side on to the camera, so it sees you both in profile
    if (p.place === "front") player.facing = toCam + (Math.sin(Math.atan2(near.pos.x - player.pos.x, near.pos.z - player.pos.z) - toCam) >= 0 ? Math.PI / 2 : -Math.PI / 2);
    else if (p.place === "right") player.facing = toCam;
    else player.facing = toCam + Math.PI / 2; // back to back: side on to the camera
    player.speed = 0;
    this.partnerKey = near.key;
    net.send("pose", { pose: p.id, x: player.pos.x, z: player.pos.z, f: player.facing, cy: toCam }, near.key);
    this.ctx.audio.sfx("pop");
  }

  // your person asked for a couple pose: step in and do your half
  onCouplePose(p, who) {
    const def = COUPLE_POSES.find((c) => c.id === p.pose);
    const { player, collide, toast } = this.ctx;
    if (!p.pose) {
      // they let go
      if (COUPLE_POSES.some((c) => c.id === this.pose)) this.clearPose(false);
      return;
    }
    if (!def) return;
    if (Math.hypot(player.pos.x - p.x, player.pos.z - p.z) > 12) return;
    const f = p.f;
    const fwd = [Math.sin(f), Math.cos(f)];
    const right = [-Math.cos(f), Math.sin(f)];
    let x = p.x;
    let z = p.z;
    let face = f + Math.PI;
    if (def.place === "front") {
      // far enough apart that faces meet without going through each other
      const gap = def.id === "kiss" ? 1.02 : 0.74;
      x += fwd[0] * gap;
      z += fwd[1] * gap;
    } else if (def.place === "right") {
      // shoulder to shoulder on their right, both facing the camera
      x += right[0] * 0.7;
      z += right[1] * 0.7;
      face = f;
    } else if (def.place === "back") {
      // backs touching, looking the other way
      x -= fwd[0] * 0.5;
      z -= fwd[1] * 0.5;
    }
    this.partnerKey = p.key;
    // swing your camera round to the front too, so you see the pose
    if (Number.isFinite(p.cy) && this.ctx.controls) {
      this.ctx.controls.yaw = p.cy;
      this.ctx.controls.pitch = 0.15;
    }
    player.pos.x = x;
    player.pos.z = z;
    collide?.(player.pos);
    player.facing = face;
    player.speed = 0;
    this.ctx.avatar.pose = def.theirs;
    this.pose = def.id;
    this.renderPoses();
    toast(`${who || "your person"} wants a ${def.label} photo ${def.emoji}`);
    clearTimeout(this.poseTimer);
    // let go after a while (or when they let go, or you move)
    this.poseTimer = setTimeout(() => {
      if (this.pose === def.id) this.clearPose(false);
    }, 25000);
  }

  // a glowing heart between your hands while you make one together
  updateHeart(t) {
    const r = this.partnerKey ? this.ctx.net.remotes.get(this.partnerKey) : null;
    const on = this.pose === "heart" && r;
    if (!on) {
      if (this.heartSprite) this.heartSprite.visible = false;
      return;
    }
    if (!this.heartSprite) {
      const { ctx, tex } = textCanvas(128, 128);
      ctx.font = "104px serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("💗", 64, 70);
      tex.needsUpdate = true;
      this.heartSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
      this.ctx.scene.add(this.heartSprite);
    }
    const p = this.ctx.player.pos;
    const h = this.ctx.avatar.dims.height;
    this.heartSprite.visible = true;
    this.heartSprite.position.set((p.x + r.pos.x) / 2, Math.max(p.y, r.pos.y) + h + 0.25, (p.z + r.pos.z) / 2);
    this.heartSprite.scale.setScalar(0.62 + Math.sin(t * 4) * 0.05);
  }

  clearPose(tell = true) {
    const wasCouple = COUPLE_POSES.some((c) => c.id === this.pose);
    this.pose = null;
    this.ctx.avatar.pose = null;
    this.renderPoses();
    if (tell && wasCouple && this.partnerKey) this.ctx.net.send("pose", { pose: null }, this.partnerKey);
    this.partnerKey = null;
  }

  // walking away breaks a couple pose
  checkMoved() {
    if (this.pose && COUPLE_POSES.some((c) => c.id === this.pose) && this.ctx.player.speed > 1.2) this.clearPose();
  }

  openCamera() {
    this.ctx.closeOthers?.();
    this.mode = "camera";
    this.camUI.hidden = false;
    this.ctx.root.classList.add("in-camera");
    this.ctx.audio.sfx("equip");
  }
  closeCamera() {
    this.mode = null;
    this.selfie = false;
    this.selfieBtn.classList.remove("on");
    this.camUI.hidden = true;
    this.ctx.root.classList.remove("in-camera");
    this.clearPose();
  }
  toggleSelfie() {
    this.selfie = !this.selfie;
    this.selfieBtn.classList.toggle("on", this.selfie);
  }
  toggleTimer() {
    this.useTimer = !this.useTimer;
    this.timerBtn.textContent = this.useTimer ? "⏱ 3s" : "⏱ off";
    this.timerBtn.classList.toggle("on", this.useTimer);
  }

  // the tripod: count down from 5, then snap from the tripod's point of view
  startTripod() {
    if (this.counting) return;
    this.tripod = true;
    this.ctx.net.send("timer", {});
    this.ctx.toast("stand on the star ⭐ and pose!");
    this.countdown(5, () => {
      this.capture();
      this.tripod = false;
    });
  }

  snap() {
    if (this.counting) return;
    if (this.useTimer) this.countdown(3, () => this.capture());
    else this.capture();
  }

  countdown(n, done) {
    this.counting = true;
    this.countEl.hidden = false;
    document.body.append(this.countEl);
    const tick = () => {
      if (n <= 0) {
        this.countEl.hidden = true;
        this.counting = false;
        done();
        return;
      }
      this.countEl.textContent = String(n);
      this.countEl.classList.remove("pop");
      void this.countEl.offsetWidth;
      this.countEl.classList.add("pop");
      this.ctx.audio.sfx("tick");
      n--;
      setTimeout(tick, 1000);
    };
    tick();
  }

  // where the camera goes while you take pictures (or null for the normal view)
  cameraOverride(out, target) {
    const { player, avatar } = this.ctx;
    if (this.tripod && this.tripodCam) {
      out.copy(this.tripodCam);
      target.copy(this.tripodLook);
      return true;
    }
    if (this.mode === "camera" && this.selfie) {
      const f = player.facing;
      const h = avatar.dims.height;
      out.set(player.pos.x + Math.sin(f) * 2.0 + Math.cos(f) * 0.25, player.pos.y + h * 0.9, player.pos.z + Math.cos(f) * 2.0 - Math.sin(f) * 0.25);
      target.set(player.pos.x, player.pos.y + h * 0.62, player.pos.z);
      return true;
    }
    return false;
  }

  capture() {
    const { renderer, scene, camera, hideTags, audio, myName } = this.ctx;
    hideTags(true);
    renderer.render(scene, camera);
    const src = renderer.domElement;
    const sw = src.width;
    const sh = src.height;
    // a 6:5 crop from the middle
    let cw = sw;
    let ch = (sw * 480) / 560;
    if (ch > sh) {
      ch = sh;
      cw = (sh * 560) / 480;
    }
    const pol = document.createElement("canvas");
    pol.width = 600;
    pol.height = 700;
    const x = pol.getContext("2d");
    x.fillStyle = "#fffdf8";
    x.fillRect(0, 0, 600, 700);
    try {
      x.drawImage(src, (sw - cw) / 2, (sh - ch) / 2, cw, ch, 20, 20, 560, 480);
    } catch {}
    hideTags(false);
    const date = new Date();
    x.fillStyle = "#5b3a55";
    x.textAlign = "center";
    x.font = `700 38px ${FONT}`;
    x.fillText("toto & dodo ♡", 300, 572);
    x.font = `500 26px ${FONT}`;
    x.fillStyle = "#a07c96";
    x.fillText(date.toLocaleDateString(undefined, { day: "numeric", month: "long", year: "numeric" }), 300, 620);
    x.font = `500 22px ${FONT}`;
    x.fillText(`📷 ${myName()}`, 300, 660);
    const dataUrl = pol.toDataURL("image/jpeg", 0.8);
    // flash + shutter sound
    this.flash.classList.remove("on");
    void this.flash.offsetWidth;
    this.flash.classList.add("on");
    audio.sfx("shutter");
    this.showPreview({ id: `${date.getTime().toString(36)}${Math.random().toString(36).slice(2, 6)}`, src: dataUrl, by: myName(), at: date.getTime() });
  }

  showPreview(item) {
    const { h, isGuest, toast, confetti } = this.ctx;
    this.previewImg.src = item.src;
    const actions = [];
    if (!isGuest) {
      actions.push(
        h("button", { class: "g3d-big-btn", type: "button", onclick: () => {
          this.addItem(item);
          this.preview.hidden = true;
          confetti?.();
          toast("pinned to our photo wall 📌");
        } }, "📌 pin it to our wall"),
        h("button", { class: "g3d-big-btn g3d-big-btn-soft", type: "button", onclick: () => {
          const a = document.createElement("a");
          a.href = item.src;
          a.download = `toto-dodo-${item.at}.jpg`;
          a.click();
        } }, "save to my device"),
      );
    } else actions.push(h("p", { class: "g3d-invite-note" }, "visitors can take photos but can't keep or post them ♡"));
    actions.push(h("button", { class: "g3d-big-btn g3d-big-btn-soft", type: "button", onclick: () => (this.preview.hidden = true) }, "retake"));
    this.previewActions.replaceChildren(...actions);
    this.preview.hidden = false;
  }

  openWall() {
    const { h, isGuest } = this.ctx;
    this.ctx.closeOthers?.();
    this.viewer.hidden = true;
    this.grid.hidden = false;
    this.grid.replaceChildren(
      ...(this.items.length
        ? this.items.map((it) => h("button", { class: "g3d-album-thumb", type: "button", onclick: () => this.showBig(it) }, h("img", { src: it.src, alt: `photo by ${it.by}`, loading: "lazy" })))
        : [h("p", { class: "g3d-invite-note" }, isGuest ? "no photos here yet ♡" : "no photos yet. use the 📷 camera or the tripod ⏱ ♡")]),
    );
    this.wallView.hidden = false;
    this.ctx.setControls(false);
  }
  showBig(it) {
    const { h, isGuest, toast } = this.ctx;
    this.grid.hidden = true;
    this.viewer.hidden = false;
    this.viewer.replaceChildren(
      h("img", { class: "g3d-gallery-img g3d-photo-img", src: it.src, alt: "" }),
      h("p", { class: "g3d-invite-note" }, `taken by ${it.by || "one of you"} · ${new Date(it.at).toLocaleDateString()}`),
      h("div", { class: "g3d-gallery-actions" },
        h("button", { class: "g3d-big-btn g3d-big-btn-soft", type: "button", onclick: () => this.openWall() }, "← all photos"),
        isGuest
          ? null
          : h("button", { class: "g3d-big-btn g3d-big-btn-soft", type: "button", onclick: () => {
              this.removeItem(it.id);
              toast("taken down ♡");
              this.openWall();
            } }, "take it down"),
      ),
    );
  }
  closeWall() {
    this.wallView.hidden = true;
    this.ctx.setControls(true);
  }

  isOpen() {
    return !this.wallView.hidden || !this.preview.hidden;
  }
  closeOverlays() {
    this.wallView.hidden = true;
    this.preview.hidden = true;
  }

  update(t) {
    this.updateHeart(t);
    this.checkMoved();
    if (this.recLight) this.recLight.material.color.set(this.counting && Math.floor(t * 4) % 2 ? "#ff3b5c" : this.counting ? "#5a1020" : "#ff3b5c");
  }

  destroy() {
    for (const el of [this.camUI, this.flash, this.preview, this.wallView, this.countEl]) el.remove();
  }
}

const imgCache = new Map();
function loadImg(src) {
  if (!imgCache.has(src)) {
    imgCache.set(
      src,
      new Promise((res, rej) => {
        const img = new Image();
        img.onload = () => res(img);
        img.onerror = rej;
        img.src = src;
      }),
    );
  }
  return imgCache.get(src);
}
