export const colorKey = (group) => (group === "skin" ? "skin" : `${group}Color`);

export function loadAvatar() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || "null");
    if (saved && typeof saved === "object") return { ...DEFAULT_AVATAR, ...saved };
  } catch {}
  return { ...DEFAULT_AVATAR };
}

export function saveAvatar(config) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
  } catch {}
}

const BODY = {
  regular: { w: 1, limb: 1, leg: 1, depth: 1, torsoH: 1 },
  slim: { w: 0.84, limb: 0.82, leg: 1.02, depth: 0.9, torsoH: 1 },
  chubby: { w: 1.32, limb: 1.22, leg: 0.9, depth: 1.3, torsoH: 0.98 },
  tall: { w: 0.94, limb: 0.94, leg: 1.28, depth: 0.95, torsoH: 1.1 },
};

const matCache = new Map();
function mat(color, extra = {}) {
  const key = color + JSON.stringify(extra);
  if (!matCache.has(key)) {
    matCache.set(
      key,
      new THREE.MeshStandardMaterial({ color, flatShading: true, roughness: 0.82, metalness: 0, ...extra }),
    );
  }
  return matCache.get(key);
}

const capsule = (r, len) => new THREE.CapsuleGeometry(r, len, 2, 7);

function mesh(geo, material, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, material);
  m.position.set(x, y, z);
  m.castShadow = true;
  return m;
}

// ---- hair builders --------------------------------------------------------
function hairCap(r, m, coverage = 0.56) {
  const cap = mesh(new THREE.SphereGeometry(r * 1.07, 10, 7, 0, Math.PI * 2, 0, Math.PI * coverage), m);
  cap.rotation.x = -0.32;
  cap.position.y = r * 0.04;
  return cap;
}

const HAIR = {
  bald() {},
  short(g, r, m) {
    g.add(hairCap(r, m));
  },
  bob(g, r, m) {
    const open = Math.PI * 2 * 0.3;
    const shell = mesh(
      new THREE.SphereGeometry(r * 1.13, 10, 7, Math.PI / 2 + open / 2, Math.PI * 2 - open, 0, Math.PI * 0.7),
      m,
    );
    shell.position.y = r * 0.02;
    m.side = THREE.DoubleSide;
    g.add(shell, hairCap(r, m, 0.5));
  },
  long(g, r, m) {
    m.side = THREE.DoubleSide;
    g.add(hairCap(r, m));
    const curtain = mesh(new THREE.CylinderGeometry(r * 1.06, r * 1.22, r * 1.9, 14, 1, true, Math.PI * 0.42, Math.PI * 1.16), m, 0, -r * 0.6, -r * 0.05);
    g.add(curtain);
    // soft wavy ends
    for (let i = 0; i < 7; i++) {
      const a = Math.PI * 0.45 + (i / 6) * Math.PI * 1.1;
      g.add(mesh(new THREE.IcosahedronGeometry(r * 0.26, 1), m, Math.sin(a) * r * 1.1, -r * 1.5, Math.cos(a) * r * 1.1 - r * 0.05));
    }
    for (const s of [-1, 1]) {
      const lock = mesh(new THREE.CapsuleGeometry(r * 0.17, r * 1.0, 2, 8), m, s * r * 0.95, -r * 0.55, r * 0.22);
      lock.rotation.z = s * 0.06;
      g.add(lock);
    }
  },
  bun(g, r, m) {
    g.add(hairCap(r, m));
    g.add(mesh(new THREE.IcosahedronGeometry(r * 0.42, 1), m, 0, r * 0.92, -r * 0.42));
  },
  ponytail(g, r, m) {
    g.add(hairCap(r, m));
    const tail = mesh(new THREE.ConeGeometry(r * 0.3, r * 1.5, 6), m, 0, -r * 0.1, -r * 1.15);
    tail.rotation.x = -2.6;
    g.add(tail);
    g.add(mesh(new THREE.IcosahedronGeometry(r * 0.2, 0), m, 0, r * 0.45, -r * 0.95));
  },
  curly(g, r, m) {
    g.add(hairCap(r, m, 0.5));
    const geo = new THREE.IcosahedronGeometry(r * 0.32, 0);
    const n = 26;
    for (let i = 0; i < n; i++) {
      const y = 1 - (i / (n - 1)) * 1.3;
      if (y < -0.25) continue;
      const rad = Math.sqrt(Math.max(0, 1 - y * y));
      const a = i * 2.399;
      const x = Math.cos(a) * rad;
      const z = Math.sin(a) * rad;
      if (z > 0.55 && y < 0.55) continue; // keep the face clear
      g.add(mesh(geo, m, x * r * 1.05, y * r * 1.05 + r * 0.05, z * r * 1.05 - r * 0.05));
    }
  },
  buzz(g, r, m) {
    const cap = hairCap(r * 0.97, m, 0.5);
    cap.position.y = r * 0.02;
    g.add(cap);
  },
  messy(g, r, m) {
    g.add(hairCap(r, m));
    const geo = new THREE.IcosahedronGeometry(r * 0.24, 0);
    const spots = [[0, 1, 0.2], [0.4, 0.9, 0.35], [-0.4, 0.9, 0.3], [0.2, 0.95, -0.25], [-0.25, 0.92, -0.2], [0.55, 0.7, 0.1], [-0.55, 0.72, 0.05], [0, 0.8, 0.6]];
    for (const [x, y, z] of spots) {
      const c = mesh(geo, m, x * r, y * r, z * r);
      c.rotation.set(x * 2, y * 3, z * 2);
      g.add(c);
    }
  },
  quiff(g, r, m) {
    g.add(hairCap(r, m, 0.5));
    const front = mesh(new THREE.CapsuleGeometry(r * 0.3, r * 0.7, 3, 8), m, 0, r * 0.95, r * 0.42);
    front.rotation.z = Math.PI / 2;
    front.rotation.x = -0.5;
    g.add(front);
    g.add(mesh(new THREE.IcosahedronGeometry(r * 0.3, 1), m, 0, r * 1.02, r * 0.1));
  },
  sidepart(g, r, m) {
    g.add(hairCap(r, m));
    const sweep = mesh(new THREE.SphereGeometry(r * 1.1, 10, 6, 0, Math.PI, 0, Math.PI * 0.42), m, 0, r * 0.06, r * 0.02);
    sweep.rotation.set(-0.35, Math.PI / 2, 0.18);
    g.add(sweep);
  },
  spiky(g, r, m) {
    g.add(hairCap(r, m));
    const geo = new THREE.ConeGeometry(r * 0.22, r * 0.75, 4);
    const dirs = [
      [0, 1, -0.1], [0.5, 0.8, 0], [-0.5, 0.8, 0], [0.3, 0.75, -0.55], [-0.3, 0.75, -0.55],
      [0, 0.6, -0.8], [0.25, 0.85, 0.4], [-0.25, 0.85, 0.4],
    ];
    for (const d of dirs) {
      const v = new THREE.Vector3(...d).normalize();
      const c = mesh(geo, m);
      c.position.copy(v.clone().multiplyScalar(r * 1.05));
      c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), v);
      g.add(c);
    }
  },
};

// ---- accessory builders ---------------------------------------------------
const ACCESSORY = {
  none() {},
  glasses(head, r, a) {
    const m = mat(a.accent === "#fff7f2" ? "#2b2633" : a.accent);
    const ring = new THREE.TorusGeometry(r * 0.2, r * 0.035, 4, 12);
    for (const s of [-1, 1]) head.add(mesh(ring, m, s * r * 0.33, r * 0.02, r * 0.95));
    head.add(mesh(new THREE.BoxGeometry(r * 0.22, r * 0.04, r * 0.04), m, 0, r * 0.05, r * 0.98));
  },
  cap(head, r, a) {
    const m = mat(a.accent);
    const dome = mesh(new THREE.SphereGeometry(r * 1.12, 10, 5, 0, Math.PI * 2, 0, Math.PI / 2), m, 0, r * 0.12, 0);
    dome.rotation.x = -0.15;
    const brim = mesh(new THREE.CylinderGeometry(r * 0.75, r * 0.75, r * 0.07, 10, 1, false, 0, Math.PI), m, 0, r * 0.32, r * 0.55);
    brim.rotation.y = -Math.PI / 2;
    brim.rotation.x = 0.12;
    head.add(dome, brim);
  },
  bow(head, r, a) {
    const m = mat(a.accent);
    const g = new THREE.Group();
    g.position.set(r * 0.62, r * 0.78, r * 0.05);
    g.rotation.z = -0.5;
    const lobe = new THREE.ConeGeometry(r * 0.26, r * 0.42, 4);
    for (const s of [-1, 1]) {
      const c = mesh(lobe, m, s * r * 0.2, 0, 0);
      c.rotation.z = s * Math.PI / 2;
      g.add(c);
    }
    g.add(mesh(new THREE.IcosahedronGeometry(r * 0.1, 0), m));
    head.add(g);
  },
  headphones(head, r, a) {
    const m = mat(a.accent);
    const band = mesh(new THREE.TorusGeometry(r * 1.12, r * 0.07, 4, 14, Math.PI), m);
    band.rotation.z = 0;
    band.position.y = r * 0.05;
    head.add(band);
    for (const s of [-1, 1]) {
      const cup = mesh(new THREE.CylinderGeometry(r * 0.26, r * 0.26, r * 0.18, 10), m, s * r * 1.08, r * 0.0, 0);
      cup.rotation.z = Math.PI / 2;
      head.add(cup);
    }
  },
  catEars(head, r, a) {
    const m = mat(a.hairColor);
    const inner = mat("#f7a8c4");
    for (const s of [-1, 1]) {
      const ear = mesh(new THREE.ConeGeometry(r * 0.28, r * 0.5, 4), m, s * r * 0.55, r * 0.95, -r * 0.05);
      ear.rotation.z = -s * 0.35;
      const e2 = mesh(new THREE.ConeGeometry(r * 0.16, r * 0.32, 4), inner, s * r * 0.55, r * 0.95, r * 0.06);
      e2.rotation.z = -s * 0.35;
      head.add(ear, e2);
    }
  },
  crown(head, r) {
    const m = mat("#ffd166", { metalness: 0.4, roughness: 0.4, emissive: "#5a3a00", emissiveIntensity: 0.3 });
    const g = new THREE.Group();
    g.position.set(0, r * 1.0, -r * 0.05);
    g.rotation.x = -0.15;
    g.add(mesh(new THREE.CylinderGeometry(r * 0.5, r * 0.55, r * 0.22, 10, 1, true), m));
    for (let i = 0; i < 5; i++) {
      const ang = (i / 5) * Math.PI * 2;
      g.add(mesh(new THREE.ConeGeometry(r * 0.1, r * 0.3, 4), m, Math.cos(ang) * r * 0.5, r * 0.24, Math.sin(ang) * r * 0.5));
    }
    m.side = THREE.DoubleSide;
    head.add(g);
  },
  flower(head, r, a) {
    const g = new THREE.Group();
    g.position.set(-r * 0.75, r * 0.6, r * 0.25);
    const petal = mat(a.accent);
    for (let i = 0; i < 5; i++) {
      const ang = (i / 5) * Math.PI * 2;
      g.add(mesh(new THREE.IcosahedronGeometry(r * 0.13, 0), petal, Math.cos(ang) * r * 0.15, Math.sin(ang) * r * 0.15, 0));
    }
    g.add(mesh(new THREE.IcosahedronGeometry(r * 0.1, 0), mat("#ffd166")));
    head.add(g);
  },
  sunglasses(head, r) {
    const m = mat("#1d1820", { roughness: 0.2, metalness: 0.3 });
    for (const s of [-1, 1]) {
      const lens = mesh(new THREE.BoxGeometry(r * 0.42, r * 0.28, r * 0.06), m, s * r * 0.31, r * 0.04, r * 0.97);
      lens.rotation.y = s * 0.18;
      head.add(lens);
    }
    head.add(mesh(new THREE.BoxGeometry(r * 0.2, r * 0.05, r * 0.05), m, 0, r * 0.1, r * 1.0));
  },
  beret(head, r, a) {
    const m = mat(a.accent);
    const cap = mesh(new THREE.CylinderGeometry(r * 0.95, r * 0.8, r * 0.26, 14), m, -r * 0.12, r * 0.86, -r * 0.05);
    cap.rotation.z = 0.28;
    cap.rotation.x = -0.12;
    head.add(cap, mesh(new THREE.CylinderGeometry(r * 0.05, r * 0.07, r * 0.14, 6), m, -r * 0.22, r * 1.06, -r * 0.05));
  },
  starclips(head, r, a) {
    const m = mat(a.accent, { emissive: a.accent, emissiveIntensity: 0.25 });
    const star = new THREE.OctahedronGeometry(r * 0.13, 0);
    for (const [x, y, z] of [[0.62, 0.62, 0.4], [0.42, 0.78, 0.5], [-0.62, 0.62, 0.4]]) {
      const st = mesh(star, m, x * r, y * r, z * r);
      st.scale.set(1, 1, 0.45);
      st.rotation.z = Math.PI / 4;
      head.add(st);
    }
  },
  halo(head, r) {
    const m = mat("#fff2b0", { emissive: "#ffe27a", emissiveIntensity: 1.2 });
    const h = mesh(new THREE.TorusGeometry(r * 0.55, r * 0.06, 4, 16), m, 0, r * 1.45, 0);
    h.rotation.x = Math.PI / 2;
    h.castShadow = false;
    head.add(h);
  },
  // the scarf and chain live on the neck, not the head
  scarf() {},
  chain() {},
  backcap(head, r, a) {
    ACCESSORY.cap(head, r, a);
    for (const k of head.children.slice(-2)) {
      k.position.z *= -1;
      k.rotation.y += Math.PI;
      k.rotation.x *= -1;
    }
  },
  beanie(head, r, a) {
    const m = mat(a.accent);
    const dome = mesh(new THREE.SphereGeometry(r * 1.1, 12, 6, 0, Math.PI * 2, 0, Math.PI * 0.52), m, 0, r * 0.08, -r * 0.02);
    dome.rotation.x = -0.2;
    const fold = mesh(new THREE.TorusGeometry(r * 1.02, r * 0.11, 5, 16), mat(shadeHex(a.accent, 0.82)), 0, r * 0.22, r * 0.04);
    fold.rotation.x = Math.PI / 2 - 0.2;
    head.add(dome, fold, mesh(new THREE.IcosahedronGeometry(r * 0.2, 1), mat("#fff7f2"), 0, r * 1.18, -r * 0.2));
  },
  bandana(head, r, a) {
    const m = mat(a.accent);
    const band = mesh(new THREE.TorusGeometry(r * 1.02, r * 0.08, 4, 16), m, 0, r * 0.45, 0);
    band.rotation.x = Math.PI / 2 - 0.25;
    head.add(band);
    for (const s of [-1, 1]) {
      const tail = mesh(new THREE.BoxGeometry(r * 0.12, r * 0.4, r * 0.05), m, s * r * 0.12, r * 0.25, -r * 1.02);
      tail.rotation.z = s * 0.4;
      head.add(tail);
    }
  },
  bunny(head, r) {
    const white = mat("#fff7f2");
    const pink = mat("#f7a8c4");
    for (const s of [-1, 1]) {
      const ear = new THREE.Group();
      ear.position.set(s * r * 0.38, r * 0.85, -r * 0.08);
      ear.rotation.z = -s * 0.22;
      ear.rotation.x = -0.12;
      head.add(ear);
      ear.add(mesh(new THREE.CapsuleGeometry(r * 0.17, r * 0.95, 3, 10), white, 0, r * 0.6, 0));
      const inner = mesh(new THREE.CapsuleGeometry(r * 0.09, r * 0.7, 3, 8), pink, 0, r * 0.6, r * 0.1);
      inner.scale.z = 0.4;
      ear.add(inner);
      // one ear flops a little
      if (s > 0) ear.rotation.z -= 0.35;
    }
  },
};

export class Avatar {
  constructor(config = loadAvatar()) {
    this.root = new THREE.Group();
    this.root.name = "avatar";
    this.t = Math.random() * 10;
    this.phase = 0;
    this.walk = 0;
    this.run = 0;
    this.air = 0;
    this.emote = null;
    this.emoteTime = 0;
    this.emoteWeight = 0;
    this.landT = 0;
    this.blinkIn = 2;
    this.build(config);
  }

  setConfig(config) {
    this.root.remove(this.body);
    this.body.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
    });
    this.build(config);
  }

  build(config) {
    this.config = { ...DEFAULT_AVATAR, ...config };
    const c = this.config;
    const b = BODY[c.body] || BODY.regular;
    const skin = mat(c.skin);
    const top = mat(c.topColor);
    const bottom = mat(c.bottomColor);
    const shoes = mat(c.shoesColor);
    const hairM = mat(c.hairColor);
    const isDress = c.top === "dress";
    const skirtish = isDress || c.bottom === "skirt";

    const thigh = 0.27 * b.leg;
    const shin = 0.25 * b.leg;
    const legR = 0.075 * b.limb;
    const hipY = thigh + shin + 0.07;
    const torsoW = 0.17 * b.w;
    const torsoH = 0.36 * b.torsoH;
    const headR = 0.31;
    const arm = 0.22;
    const fore = 0.2;
    const armR = 0.058 * b.limb;

    const body = new THREE.Group();
    this.body = body;
    this.root.add(body);
    this.dims = { hipY, headR, height: hipY + torsoH + headR * 2 + 0.05 };

    const hips = new THREE.Group();
    hips.position.y = hipY;
    body.add(hips);
    this.hips = hips;

    // pelvis
    const pelvis = mesh(new THREE.SphereGeometry(torsoW * 1.02, 8, 5), isDress ? top : c.bottom === "skirt" ? bottom : bottom, 0, 0.02, 0);
    pelvis.scale.set(1, 0.6, 0.75 * b.depth);
    hips.add(pelvis);

    // legs
    this.legs = [];
    for (const s of [1, -1]) {
      const leg = new THREE.Group();
      leg.position.set(s * torsoW * 0.5, -0.02, 0);
      const thighMat = skirtish || false ? skin : bottom;
      const shinMat = PANTS.has(c.bottom) && !isDress ? bottom : skin;
      leg.add(mesh(capsule(legR, thigh - legR), isDress ? skin : c.bottom === "skirt" ? skin : thighMat, 0, -thigh / 2, 0));
      const knee = new THREE.Group();
      knee.position.y = -thigh;
      knee.add(mesh(capsule(legR * 0.92, shin - legR), shinMat, 0, -shin / 2, 0));
      const shoe = mesh(new THREE.BoxGeometry(legR * 2.3, 0.08, legR * 3.4), shoes, 0, -shin - 0.02, legR * 0.6);
      knee.add(shoe);
      if (!isDress && (c.bottom === "jeans" || c.bottom === "joggers")) {
        // rolled cuffs / elastic ankles
        knee.add(mesh(new THREE.CylinderGeometry(legR * 1.08, legR * 1.12, 0.05, 8), mat(shadeHex(c.bottomColor, c.bottom === "jeans" ? 1.25 : 0.75)), 0, -shin + 0.06, 0));
      }
      if (!isDress && c.bottom === "cargo") leg.add(mesh(new THREE.BoxGeometry(0.03, 0.1, 0.09), mat(shadeHex(c.bottomColor, 0.85)), s * legR * 1.02, -thigh * 0.55, 0));
      if (!isDress && c.bottom === "jeans") leg.add(mesh(new THREE.BoxGeometry(legR * 2.05, 0.012, 0.012), mat(shadeHex(c.bottomColor, 1.3)), 0, -thigh * 0.2, legR * 0.92));
      leg.add(knee);
      hips.add(leg);
      this.legs.push({ leg, knee });
    }

    if (c.accessory === "bunny") {
      const tail = mesh(new THREE.IcosahedronGeometry(0.1, 1), mat("#fff7f2"), 0, 0.04, -torsoW * 0.95 * b.depth);
      hips.add(tail);
      this.bunnyTail = tail;
    } else this.bunnyTail = null;

    if (skirtish) {
      const len = isDress ? thigh * 1.15 : thigh * 0.95;
      const skirt = mesh(new THREE.CylinderGeometry(torsoW * 0.95, torsoW * 1.7, len, 9, 1, true), isDress ? top : bottom, 0, -len / 2 + 0.05, 0);
      skirt.material.side = THREE.DoubleSide;
      skirt.scale.z = 0.85 * b.depth;
      hips.add(skirt);
    }

    // spine + torso
    const spine = new THREE.Group();
    spine.position.y = 0.02;
    hips.add(spine);
    this.spine = spine;
    const torso = mesh(capsule(torsoW, torsoH - torsoW * 0.6), top, 0, torsoH / 2, 0);
    torso.scale.z = 0.78 * b.depth;
    spine.add(torso);
    this.torso = torso;

    if (c.top === "hoodie") {
      const hood = mesh(new THREE.TorusGeometry(torsoW * 0.75, 0.06, 5, 10), top, 0, torsoH - 0.02, -0.06);
      hood.rotation.x = Math.PI / 2.4;
      spine.add(hood);
      spine.add(mesh(new THREE.BoxGeometry(torsoW * 1.1, 0.09, 0.03), mat(shadeHex(c.topColor, 0.85)), 0, torsoH * 0.32, torsoW * 0.8 * b.depth));
      for (const s of [-1, 1]) spine.add(mesh(new THREE.CylinderGeometry(0.008, 0.008, 0.12, 4), mat("#fff7f2"), s * 0.04, torsoH - 0.1, torsoW * 0.78 * b.depth));
    }
    if (c.top === "shirt") {
      for (const s of [-1, 1]) {
        const flap = mesh(new THREE.BoxGeometry(0.09, 0.02, 0.07), mat("#fff7f2"), s * 0.05, torsoH - 0.02, torsoW * 0.62 * b.depth);
        flap.rotation.set(0.5, 0, s * 0.5);
        spine.add(flap);
      }
      for (let k = 0; k < 3; k++) spine.add(mesh(new THREE.SphereGeometry(0.012, 5, 4), mat("#fff7f2"), 0, torsoH * (0.72 - k * 0.2), torsoW * 0.8 * b.depth));
      spine.add(mesh(new THREE.BoxGeometry(0.06, 0.05, 0.01), mat(shadeHex(c.topColor, 0.82)), torsoW * 0.45, torsoH * 0.7, torsoW * 0.78 * b.depth));
    }
    if (c.top === "jacket") {
      // open jacket over a white tee
      spine.add(mesh(new THREE.BoxGeometry(torsoW * 0.62, torsoH * 0.8, 0.02), mat("#fff7f2"), 0, torsoH * 0.5, torsoW * 0.79 * b.depth));
      for (const s of [-1, 1]) {
        const lapel = mesh(new THREE.BoxGeometry(0.05, torsoH * 0.5, 0.015), mat(shadeHex(c.topColor, 0.8)), s * torsoW * 0.36, torsoH * 0.62, torsoW * 0.82 * b.depth);
        lapel.rotation.z = s * 0.25;
        spine.add(lapel);
      }
      const collar = mesh(new THREE.TorusGeometry(torsoW * 0.62, 0.04, 4, 10, Math.PI * 1.3), mat(shadeHex(c.topColor, 0.85)), 0, torsoH - 0.02, -0.01);
      collar.rotation.set(Math.PI / 2, 0, Math.PI * 0.85);
      spine.add(collar);
    }
    if (c.top === "jersey") {
      for (const y of [0.35, 0.5]) {
        const band = mesh(new THREE.TorusGeometry(torsoW * 0.98, 0.012, 3, 14), mat("#fff7f2"), 0, torsoH * y, 0);
        band.rotation.x = Math.PI / 2;
        band.scale.y = 0.78 * b.depth;
        spine.add(band);
      }
      spine.add(mesh(new THREE.BoxGeometry(0.1, 0.12, 0.01), mat("#fff7f2"), 0, torsoH * 0.62, -torsoW * 0.8 * b.depth));
    }
    if (c.top === "vest") {
      const v = mesh(new THREE.ConeGeometry(0.05, 0.12, 3), mat("#fff7f2"), 0, torsoH - 0.07, torsoW * 0.8 * b.depth);
      v.rotation.z = Math.PI;
      spine.add(v);
    }
    if (c.accessory === "chain") {
      const gold = mat("#ffd166", { metalness: 0.6, roughness: 0.3 });
      const ch = mesh(new THREE.TorusGeometry(torsoW * 0.58, 0.012, 3, 14), gold, 0, torsoH - 0.06, 0.02);
      ch.rotation.x = Math.PI / 2 - 0.5;
      spine.add(ch, mesh(new THREE.OctahedronGeometry(0.03, 0), gold, 0, torsoH - 0.16, torsoW * 0.8 * b.depth));
    }
    if (c.top === "sweater") {
      const collar = mesh(new THREE.TorusGeometry(torsoW * 0.55, 0.035, 4, 10), mat(shadeHex(c.topColor, 0.85)), 0, torsoH - 0.01, 0);
      collar.rotation.x = Math.PI / 2;
      spine.add(collar);
    }
    if (c.accessory === "scarf") {
      const sc = mat(c.accentColor);
      const ring = mesh(new THREE.TorusGeometry(torsoW * 0.62, 0.055, 5, 10), sc, 0, torsoH + 0.01, 0);
      ring.rotation.x = Math.PI / 2;
      spine.add(ring, mesh(new THREE.BoxGeometry(0.08, 0.2, 0.04), sc, torsoW * 0.35, torsoH - 0.12, torsoW * 0.75));
    }

    // arms
    this.arms = [];
    const sleeveUpper = c.top === "tank" ? skin : c.top === "vest" ? mat("#fff7f2") : top;
    const sleeveFore = c.top === "hoodie" || c.top === "sweater" || c.top === "shirt" || c.top === "jacket" ? top : c.top === "vest" ? mat("#fff7f2") : skin;
    for (const s of [1, -1]) {
      const shoulder = new THREE.Group();
      shoulder.position.set(s * (torsoW + armR * 0.6), torsoH - 0.06, 0);
      shoulder.add(mesh(capsule(armR, arm - armR), sleeveUpper, 0, -arm / 2, 0));
      const elbow = new THREE.Group();
      elbow.position.y = -arm;
      elbow.add(mesh(capsule(armR * 0.9, fore - armR), sleeveFore, 0, -fore / 2, 0));
      elbow.add(mesh(new THREE.IcosahedronGeometry(armR * 1.2, 0), skin, 0, -fore, 0));
      shoulder.add(elbow);
      spine.add(shoulder);
      this.arms.push({ shoulder, elbow, side: s });
    }

    // head
    const neck = new THREE.Group();
    neck.position.y = torsoH;
    spine.add(neck);
    const head = new THREE.Group();
    head.position.y = headR * 0.92;
    neck.add(head);
    this.head = head;
    const skull = mesh(new THREE.SphereGeometry(headR, 12, 9), skin);
    skull.scale.set(1.04, 0.96, 1);
    head.add(skull);

    const eyeMat = mat("#2b1d24", { roughness: 0.3 });
    const glint = new THREE.MeshBasicMaterial({ color: "#ffffff" });
    this.eyes = [];
    const face = c.face || "cute";
    for (const s of [-1, 1]) {
      // happy and wink eyes are little ^ arcs; the rest are round
      const arc = face === "happy" || (face === "wink" && s === 1);
      let eye;
      if (arc) {
        eye = mesh(new THREE.TorusGeometry(headR * 0.11, headR * 0.03, 4, 10, Math.PI), eyeMat, s * headR * 0.33, -headR * 0.02, headR * 0.9);
        eye.userData.arc = true;
      } else {
        eye = mesh(new THREE.SphereGeometry(headR * 0.13, 8, 6), eyeMat, s * headR * 0.33, headR * 0.0, headR * 0.86);
        eye.scale.set(1, 1.25, 0.5);
        eye.userData.k = face === "sleepy" ? 0.4 : 1;
        const dot = new THREE.Mesh(new THREE.SphereGeometry(headR * 0.045, 6, 4), glint);
        dot.position.set(headR * 0.035, headR * 0.05, headR * 0.1);
        eye.add(dot);
      }
      eye.castShadow = false;
      head.add(eye);
      this.eyes.push(eye);
      if (c.cheeks === "freckles") {
        const fm = new THREE.MeshBasicMaterial({ color: shadeHex(c.skin, 0.62) });
        for (const [dx, dy] of [[0, 0], [0.09, 0.05], [0.1, -0.06], [-0.07, -0.03]]) {
          const dot = new THREE.Mesh(new THREE.CircleGeometry(headR * 0.028, 6), fm);
          dot.position.set(s * headR * (0.5 + dx), -headR * (0.16 + dy), headR * 0.86);
          dot.rotation.y = s * 0.5;
          head.add(dot);
        }
      } else if (c.cheeks !== "none") {
        const blush = new THREE.Mesh(
          new THREE.CircleGeometry(headR * 0.13, 10),
          new THREE.MeshBasicMaterial({ color: "#ff8fb1", transparent: true, opacity: 0.55, depthWrite: false }),
        );
        blush.position.set(s * headR * 0.56, -headR * 0.2, headR * 0.81);
        blush.rotation.y = s * 0.55;
        head.add(blush);
      }
    }
    const mouth = mesh(new THREE.TorusGeometry(headR * 0.1, headR * 0.025, 4, 8, Math.PI), mat("#7a2e3e"), 0, -headR * 0.28, headR * 0.94);
    mouth.rotation.z = Math.PI;
    mouth.castShadow = false;
    head.add(mouth);
    this.mouth = mouth;

    (HAIR[c.hair] || HAIR.short)(head, headR, hairM);
    (ACCESSORY[c.accessory] || ACCESSORY.none)(head, headR, { accent: c.accentColor, hairColor: c.hairColor });
  }

  playEmote(name) {
    this.emote = name;
    this.lastEmote = name;
    this.emoteTime = 0;
  }

  // a small squat when landing from a jump
  land(strength = 1) {
    this.landT = Math.min(1, Math.max(this.landT || 0, strength));
  }

  // speed: horizontal m/s, airborne: bool, vy: vertical speed
  update(dt, speed, airborne, vy = 0) {
    const lerp = THREE.MathUtils.lerp;
    const clamp = THREE.MathUtils.clamp;
    this.t += dt;
    const t = this.t;
    const k = 1 - Math.exp(-dt * 10);
    this.walk += (clamp(speed / 3, 0, 1) - this.walk) * k;
    this.run += (clamp((speed - 3.6) / 2.4, 0, 1) - this.run) * k;
    this.air += ((airborne ? 1 : 0) - this.air) * (1 - Math.exp(-dt * 16));
    this.landT = Math.max(0, (this.landT || 0) - dt * 4.5);
    if (speed > 0.6 && this.emote && this.emote !== "heart" && this.emote !== "kiss") this.emote = null;

    // stride: about 1.4 steps cycles a second walking, 2 running
    const cycles = speed > 0.05 ? 0.75 + speed * 0.2 : 0;
    this.phase += dt * cycles * Math.PI * 2;
    const p = this.phase;
    const air = this.air;
    const w = this.walk * (1 - air);
    const r = this.run * (1 - air);
    const up = clamp(vy / 5, -1, 1);
    const falling = airborne ? Math.max(0, -up) : 0;
    const { hipY } = this.dims;
    const thighAmp = 0.5 * w + 0.3 * r;

    this.legs.forEach(({ leg, knee }, i) => {
      const ph = p + (i ? Math.PI : 0);
      let lx = -Math.sin(ph) * thighAmp;
      let kx = Math.max(0, Math.sin(ph - 1.1)) * (0.75 * w + 0.95 * r) + 0.06 * w;
      // in the air one knee tucks up and the other trails, opening out on the way down
      lx = lerp(lx, i === 0 ? lerp(-1.05, -0.35, falling) : lerp(0.4, 0.12, falling), air);
      kx = lerp(kx, i === 0 ? lerp(1.55, 0.4, falling) : lerp(0.55, 0.25, falling), air);
      lx -= this.landT * 0.55;
      kx += this.landT * 1.0;
      leg.rotation.set(lx, 0, (i ? -1 : 1) * 0.03);
      knee.rotation.x = kx;
    });

    const bounce = Math.abs(Math.cos(p));
    const breathe = Math.sin(t * 2.2) * 0.012 * (1 - this.walk);
    this.torso.scale.y = 1 + breathe;
    this.hips.position.y = hipY + bounce * (0.035 * w + 0.055 * r) - r * 0.035 - this.landT * 0.12;
    this.hips.rotation.y = Math.sin(p) * 0.1 * w;
    this.spine.rotation.x = r * 0.2 + air * (0.05 + falling * 0.1) + this.landT * 0.22;
    this.spine.rotation.y = -Math.sin(p) * 0.13 * (w + r * 0.5);
    this.spine.rotation.z = 0;
    this.head.rotation.y = Math.sin(t * 0.6) * 0.18 * (1 - this.walk);
    this.head.rotation.x = -this.spine.rotation.x * 0.6 + Math.sin(t * 1.3) * 0.03 * (1 - this.walk) - air * 0.1;
    this.head.rotation.z = 0;

    const armPose = this.arms.map(({ side }, i) => {
      const sw = Math.sin(p + (i ? 0 : Math.PI));
      let sx = -sw * (0.45 * w + 0.55 * r);
      let sz = side * (0.1 + 0.05 * r) + Math.sin(t * 2.2) * 0.02 * side * (1 - this.walk);
      let ex = -(0.15 + 0.15 * w + 1.1 * r);
      // arms reach up while rising and spread out for balance when falling
      sx = lerp(sx, lerp(-2.5, -0.5, falling), air);
      sz = lerp(sz, side * lerp(0.3, 1.15, falling), air);
      ex = lerp(ex, -0.25, air);
      sx -= this.landT * 0.45;
      return { sx, sz, ex, ez: 0 };
    });

    // a held photo pose works like an emote that never ends
    if (this.pose) {
      if (this.emote !== this.pose) {
        this.emote = this.pose;
        this.lastEmote = this.pose;
        this.emoteTime = 0;
      }
      this.emoteTime = Math.min(this.emoteTime, 1.2);
    } else if (this.emote && POSES.has(this.emote)) this.emote = null;
    // emotes blend over the movement pose
    let target = 0;
    if (this.emote) {
      this.emoteTime += dt;
      const len = POSES.has(this.emote) ? 99 : this.emote === "cuddle" ? 5 : this.emote === "kiss" ? 2.4 : this.emote === "dance" ? 4 : this.emote === "poop" ? 3.4 : this.emote === "hug" ? 2.8 : this.emote === "pet" ? 2.6 : this.emote === "heart" ? 2.4 : 2.2;
      target = this.emoteTime < len ? 1 : 0;
      if (this.emoteTime > len + 0.4) this.emote = null;
    }
    this.emoteWeight += (target - this.emoteWeight) * (1 - Math.exp(-dt * 9));
    const ew = this.emoteWeight;
    const et = this.emoteTime;
    const e = this.lastEmote;
    if (ew > 0.001 && e) {
      if (e === "wave") {
        const a = armPose[1];
        a.sx = lerp(a.sx, -0.2, ew);
        a.sz = lerp(a.sz, -2.6, ew);
        a.ex = lerp(a.ex, 0, ew);
        a.ez = lerp(a.ez, Math.sin(et * 11) * 0.55 - 0.3, ew);
        this.head.rotation.z = 0.12 * ew;
      } else if (e === "heart") {
        armPose.forEach((a) => {
          a.sx = lerp(a.sx, -1.15, ew);
          a.sz = lerp(a.sz, a.sz * 0.2 - Math.sign(a.sz) * 0.45, ew);
          a.ex = lerp(a.ex, -1.7, ew);
        });
        this.head.rotation.x = lerp(this.head.rotation.x, -0.15, ew);
        this.hips.position.y += Math.sin(et * 6) * 0.02 * ew;
      } else if (e === "hug") {
        // arms open, then wrap around
        const close = THREE.MathUtils.smoothstep(et, 0.25, 0.75);
        armPose.forEach((a) => {
          const side = Math.sign(a.sz || 1);
          a.sx = lerp(a.sx, -1.4, ew);
          a.sz = lerp(a.sz, side * lerp(1.0, 0.15, close), ew);
          a.ex = lerp(a.ex, lerp(-0.2, -1.1, close), ew);
          a.ez = lerp(a.ez, -side * 0.6 * close, ew);
        });
        this.spine.rotation.x = lerp(this.spine.rotation.x, 0.14 * close, ew);
        this.head.rotation.z = lerp(0, 0.22, close * ew);
        this.head.rotation.x = lerp(this.head.rotation.x, 0.08, ew);
        this.hips.rotation.y += Math.sin(et * 3) * 0.08 * close * ew;
      } else if (POSES.has(e)) {
        const L = armPose[0];
        const R = armPose[1];
        const set = (a, sx, sz, ex, ez = 0) => {
          a.sx = lerp(a.sx, sx, ew);
          a.sz = lerp(a.sz, sz, ew);
          a.ex = lerp(a.ex, ex, ew);
          a.ez = lerp(a.ez, ez, ew);
        };
        const hip = (a, side) => set(a, -0.25, side * 0.75, -1.7);
        if (e === "peace") {
          set(R, -2.35, -0.3, -1.35);
          hip(L, 1);
          this.head.rotation.z = 0.22 * ew;
        } else if (e === "hearthands") {
          // a heart with your hands, held up in front of your chest
          set(L, -1.2, -0.55, -1.25);
          set(R, -1.2, 0.55, -1.25);
          this.head.rotation.x = lerp(this.head.rotation.x, -0.1, ew);
        } else if (e === "blowkiss") {
          set(R, -1.5, 0.3, -2.2);
          hip(L, 1);
          this.spine.rotation.x = lerp(this.spine.rotation.x, 0.12, ew);
          this.head.rotation.z = 0.18 * ew;
          this.mouthKiss = ew;
        } else if (e === "shy") {
          set(L, -0.45, -0.38, -0.7);
          set(R, -0.45, 0.38, -0.7);
          this.head.rotation.x = lerp(this.head.rotation.x, 0.28, ew);
          this.head.rotation.z = 0.16 * ew;
          const leg = this.legs[0];
          leg.leg.rotation.z = lerp(leg.leg.rotation.z, -0.12, ew);
          leg.knee.rotation.x = lerp(leg.knee.rotation.x, 0.45, ew);
        } else if (e === "cheer") {
          set(L, -2.6, 0.55, -0.2);
          set(R, -2.6, -0.55, -0.2);
          this.hips.position.y += Math.abs(Math.sin(this.t * 5)) * 0.04 * ew;
          this.head.rotation.x = lerp(this.head.rotation.x, -0.18, ew);
        } else if (e === "halfR") {
          // the arm on your person's side arcs up and over toward them
          set(R, -0.35, -2.45, -0.2, -1.05);
          hip(L, 1);
          this.head.rotation.z = -0.15 * ew;
        } else if (e === "halfL") {
          set(L, -0.35, 2.45, -0.2, 1.05);
          hip(R, -1);
          this.head.rotation.z = 0.15 * ew;
        } else if (e === "crossed") {
          set(L, -1.3, -0.75, -1.9);
          set(R, -1.25, 0.75, -1.95);
          this.head.rotation.x = lerp(this.head.rotation.x, -0.12, ew);
          this.head.rotation.y = 0.35 * ew;
        }
      } else if (e === "kiss") {
        // lean in on tiptoes, hands behind the back, a little smooch
        const lean = THREE.MathUtils.smoothstep(et, 0.1, 0.6);
        this.spine.rotation.x = lerp(this.spine.rotation.x, 0.28 * lean, ew);
        this.head.rotation.x = lerp(this.head.rotation.x, -0.12, ew);
        this.head.rotation.z = lerp(0, 0.18, lean * ew);
        this.hips.position.y += 0.04 * lean * ew;
        armPose.forEach((a) => {
          a.sx = lerp(a.sx, 0.55, ew);
          a.sz = lerp(a.sz, Math.sign(a.sz || 1) * 0.22, ew);
          a.ex = lerp(a.ex, -1.2, ew);
        });
        const back = this.legs[1];
        back.leg.rotation.x = lerp(back.leg.rotation.x, 0.25, ew * lean);
        back.knee.rotation.x = lerp(back.knee.rotation.x, 1.4, ew * lean);
        this.mouthKiss = lean * ew;
      } else if (e === "cuddle") {
        // a long, slow, swaying squeeze
        const close = THREE.MathUtils.smoothstep(et, 0.2, 0.8);
        const sway = Math.sin(et * 2.2) * close;
        armPose.forEach((a) => {
          const side = Math.sign(a.sz || 1);
          a.sx = lerp(a.sx, -1.25, ew);
          a.sz = lerp(a.sz, side * lerp(1.0, 0.05, close), ew);
          a.ex = lerp(a.ex, lerp(-0.2, -1.45, close), ew);
          a.ez = lerp(a.ez, -side * 0.8 * close, ew);
        });
        this.spine.rotation.x = lerp(this.spine.rotation.x, 0.12 * close, ew);
        this.spine.rotation.z = sway * 0.12 * ew;
        this.hips.rotation.y += sway * 0.12 * ew;
        this.head.rotation.z = lerp(0, 0.35, close * ew) + sway * 0.05;
        this.head.rotation.x = lerp(this.head.rotation.x, 0.12, ew);
        this.hips.position.y -= 0.03 * close * ew;
      } else if (e === "pet") {
        // crouch down and stroke with one hand
        this.hips.position.y -= 0.16 * ew;
        this.spine.rotation.x = lerp(this.spine.rotation.x, 0.5, ew);
        this.legs.forEach(({ leg, knee }, i) => {
          leg.rotation.x = lerp(leg.rotation.x, i ? -0.5 : -1.2, ew);
          knee.rotation.x = lerp(knee.rotation.x, i ? 1.4 : 1.6, ew);
        });
        const r = armPose[1];
        r.sx = lerp(r.sx, -0.95 + Math.sin(et * 7) * 0.18, ew);
        r.sz = lerp(r.sz, -0.08, ew);
        r.ex = lerp(r.ex, -0.35, ew);
        const l = armPose[0];
        l.sx = lerp(l.sx, -0.7, ew);
        l.ex = lerp(l.ex, -0.9, ew);
        this.head.rotation.x = lerp(this.head.rotation.x, 0.25, ew);
      } else if (e === "poop") {
        // a deep squat, hands on knees, a little push
        this.hips.position.y -= 0.24 * ew;
        this.spine.rotation.x = lerp(this.spine.rotation.x, 0.45, ew);
        this.legs.forEach(({ leg, knee }, i) => {
          leg.rotation.x = lerp(leg.rotation.x, -1.45, ew);
          leg.rotation.z = (i ? -1 : 1) * 0.35 * ew;
          knee.rotation.x = lerp(knee.rotation.x, 2.2, ew);
        });
        armPose.forEach((a) => {
          a.sx = lerp(a.sx, -1.0, ew);
          a.sz = lerp(a.sz, Math.sign(a.sz || 1) * 0.25, ew);
          a.ex = lerp(a.ex, -0.8, ew);
        });
        const push = et > 0.6 && et < 1.4 ? 1 : 0;
        this.head.rotation.z = Math.sin(et * 40) * 0.05 * push * ew;
        this.head.rotation.x = lerp(this.head.rotation.x, -0.25, ew);
      } else if (e === "dance") {
        const beat = et * 7;
        armPose.forEach((a, i) => {
          a.sx = lerp(a.sx, -0.3, ew);
          a.sz = lerp(a.sz, Math.sign(a.sz || 1) * (2.2 + Math.sin(beat + i * Math.PI) * 0.7), ew);
          a.ex = lerp(a.ex, -0.4, ew);
        });
        this.hips.position.y += Math.abs(Math.sin(beat)) * 0.07 * ew;
        this.hips.rotation.y += Math.sin(beat * 0.5) * 0.5 * ew;
        this.spine.rotation.z = Math.sin(beat) * 0.15 * ew;
        this.head.rotation.z = Math.sin(beat) * 0.2 * ew;
        this.legs.forEach(({ leg, knee }, i) => {
          leg.rotation.z = (i ? -1 : 1) * Math.max(0, Math.sin(beat + i * Math.PI)) * 0.3 * ew;
          knee.rotation.x += Math.max(0, Math.sin(beat + i * Math.PI)) * 0.5 * ew;
        });
      }
    }

    // sitting on a bench, log, stool or bean bag
    this.sitW = (this.sitW || 0) + ((this.sitting ? 1 : 0) - (this.sitW || 0)) * (1 - Math.exp(-dt * 8));
    if (this.sitW > 0.01) {
      const sw = this.sitW;
      const target = (this.seatH || 0.45) + 0.05;
      this.hips.position.y = lerp(this.hips.position.y, target, sw);
      this.spine.rotation.x = lerp(this.spine.rotation.x, -0.06, sw);
      this.legs.forEach(({ leg, knee }, i) => {
        leg.rotation.x = lerp(leg.rotation.x, -1.5, sw);
        leg.rotation.z = (i ? -1 : 1) * 0.06 * sw;
        knee.rotation.x = lerp(knee.rotation.x, 1.5 + Math.sin(t * 1.6 + i * 2) * 0.12, sw);
      });
      armPose.forEach((a) => {
        // on the scooter: hands reach for the handlebars
        a.sx = lerp(a.sx, this.riding ? -1.2 : -0.55, sw);
        a.sz = lerp(a.sz, Math.sign(a.sz || 1) * (this.riding ? 0.22 : 0.12), sw);
        a.ex = lerp(a.ex, this.riding ? -0.25 : -0.85, sw);
      });
      this.head.rotation.y = Math.sin(t * 0.4) * (this.riding ? 0.08 : 0.3) * sw;
    }

    // holding the rifle up to aim
    this.aimW = (this.aimW || 0) + ((this.aiming ? 1 : 0) - (this.aimW || 0)) * (1 - Math.exp(-dt * 12));
    if (this.aimW > 0.01) {
      const aw = this.aimW;
      const ap = this.aimPitch || 0;
      const rA = armPose[1];
      rA.sx = lerp(rA.sx, -1.55 - ap, aw);
      rA.sz = lerp(rA.sz, -0.12, aw);
      rA.ex = lerp(rA.ex, 0, aw);
      rA.ez = lerp(rA.ez, 0, aw);
      const lA = armPose[0];
      lA.sx = lerp(lA.sx, -1.45 - ap, aw);
      lA.sz = lerp(lA.sz, -0.55, aw);
      lA.ex = lerp(lA.ex, -0.35, aw);
    }

    this.arms.forEach(({ shoulder, elbow }, i) => {
      const a = armPose[i];
      shoulder.rotation.set(a.sx, 0, a.sz);
      elbow.rotation.set(a.ex, 0, a.ez);
    });

    // blink
    this.blinkIn -= dt;
    let eyeY = 1.25;
    if (this.blinkIn < 0) {
      eyeY = 0.15;
      if (this.blinkIn < -0.12) this.blinkIn = 2 + Math.random() * 3;
    }
    if ((e === "heart" || e === "hug" || e === "pet" || e === "cuddle" || e === "kiss" || e === "blowkiss" || e === "shy") && ew > 0.5) eyeY = 0.3;
    // pucker for the kiss
    const pk = e === "kiss" || e === "blowkiss" ? this.mouthKiss || 0 : 0;
    this.mouth.scale.set(1 - pk * 0.55, 1 + pk * 0.4, 1);
    this.mouthKiss = 0;
    if (this.bunnyTail) this.bunnyTail.position.x = Math.sin(t * 8) * 0.015 * (this.walk + 0.3);
    // sleepy eyes stay half shut; arcs blink by squashing flat
    this.eyes.forEach((eye) => (eye.scale.y = eye.userData.arc ? eyeY / 1.25 : Math.min(eyeY, 1.25 * eye.userData.k)));
  }
}

