// The floating island: terrain, sky, decor and every room. Room shells are
// built at start; their furniture is built the first time the player comes
// near (lazy rooms), so start-up stays fast.
import * as THREE from "three";
import { mergeGeometries as mergeRaw } from "three/examples/jsm/utils/BufferGeometryUtils.js";
const mergeGeometries = (geos) => mergeRaw(geos.map((g) => (g.index ? g.toNonIndexed() : g)));
import { texture, textCanvas, FONT, wrapText } from "./textures.js";

export const ISLAND_R = 50;
const UP = new THREE.Vector3(0, 1, 0);
const matCache = new Map();
export function std(color, opts = {}) {
  const key = color + (opts.map ? opts.map.uuid : "") + (opts.key || "");
  if (!opts.unique && matCache.has(key)) return matCache.get(key);
  const { key: _k, unique: _u, ...rest } = opts;
  const m = new THREE.MeshStandardMaterial({ color, flatShading: true, roughness: 0.88, metalness: 0, ...rest });
  if (!opts.unique) matCache.set(key, m);
  return m;
}

function add(parent, geo, material, x = 0, y = 0, z = 0, opts = {}) {
  const m = new THREE.Mesh(geo, material);
  m.position.set(x, y, z);
  if (opts.ry) m.rotation.y = opts.ry;
  if (opts.rx) m.rotation.x = opts.rx;
  if (opts.rz) m.rotation.z = opts.rz;
  if (opts.scale) m.scale.setScalar(opts.scale);
  m.castShadow = opts.cast !== false;
  m.receiveShadow = opts.receive !== false;
  parent.add(m);
  return m;
}

const box = (w, h, d) => new THREE.BoxGeometry(w, h, d);
const cyl = (rt, rb, h, s = 10) => new THREE.CylinderGeometry(rt, rb, h, s);

