  warm: new THREE.MeshStandardMaterial({ color: "#ffe6b0", emissive: "#ffb85c", emissiveIntensity: 0.4, flatShading: true }),
  pink: new THREE.MeshStandardMaterial({ color: "#ffd0e2", emissive: "#ff6fa5", emissiveIntensity: 0.5, flatShading: true }),
