// ---------------------------------------------------------------------------
export class World {
  constructor(scene, { lowEnd, reserved = [], fenceGaps = [] }) {
    this.scene = scene;
    this.lowEnd = lowEnd;
    this.reserved = reserved;
    this.fenceGaps = fenceGaps;
    this.solids = [];
    this.spookyCircles = [];
    // two canvases for the art studio, one each
    this.paintCanvases = [0, 1].map(() => {
      const c = document.createElement("canvas");
      c.width = c.height = 512;
      const x = c.getContext("2d");
      x.fillStyle = "#fffdf8";
      x.fillRect(0, 0, 512, 512);
      return c;
    });
    this.paintTextures = this.paintCanvases.map((c) => {
      const t = new THREE.CanvasTexture(c);
      t.colorSpace = THREE.SRGBColorSpace;
      return t;
    });
    this.segments = [];
    this.circles = [];
    this.interactables = [];
    this.rooms = new Map();
    this.animated = [];
    this.root = new THREE.Group();
    scene.add(this.root);
    this.time = 0;

    this.buildSky();
    this.buildIsland();
    for (const def of ROOMS) this.buildRoom(def);
    this.buildDecor();
    this.buildSpooky();
    this.buildParticles();
  }

  // ---- collision helpers --------------------------------------------------
  addWallSegment(ax, az, bx, bz, h = 4) {
    this.segments.push({ ax, az, bx, bz, h, room: this.buildingRoom || "" });
  }
  addCircle(x, z, r) {
    this.circles.push({ x, z, r });
  }

  // ---- sky ----------------------------------------------------------------
  buildSky() {
    const uniforms = {
      top: { value: new THREE.Color("#ffd6e7") },
      mid: { value: new THREE.Color("#ffeef5") },
      bottom: { value: new THREE.Color("#fff7fb") },
      sunDir: { value: new THREE.Vector3(0.4, 0.6, 0.3).normalize() },
      sunColor: { value: new THREE.Color("#fff3e0") },
      night: { value: 0 },
    };
    this.skyUniforms = uniforms;
    const sky = new THREE.Mesh(
      new THREE.SphereGeometry(450, 24, 16),
      new THREE.ShaderMaterial({
        uniforms,
        side: THREE.BackSide,
        depthWrite: false,
        fog: false,
        vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
        fragmentShader: `
          uniform vec3 top; uniform vec3 mid; uniform vec3 bottom; uniform vec3 sunDir; uniform vec3 sunColor; uniform float night;
          varying vec3 vDir;
          void main(){
            float h = vDir.y;
            vec3 col = h > 0.0 ? mix(mid, top, smoothstep(0.0, 0.65, h)) : mix(mid, bottom, smoothstep(0.0, -0.5, h));
            float s = max(dot(normalize(vDir), sunDir), 0.0);
            col += sunColor * (pow(s, 600.0) * 1.4 + pow(s, 12.0) * 0.18);
            gl_FragColor = vec4(col, 1.0);
          }`,
      }),
    );
    sky.renderOrder = -10;
    this.sky = sky;
    this.scene.add(sky);

    // stars for the night themes
    const n = this.lowEnd ? 400 : 900;
    const pos = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const v = new THREE.Vector3().randomDirection();
      v.y = Math.abs(v.y) * 0.9 + 0.05;
      v.normalize().multiplyScalar(400);
      pos.set([v.x, v.y, v.z], i * 3);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    this.stars = new THREE.Points(g, new THREE.PointsMaterial({ color: "#ffffff", size: 1.6, sizeAttenuation: false, transparent: true, opacity: 0, fog: false, depthWrite: false }));
    this.scene.add(this.stars);
  }

  // ---- island -------------------------------------------------------------
  buildIsland() {
    const grassTex = texture("grass", ["#9fd18b", "#7fbf7a"], 14);
    this.grassMat = std("#ffffff", { map: grassTex, key: "grass" });
    const top = new THREE.Mesh(new THREE.CircleGeometry(ISLAND_R, 64), this.grassMat);
    top.rotation.x = -Math.PI / 2;
    top.receiveShadow = true;
    this.root.add(top);

    // soil rim
    const rim = add(this.root, cyl(ISLAND_R, ISLAND_R - 1.5, 2.2, 48), std("#a8795a", { map: texture("stone", ["#b98a64", "#8a5a3c"], 3) }), 0, -1.12, 0, { cast: false });
    rim.material.side = THREE.DoubleSide;

    // rocky underside with a little noise, tapering to a point
    const under = new THREE.ConeGeometry(ISLAND_R - 1.5, 34, 28, 7, true);
    under.rotateX(Math.PI);
    const p = under.attributes.position;
    const v = new THREE.Vector3();
    for (let i = 0; i < p.count; i++) {
      v.fromBufferAttribute(p, i);
      const k = 1 + (Math.sin(v.x * 0.35) * Math.cos(v.z * 0.31) + Math.sin(v.y * 0.5 + v.x * 0.2)) * 0.07;
      if (v.y < 16.5) {
        v.x *= k;
        v.z *= k;
      }
      p.setXYZ(i, v.x, v.y, v.z);
    }
    under.computeVertexNormals();
    const underMesh = add(this.root, under, std("#ffffff", { map: texture("stone", ["#9c8a9a", "#6a5a72"], 4), key: "under" }), 0, -2.2 - 17, 0, { cast: false });
    this.underMat = underMesh.material;

    // crystals hanging under the island
    const crystal = new THREE.OctahedronGeometry(1, 0);
    for (let i = 0; i < 14; i++) {
      const a = (i / 14) * Math.PI * 2 + 0.3;
      const r = 12 + (i % 3) * 9;
      const c = add(this.root, crystal, glow.magic, Math.cos(a) * r, -8 - (i % 4) * 3.5 - (30 - r) * 0.4, Math.sin(a) * r, { cast: false });
      c.scale.set(0.7, 2.2, 0.7);
      this.animated.push((t) => (c.rotation.y = t * 0.3 + i));
    }

    // edge fence with a rope between the posts; gaps for the gate and the sky trail
    const postGeo = box(0.22, 1.1, 0.22);
    const posts = Math.round((Math.PI * 2 * 48.6) / 2.6);
    const woodMat = std("#ffffff", { map: texture("wood", ["#f0dcc8", "#d8bca0"]) });
    const gaps = [0, ...this.fenceGaps];
    const inGap = (a) => gaps.some((g) => Math.abs(Math.atan2(Math.sin(a - g), Math.cos(a - g))) < 0.035);
    const postInst = new THREE.InstancedMesh(postGeo, woodMat, posts);
    const ropeInst = new THREE.InstancedMesh(box(0.06, 0.06, 1), std("#f4e3d0"), posts);
    const mtx = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const one = new THREE.Vector3(1, 1, 1);
    let pi = 0;
    let ri = 0;
    const step = (Math.PI * 2) / posts;
    for (let i = 0; i < posts; i++) {
      const a = i * step;
      if (inGap(a)) continue;
      mtx.makeTranslation(Math.sin(a) * 48.6, 0.55, Math.cos(a) * 48.6);
      postInst.setMatrixAt(pi++, mtx);
      const b = a + step;
      if (inGap(b)) continue;
      const mid = a + step / 2;
      const len = 2 * 48.6 * Math.sin(step / 2);
      q.setFromAxisAngle(UP, mid + Math.PI / 2);
      mtx.compose(new THREE.Vector3(Math.sin(mid) * 48.55, 0.85, Math.cos(mid) * 48.55), q, new THREE.Vector3(1, 1, len));
      ropeInst.setMatrixAt(ri++, mtx);
    }
    void one;
    postInst.count = pi;
    ropeInst.count = ri;
    postInst.castShadow = true;
    this.root.add(postInst, ropeInst);
  }

  // ---- rooms --------------------------------------------------------------
  buildRoom(def) {
    const g = new THREE.Group();
    g.position.copy(def.pos);
    const len = Math.hypot(def.pos.x, def.pos.z);
    // every building faces the middle of the island
    g.rotation.y = len > 0.5 && def.id !== "diary" ? Math.atan2(-def.pos.x, -def.pos.z) : 0;
    this.root.add(g);
    g.updateMatrixWorld(true);
    const room = { def, group: g, walls: [], roof: null, interiorBuilt: false, radius: def.r || 5.2, inside: false, buildInterior: null };
    this.rooms.set(def.id, room);

    this.buildingRoom = def.id;
    if (def.kind === "pavilion" || def.kind === "tower") this.buildPavilion(room);
    if (def.kind === "hall") this.buildHall(room);
    this.buildingRoom = "";

    const builder = INTERIORS[def.id];
    if (builder) room.buildInterior = () => builder.call(this, room);

    // the name over the place
    const label = nameSprite();
    label.userData.draw(def.name);
    const h = def.kind === "tower" ? 10.5 : def.kind === "hall" ? 9.6 : def.kind === "pavilion" ? 7.4 : 4.2;
    label.position.set(0, h, 0);
    g.add(label);
    room.label = label;
    return room;
  }

  toWorld(room, x, y, z) {
    return new THREE.Vector3(x, y, z).applyMatrix4(room.group.matrixWorld);
  }

  // hexagonal (or round, for the tower) room with an open doorway in front
  buildPavilion(room) {
    const { def, group } = room;
    const R = room.radius;
    const sides = def.kind === "tower" ? 10 : 6;
    const H = def.kind === "tower" ? 5.5 : 3.3;
    room.wallH = H;
    const wallMatBase = std("#ffffff", { map: texture("plaster", [def.wall, shadeHex(def.wall, 0.92)], 1), key: def.id + "wall" });
    const trim = std(def.trim, { map: texture("wood", [def.trim, shadeHex(def.trim, 0.8)]) });

    // floor
    const floorTex = def.floor === "tiles" ? texture("tiles", ["#fff6ee", shadeHex(def.trim, 1.1)], 3) : texture("wood", ["#d9a77c", "#b98a64"], 2);
    const floor = add(group, cyl(R + 0.3, R + 0.5, 0.34, sides), std("#ffffff", { map: floorTex }), 0, -0.15, 0, { ry: Math.PI / sides });
    floor.receiveShadow = true;
    add(group, cyl(R * 0.55, R * 0.55, 0.02, 24), std("#ffffff", { map: texture("rug", [def.wall, def.trim]) }), 0, 0.035, 0, { cast: false });

    // walls
    const step = (Math.PI * 2) / sides;
    const vert = (i) => {
      const a = step / 2 + i * step - step; // side 0 centred on +z
      return new THREE.Vector3(Math.sin(a) * R, 0, Math.cos(a) * R);
    };
    const thick = 0.28;
    const doorW = 1.9;
    const doorH = 2.5;
    for (let i = 0; i < sides; i++) {
      const a = vert(i);
      const b = vert(i + 1);
      const mid = a.clone().add(b).multiplyScalar(0.5);
      const L = a.distanceTo(b) + thick * 0.5;
      const ang = Math.atan2(b.x - a.x, b.z - a.z) - Math.PI / 2;
      const normal = mid.clone().setY(0).normalize();
      const m = wallMatBase.clone();
      m.transparent = true;
      const wallGroup = new THREE.Group();
      wallGroup.position.copy(mid);
      wallGroup.rotation.y = ang;
      group.add(wallGroup);
      const pieces = [];
      if (i === 0) {
        const side = (L - doorW) / 2;
        pieces.push(add(wallGroup, box(side, H, thick), m, -(doorW + side) / 2, H / 2, 0));
        pieces.push(add(wallGroup, box(side, H, thick), m, (doorW + side) / 2, H / 2, 0));
        pieces.push(add(wallGroup, box(doorW, H - doorH, thick), m, 0, doorH + (H - doorH) / 2, 0));
        // door frame
        add(wallGroup, box(0.16, doorH, thick + 0.1), trim, -doorW / 2, doorH / 2, 0);
        add(wallGroup, box(0.16, doorH, thick + 0.1), trim, doorW / 2, doorH / 2, 0);
        add(wallGroup, box(doorW + 0.3, 0.18, thick + 0.12), trim, 0, doorH, 0);
        // collisions for both halves of the front wall
        const dir = b.clone().sub(a).normalize();
        const wa = a.clone().applyMatrix4(group.matrixWorld);
        const da = a.clone().add(dir.clone().multiplyScalar((L - doorW) / 2 - 0.05)).applyMatrix4(group.matrixWorld);
        const db = b.clone().sub(dir.clone().multiplyScalar((L - doorW) / 2 - 0.05)).applyMatrix4(group.matrixWorld);
        const wb = b.clone().applyMatrix4(group.matrixWorld);
        this.addWallSegment(wa.x, wa.z, da.x, da.z);
        this.addWallSegment(db.x, db.z, wb.x, wb.z);
      } else {
        pieces.push(add(wallGroup, box(L, H, thick), m, 0, H / 2, 0));
        // a glowing window on every other side
        if (i % 2 === 1 || sides > 6) {
          if (sides === 6 || i === 2 || i === 8) {
            add(wallGroup, box(1.1, 1.0, thick + 0.06), glow.warm, 0, H * 0.55, 0, { cast: false });
            add(wallGroup, box(1.3, 0.12, thick + 0.16), trim, 0, H * 0.55 - 0.56, 0);
            add(wallGroup, box(0.08, 1.0, thick + 0.1), trim, 0, H * 0.55, 0);
          }
        }
        const wa = a.clone().applyMatrix4(group.matrixWorld);
        const wb = b.clone().applyMatrix4(group.matrixWorld);
        this.addWallSegment(wa.x, wa.z, wb.x, wb.z);
      }
      // trim along the top
      add(wallGroup, box(L + 0.05, 0.16, thick + 0.12), trim, 0, H, 0);
      const worldNormal = normal.clone().applyQuaternion(group.quaternion);
      room.walls.push({ material: m, normal: worldNormal, group: wallGroup });
    }
    // corner posts
    for (let i = 0; i < sides; i++) {
      const v = vert(i);
      add(group, box(0.34, H + 0.1, 0.34), trim, v.x, (H + 0.1) / 2, v.z);
    }

    // roof
    const roofG = new THREE.Group();
    group.add(roofG);
    const roofH = def.kind === "tower" ? 3.6 : 2.6;
    const roofMat = std("#ffffff", { map: texture("shingles", [def.roof, shadeHex(def.roof, 0.7)], 3), key: def.id + "roof", side: THREE.DoubleSide });
    add(roofG, new THREE.ConeGeometry(R * 1.28, roofH, sides, 1, true), roofMat, 0, H + roofH / 2 + 0.05, 0, { ry: Math.PI / sides });
    const topper = add(roofG, new THREE.IcosahedronGeometry(0.35, 0), glow.pink, 0, H + roofH + 0.25, 0);
    this.animated.push((t) => (topper.rotation.y = t));
    room.roof = roofG;

    if (def.kind === "tower") {
      // clock face on the front
      const clock = add(group, cyl(1.1, 1.1, 0.12, 20), std("#fff8ec"), 0, H - 1.1, R + 0.05, { rx: Math.PI / 2 });
      const hand1 = add(group, box(0.08, 0.8, 0.04), std("#3a2a35"), 0, H - 1.1, R + 0.14);
      const hand2 = add(group, box(0.06, 0.55, 0.04), std("#3a2a35"), 0, H - 1.1, R + 0.16);
      hand1.geometry.translate(0, 0.35, 0);
      hand2.geometry.translate(0, 0.25, 0);
      void clock;
      this.animated.push(() => {
        const d = new Date();
        hand1.rotation.z = -((d.getMinutes() + d.getSeconds() / 60) / 60) * Math.PI * 2;
        hand2.rotation.z = -(((d.getHours() % 12) + d.getMinutes() / 60) / 12) * Math.PI * 2;
      });
    }

    // lanterns either side of the door
    for (const s of [-1, 1]) {
      const lx = s * 1.4;
      const lz = R * Math.cos(step / 2) + 0.35;
      add(group, box(0.26, 0.36, 0.26), glow.warm, lx, 2.25, lz, { cast: false });
      add(group, box(0.34, 0.06, 0.34), trim, lx, 2.46, lz);
      const sp = glowSprite("#ffc27a", 1.6);
      sp.position.set(lx, 2.25, lz + 0.05);
      group.add(sp);
    }
    // welcome mat
    add(group, box(1.6, 0.03, 0.9), std("#ffffff", { map: texture("fabric", [def.trim, "#fff3e8"]) }), 0, 0.02, R * Math.cos(step / 2) + 0.9, { cast: false });
  }

  // the big cottage in the middle: the diary itself
  buildHall(room) {
    const { def, group } = room;
    const W = 15;
    const D = 11;
    const H = 3.8;
    room.radius = 7.5;
    room.wallH = H;
    room.rect = { w: W, d: D };
    const wallMatBase = std("#ffffff", { map: texture("plaster", [def.wall, shadeHex(def.wall, 0.93)], 1), key: "hallwall" });
    const trim = std(def.trim, { map: texture("wood", ["#b98a64", "#8a5a3c"]) });
    add(group, box(W + 0.8, 0.34, D + 0.8), std("#ffffff", { map: texture("wood", ["#d9a77c", "#b98a64"], 3) }), 0, -0.15, 0);
    // porch steps in front
    add(group, box(4, 0.2, 1.6), std("#ffffff", { map: texture("wood", ["#d9a77c", "#b98a64"], 1) }), 0, -0.08, D / 2 + 1.2);

    const thick = 0.3;
    const doorW = 2.4;
    const doorH = 2.9;
    const walls = [
      { a: [-W / 2, D / 2], b: [W / 2, D / 2], n: [0, 1], door: true },
      { a: [W / 2, D / 2], b: [W / 2, -D / 2], n: [1, 0] },
      { a: [W / 2, -D / 2], b: [-W / 2, -D / 2], n: [0, -1] },
      { a: [-W / 2, -D / 2], b: [-W / 2, D / 2], n: [-1, 0] },
    ];
    for (const w of walls) {
      const a = new THREE.Vector3(w.a[0], 0, w.a[1]);
      const b = new THREE.Vector3(w.b[0], 0, w.b[1]);
      const mid = a.clone().add(b).multiplyScalar(0.5);
      const L = a.distanceTo(b) + thick;
      const m = wallMatBase.clone();
      m.transparent = true;
      const wg = new THREE.Group();
      wg.position.copy(mid);
      wg.rotation.y = Math.atan2(b.x - a.x, b.z - a.z) - Math.PI / 2;
      group.add(wg);
      if (w.door) {
        const side = (L - doorW) / 2;
        add(wg, box(side, H, thick), m, -(doorW + side) / 2, H / 2, 0);
        add(wg, box(side, H, thick), m, (doorW + side) / 2, H / 2, 0);
        add(wg, box(doorW, H - doorH, thick), m, 0, doorH + (H - doorH) / 2, 0);
        add(wg, box(0.2, doorH, thick + 0.1), trim, -doorW / 2, doorH / 2, 0);
        add(wg, box(0.2, doorH, thick + 0.1), trim, doorW / 2, doorH / 2, 0);
        add(wg, box(doorW + 0.4, 0.2, thick + 0.12), trim, 0, doorH, 0);
        this.addWallSegment(def.pos.x - W / 2, def.pos.z + D / 2, def.pos.x - doorW / 2, def.pos.z + D / 2);
        this.addWallSegment(def.pos.x + doorW / 2, def.pos.z + D / 2, def.pos.x + W / 2, def.pos.z + D / 2);
        for (const s of [-1, 1]) {
          add(wg, box(1.4, 1.1, thick + 0.06), glow.warm, s * 4.6, 1.9, 0, { cast: false });
          add(wg, box(1.6, 0.12, thick + 0.16), trim, s * 4.6, 1.3, 0);
          add(wg, box(0.08, 1.1, thick + 0.1), trim, s * 4.6, 1.9, 0);
          // flower boxes
          add(wg, box(1.6, 0.3, 0.4), trim, s * 4.6, 1.15, 0.35);
          for (let f = 0; f < 5; f++) add(wg, new THREE.IcosahedronGeometry(0.12, 0), std(["#ff8fb1", "#ffd166", "#b79be8"][f % 3]), s * 4.6 - 0.6 + f * 0.3, 1.4, 0.38);
        }
      } else {
        add(wg, box(L, H, thick), m, 0, H / 2, 0);
        // the back wall is the screen and bookshelves: one window, in the free corner
        const back = w.n[1] === -1;
        for (const off of back ? [5.6] : L > 12 ? [-4, 0, 4] : [-2.5, 2.5]) {
          add(wg, box(1.3, 1.1, thick + 0.06), glow.warm, off, 1.95, 0, { cast: false });
          add(wg, box(0.08, 1.1, thick + 0.1), trim, off, 1.95, 0);
        }
        this.addWallSegment(def.pos.x + w.a[0], def.pos.z + w.a[1], def.pos.x + w.b[0], def.pos.z + w.b[1]);
      }
      add(wg, box(L + 0.1, 0.2, thick + 0.14), trim, 0, H, 0);
      room.walls.push({ material: m, normal: new THREE.Vector3(w.n[0], 0, w.n[1]), group: wg });
    }
    for (const [x, z] of [[-W / 2, -D / 2], [W / 2, -D / 2], [-W / 2, D / 2], [W / 2, D / 2]]) add(group, box(0.4, H + 0.1, 0.4), trim, x, H / 2, z);

    // gabled roof: an extruded triangle
    const roofG = new THREE.Group();
    group.add(roofG);
    const shape = new THREE.Shape();
    const ov = 1.1;
    shape.moveTo(-(D / 2 + ov), 0);
    shape.lineTo(0, 3.6);
    shape.lineTo(D / 2 + ov, 0);
    shape.lineTo(-(D / 2 + ov), 0);
    const roofGeo = new THREE.ExtrudeGeometry(shape, { depth: W + 1.4, bevelEnabled: false });
    roofGeo.translate(0, 0, -(W + 1.4) / 2);
    roofGeo.rotateY(Math.PI / 2);
    const roofMat = std("#ffffff", { map: texture("shingles", [def.roof, shadeHex(def.roof, 0.7)], 0.25), key: "hallroof" });
    add(roofG, roofGeo, roofMat, 0, H + 0.1, 0);
    // chimney with a puff of smoke
    add(roofG, box(1, 2.4, 1), std("#ffffff", { map: texture("cobble", ["#c4a7a0", "#8a6f6a"]) }), 3.5, H + 2.6, -1.5);
    const smokeGeo = new THREE.IcosahedronGeometry(0.4, 0);
    const smokeMat = new THREE.MeshStandardMaterial({ color: "#ffffff", transparent: true, opacity: 0.6, flatShading: true });
    for (let i = 0; i < 4; i++) {
      const puff = new THREE.Mesh(smokeGeo, smokeMat);
      roofG.add(puff);
      this.animated.push((t) => {
        const k = ((t * 0.25 + i / 4) % 1);
        puff.position.set(3.5 + Math.sin(k * 6 + i) * 0.3, H + 4 + k * 3, -1.5 - k * 0.8);
        puff.scale.setScalar(0.5 + k * 1.3);
      });
    }
    // heart on the gable
    const heartShape = new THREE.Shape();
    heartShape.moveTo(0, -0.5);
    heartShape.bezierCurveTo(-0.9, 0.1, -0.4, 0.8, 0, 0.35);
    heartShape.bezierCurveTo(0.4, 0.8, 0.9, 0.1, 0, -0.5);
    const heart = add(group, new THREE.ExtrudeGeometry(heartShape, { depth: 0.15, bevelEnabled: false }), glow.pink, 0, H + 1.5, D / 2 + 0.85);
    this.animated.push((t) => heart.scale.setScalar(1 + Math.sin(t * 2.4) * 0.06));
    room.roof = roofG;

    for (const s of [-1, 1]) {
      add(group, box(0.3, 0.42, 0.3), glow.warm, s * 1.8, 2.6, D / 2 + 0.4, { cast: false });
      const sp = glowSprite("#ffc27a", 1.8);
      sp.position.set(s * 1.8, 2.6, D / 2 + 0.5);
      group.add(sp);
    }
  }

  // ---- decor --------------------------------------------------------------
  addSpookyCircle(x, z, r) {
    this.spookyCircles.push({ x, z, r });
  }

  isFree(x, z, r) {
    if (Math.hypot(x, z) > 46) return false;
    for (const q of this.reserved) if (Math.hypot(x - q.x, z - q.z) < q.r + r) return false;
    for (const def of ROOMS) {
      const rr = def.clear || (def.kind === "hall" ? 10 : def.kind === "deck" ? 6 : def.kind === "outdoor" ? 4 : (def.r || 5.2) + 2.6);
      if (Math.hypot(x - def.pos.x, z - def.pos.z) < rr + r) return false;
    }
    for (const p of this.pathPoints) if (Math.hypot(x - p.x, z - p.z) < 1.4 + r) return false;
    return true;
  }

  buildDecor() {
    // stepping stone paths from the plaza ring to every door
    this.pathPoints = [];
    const stones = [];
    const ringR = 12.5;
    for (let i = 0; i < 64; i++) {
      const a = (i / 64) * Math.PI * 2;
      stones.push(new THREE.Vector3(Math.sin(a) * ringR, 0, Math.cos(a) * ringR - 0.5));
    }
    for (const def of ROOMS) {
      if (def.id === "diary" || def.id === "plaza") continue;
      const len = Math.hypot(def.pos.x, def.pos.z);
      const dir = new THREE.Vector3(def.pos.x, 0, def.pos.z).normalize();
      const off = def.kind === "pavilion" || def.kind === "tower" ? (def.r || 5.2) + 1.6 : def.kind === "deck" ? 5.5 : 2.6;
      for (let d = ringR + 1.2; d < len - off; d += 1.25) stones.push(dir.clone().multiplyScalar(d));
    }
    for (let z = 4; z < ringR; z += 1.25) stones.push(new THREE.Vector3(0, 0, z));
    this.pathPoints = stones;
    const stoneGeo = cyl(0.42, 0.46, 0.1, 7);
    const stoneMesh = new THREE.InstancedMesh(stoneGeo, std("#ffffff", { map: texture("stone", ["#e8dcd6", "#c4b2ac"], 1) }), stones.length);
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const s = new THREE.Vector3();
    stones.forEach((p, i) => {
      q.setFromAxisAngle(UP, i * 1.7);
      const k = 0.85 + ((i * 37) % 10) / 30;
      s.set(k, 1, k);
      m.compose(new THREE.Vector3(p.x + Math.sin(i * 3.1) * 0.12, -0.035, p.z + Math.cos(i * 2.3) * 0.12), q, s);
      stoneMesh.setMatrixAt(i, m);
    });
    stoneMesh.receiveShadow = true;
    this.root.add(stoneMesh);

    const rand = mulberry(7);
    const place = (count, r, tries = 30) => {
      const out = [];
      for (let i = 0; i < count; i++) {
        for (let t = 0; t < tries; t++) {
          const a = rand() * Math.PI * 2;
          const d = Math.sqrt(rand()) * 45;
          const x = Math.sin(a) * d;
          const z = Math.cos(a) * d;
          if (this.isFree(x, z, r) && out.every((o) => Math.hypot(o.x - x, o.z - z) > r * 2)) {
            out.push({ x, z, k: 0.75 + rand() * 0.6, r: rand() * Math.PI * 2 });
            break;
          }
        }
      }
      return out;
    };

    // trees: round blossom trees and pines
    const trunkGeo = cyl(0.18, 0.28, 1.6, 6);
    trunkGeo.translate(0, 0.8, 0);
    const blobGeo = mergeGeometries([
      new THREE.IcosahedronGeometry(1.25, 0).translate(0, 2.4, 0),
      new THREE.IcosahedronGeometry(0.9, 0).translate(0.7, 2.0, 0.2),
      new THREE.IcosahedronGeometry(0.85, 0).translate(-0.6, 2.1, -0.3),
    ]);
    const pineGeo = mergeGeometries([
      new THREE.ConeGeometry(1.3, 1.6, 7).translate(0, 1.7, 0),
      new THREE.ConeGeometry(1.0, 1.4, 7).translate(0, 2.5, 0),
      new THREE.ConeGeometry(0.65, 1.2, 7).translate(0, 3.2, 0),
    ]);
    const trees = place(this.lowEnd ? 34 : 52, 1.6);
    const half = Math.floor(trees.length * 0.6);
    const trunks = new THREE.InstancedMesh(trunkGeo, std("#ffffff", { map: texture("wood", ["#8a5a3c", "#6a4430"]) }), trees.length);
    this.canopyMat = std("#ffb3cf", { key: "canopy" });
    this.pineMat = std("#5f9e74", { key: "pine" });
    const blobs = new THREE.InstancedMesh(blobGeo, this.canopyMat, half);
    const pines = new THREE.InstancedMesh(pineGeo, this.pineMat, trees.length - half);
    trees.forEach((t, i) => {
      q.setFromAxisAngle(UP, t.r);
      s.setScalar(t.k);
      m.compose(new THREE.Vector3(t.x, 0, t.z), q, s);
      trunks.setMatrixAt(i, m);
      if (i < half) blobs.setMatrixAt(i, m);
      else pines.setMatrixAt(i - half, m);
      this.addCircle(t.x, t.z, 0.4 * t.k);
    });
    for (const im of [trunks, blobs, pines]) {
      im.castShadow = true;
      im.receiveShadow = true;
      this.root.add(im);
    }
    this.treeSway = { blobs, pines };

    // rocks
    const rocks = place(26, 0.9);
    const rockMesh = new THREE.InstancedMesh(new THREE.DodecahedronGeometry(0.7, 0), std("#ffffff", { map: texture("stone", ["#d8ccd4", "#a898a8"], 1) }), rocks.length);
    rocks.forEach((r, i) => {
      q.setFromEuler(new THREE.Euler(r.r, r.r * 2, 0));
      s.set(r.k * 1.2, r.k * 0.7, r.k);
      m.compose(new THREE.Vector3(r.x, 0.15, r.z), q, s);
      rockMesh.setMatrixAt(i, m);
      this.addCircle(r.x, r.z, 0.7 * r.k);
    });
    rockMesh.castShadow = true;
    this.root.add(rockMesh);

    // flowers and grass tufts (no collision)
    const flowerCount = this.lowEnd ? 260 : 520;
    const flowerGeo = mergeGeometries([
      cyl(0.02, 0.02, 0.4, 3).translate(0, 0.2, 0),
      new THREE.IcosahedronGeometry(0.12, 0).translate(0, 0.42, 0),
    ]);
    const flowers = new THREE.InstancedMesh(flowerGeo, std("#ffffff", { key: "flower" }), flowerCount);
    const palette = ["#ff8fb1", "#ffd166", "#b79be8", "#fff7f2", "#ff6f91", "#8fd3f0"].map((c) => new THREE.Color(c));
    let fi = 0;
    for (let i = 0; i < flowerCount * 3 && fi < flowerCount; i++) {
      // flowers grow in little clusters
      const cx = (rand() - 0.5) * 92;
      const cz = (rand() - 0.5) * 92;
      if (!this.isFree(cx, cz, 0.2)) continue;
      const col = palette[Math.floor(rand() * palette.length)];
      for (let j = 0; j < 6 && fi < flowerCount; j++) {
        const x = cx + (rand() - 0.5) * 1.6;
        const z = cz + (rand() - 0.5) * 1.6;
        q.setFromAxisAngle(UP, rand() * 6);
        s.setScalar(0.7 + rand() * 0.6);
        m.compose(new THREE.Vector3(x, 0, z), q, s);
        flowers.setMatrixAt(fi, m);
        flowers.setColorAt(fi, col);
        fi++;
      }
    }
    flowers.count = fi;
    this.root.add(flowers);

    const tuftCount = this.lowEnd ? 500 : 1200;
    const tuftGeo = mergeGeometries([0, 1, 2].map((i) => new THREE.ConeGeometry(0.05, 0.35, 3).translate(Math.cos(i * 2.1) * 0.07, 0.17, Math.sin(i * 2.1) * 0.07)));
    this.tuftMat = std("#8cc77e", { key: "tuft" });
    const tufts = new THREE.InstancedMesh(tuftGeo, this.tuftMat, tuftCount);
    let ti = 0;
    for (let i = 0; i < tuftCount * 2 && ti < tuftCount; i++) {
      const a = rand() * Math.PI * 2;
      const d = Math.sqrt(rand()) * 46;
      const x = Math.sin(a) * d;
      const z = Math.cos(a) * d;
      if (!this.isFree(x, z, 0)) continue;
      q.setFromAxisAngle(UP, rand() * 6);
      s.setScalar(0.7 + rand() * 0.8);
      m.compose(new THREE.Vector3(x, 0, z), q, s);
      tufts.setMatrixAt(ti++, m);
    }
    tufts.count = ti;
    this.root.add(tufts);

    // lamp posts along the plaza ring
    const lampCount = 10;
    for (let i = 0; i < lampCount; i++) {
      const a = (i / lampCount) * Math.PI * 2 + 0.31;
      const x = Math.sin(a) * (ringR + 1.6);
      const z = Math.cos(a) * (ringR + 1.6) - 0.5;
      const lamp = new THREE.Group();
      lamp.position.set(x, 0, z);
      add(lamp, cyl(0.07, 0.1, 2.8, 6), std("#5b4a5a"), 0, 1.4, 0);
      add(lamp, new THREE.IcosahedronGeometry(0.26, 0), glow.warm, 0, 2.95, 0, { cast: false });
      const sp = glowSprite("#ffd08a", 2.2);
      sp.position.y = 2.95;
      lamp.add(sp);
      this.root.add(lamp);
      this.addCircle(x, z, 0.2);
    }

    // clouds around and below the island
    const cloudGeo = mergeGeometries([
      new THREE.IcosahedronGeometry(3, 0).translate(0, 0, 0),
      new THREE.IcosahedronGeometry(2.3, 0).translate(3, -0.4, 0.6),
      new THREE.IcosahedronGeometry(2.1, 0).translate(-3, -0.5, -0.4),
      new THREE.IcosahedronGeometry(1.8, 0).translate(1.2, 1.4, -0.8),
    ]);
    this.cloudMat = new THREE.MeshStandardMaterial({ color: "#ffffff", emissive: "#ffffff", emissiveIntensity: 0.35, flatShading: true, roughness: 1, transparent: true, opacity: 0.92 });
    const cloudCount = this.lowEnd ? 18 : 30;
    const clouds = new THREE.InstancedMesh(cloudGeo, this.cloudMat, cloudCount);
    const cloudData = [];
    for (let i = 0; i < cloudCount; i++) {
      cloudData.push({ a: rand() * Math.PI * 2, r: 65 + rand() * 90, y: -30 + rand() * 50, k: 0.8 + rand() * 1.6, sp: 0.004 + rand() * 0.01 });
    }
    this.root.add(clouds);
    this.animated.push((t) => {
      cloudData.forEach((c, i) => {
        const a = c.a + t * c.sp;
        q.setFromAxisAngle(UP, a);
        s.set(c.k * 1.4, c.k * 0.8, c.k);
        m.compose(new THREE.Vector3(Math.sin(a) * c.r, c.y + Math.sin(t * 0.2 + i) * 0.6, Math.cos(a) * c.r), q, s);
        clouds.setMatrixAt(i, m);
      });
      clouds.instanceMatrix.needsUpdate = true;
    });

    // tiny floating islets
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2 + 0.5;
      const r = 72 + (i % 2) * 18;
      const islet = new THREE.Group();
      add(islet, cyl(3.4, 3.4, 0.6, 9), this.grassMat, 0, 0, 0);
      add(islet, new THREE.ConeGeometry(3.3, 6, 9).rotateX(Math.PI), this.underMat, 0, -3.3, 0, { cast: false });
      if (i % 2 === 0) add(islet, blobGeo, this.canopyMat, 0, 0.3, 0, { scale: 0.8 });
      else add(islet, pineGeo, this.pineMat, 0, 0.3, 0, { scale: 0.7 });
      islet.position.set(Math.sin(a) * r, -4 + (i % 3) * 5, Math.cos(a) * r);
      this.root.add(islet);
      this.animated.push((t) => (islet.position.y = -4 + (i % 3) * 5 + Math.sin(t * 0.4 + i) * 1.2));
    }
  }

  buildParticles() {
    const n = this.lowEnd ? 160 : 320;
    const pos = new Float32Array(n * 3);
    const seed = new Float32Array(n);
    const rand = mulberry(99);
    for (let i = 0; i < n; i++) {
      const a = rand() * Math.PI * 2;
      const d = Math.sqrt(rand()) * 48;
      pos.set([Math.sin(a) * d, 0.3 + rand() * 6, Math.cos(a) * d], i * 3);
      seed[i] = rand() * 100;
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    g.setAttribute("seed", new THREE.BufferAttribute(seed, 1));
    this.particleUniforms = { time: { value: 0 }, color: { value: new THREE.Color("#ffb3cf") }, size: { value: 14 }, fall: { value: 1 } };
    const mat = new THREE.ShaderMaterial({
      uniforms: this.particleUniforms,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      vertexShader: `
        attribute float seed; uniform float time; uniform float size; uniform float fall; varying float vA;
        void main(){
          vec3 p = position;
          float t = time * 0.4 + seed;
          p.x += sin(t * 0.9 + seed) * 1.6;
          p.z += cos(t * 0.7 + seed * 1.3) * 1.6;
          p.y = mix(p.y + sin(t * 1.3) * 0.6, 6.5 - mod(time * 0.35 + seed, 6.5), fall);
          vA = 0.55 + 0.45 * sin(t * 3.0 + seed);
          vec4 mv = modelViewMatrix * vec4(p, 1.0);
          gl_PointSize = size * (12.0 / -mv.z);
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: `
        uniform vec3 color; varying float vA;
        void main(){ float d = length(gl_PointCoord - 0.5); if (d > 0.5) discard; gl_FragColor = vec4(color, (1.0 - d * 2.0) * vA); }`,
    });
    this.particles = new THREE.Points(g, mat);
    this.particles.frustumCulled = false;
    this.root.add(this.particles);
  }

  // ---- halloween (the dark red theme) --------------------------------------
  buildSpooky() {
    const g = new THREE.Group();
    g.visible = false;
    this.spooky = g;
    this.root.add(g);
    const rand = mulberry(31);
    const orange = std("#f07a1e", { key: "pumpkin" });
    const stem = std("#4e6b2e");
    const face = new THREE.MeshStandardMaterial({ color: "#ffd166", emissive: "#ffae3b", emissiveIntensity: 2.2, flatShading: true });
    const pumpkinGeo = new THREE.SphereGeometry(0.42, 10, 6);
    pumpkinGeo.scale(1.15, 0.8, 1.15);
    const eyeGeo = new THREE.ConeGeometry(0.08, 0.12, 3);
    const mouthGeo = box(0.26, 0.06, 0.04);
    const pumpkin = (x, z, s = 1, face2 = true) => {
      const p = new THREE.Group();
      p.position.set(x, 0.3 * s, z);
      p.scale.setScalar(s);
      p.rotation.y = Math.atan2(-x, -z) + (rand() - 0.5) * 0.6;
      add(p, pumpkinGeo, orange, 0, 0, 0);
      add(p, cyl(0.04, 0.06, 0.2, 5), stem, 0, 0.38, 0, { rz: 0.2 });
      if (face2) {
        for (const sx of [-1, 1]) add(p, eyeGeo, face, sx * 0.14, 0.08, 0.44, { rx: -0.2, cast: false });
        add(p, mouthGeo, face, 0, -0.1, 0.45, { cast: false });
        const sp = glowSprite("#ff9a3b", 1.4 * s);
        sp.position.set(0, 0, 0.4);
        p.add(sp);
      }
      g.add(p);
      this.addSpookyCircle?.(x, z, 0.45 * s);
    };
    // pumpkins by every door and along the plaza ring
    for (const def of ROOMS) {
      if (def.kind !== "pavilion" && def.kind !== "tower") continue;
      const len = Math.hypot(def.pos.x, def.pos.z);
      const dir = new THREE.Vector3(-def.pos.x / len, 0, -def.pos.z / len);
      const side = new THREE.Vector3(-dir.z, 0, dir.x);
      const front = def.pos.clone().add(dir.clone().multiplyScalar((def.r || 5.2) + 0.9));
      pumpkin(front.x + side.x * 2.2, front.z + side.z * 2.2, 0.9);
      pumpkin(front.x - side.x * 2.4, front.z - side.z * 2.4, 0.7, rand() > 0.4);
    }
    for (let i = 0; i < 14; i++) {
      const a = (i / 14) * Math.PI * 2 + 0.12;
      pumpkin(Math.sin(a) * 15.2, Math.cos(a) * 15.2 - 0.5, 0.55 + rand() * 0.5, rand() > 0.3);
    }
    pumpkin(2.6, 5.5, 1.3);
    pumpkin(-2.6, 5.6, 1.1);

    // gravestones and a few dead trees
    const stone = std("#ffffff", { map: texture("stone", ["#8a8494", "#5e5868"], 1) });
    for (let i = 0; i < 9; i++) {
      for (let t = 0; t < 20; t++) {
        const a = rand() * Math.PI * 2;
        const d = 18 + rand() * 26;
        const x = Math.sin(a) * d;
        const z = Math.cos(a) * d;
        if (!this.isFree(x, z, 1)) continue;
        const gs = new THREE.Group();
        gs.position.set(x, 0, z);
        gs.rotation.set(0, Math.atan2(-x, -z), (rand() - 0.5) * 0.25);
        add(gs, box(0.7, 0.9, 0.18), stone, 0, 0.45, 0);
        add(gs, cyl(0.35, 0.35, 0.18, 10, 1), stone, 0, 0.9, 0, { rx: Math.PI / 2 });
        add(gs, box(0.4, 0.06, 0.02), std("#3a3440"), 0, 0.6, 0.1, { cast: false });
        g.add(gs);
        break;
      }
    }
    const bark = std("#3a2e36");
    for (let i = 0; i < 6; i++) {
      for (let t = 0; t < 20; t++) {
        const a = rand() * Math.PI * 2;
        const d = 20 + rand() * 24;
        const x = Math.sin(a) * d;
        const z = Math.cos(a) * d;
        if (!this.isFree(x, z, 1.5)) continue;
        const tr = new THREE.Group();
        tr.position.set(x, 0, z);
        tr.rotation.y = rand() * 6;
        add(tr, cyl(0.1, 0.22, 2.6, 5), bark, 0, 1.3, 0);
        for (let b = 0; b < 4; b++) {
          const br = add(tr, cyl(0.03, 0.07, 1.1, 4), bark, 0, 1.6 + b * 0.3, 0);
          br.rotation.set(0, b * 1.7, 0.9);
          br.position.x = Math.cos(b * 1.7) * 0.35;
          br.position.z = -Math.sin(b * 1.7) * 0.35;
        }
        g.add(tr);
        break;
      }
    }

    // ghosts drifting about
    const ghostMat = new THREE.MeshStandardMaterial({ color: "#f4f0ff", emissive: "#b8a8ff", emissiveIntensity: 0.5, transparent: true, opacity: 0.82, flatShading: true });
    const ghostGeo = mergeGeometries([
      new THREE.SphereGeometry(0.45, 10, 7, 0, Math.PI * 2, 0, Math.PI / 2),
      new THREE.CylinderGeometry(0.45, 0.55, 0.7, 10, 1, true).translate(0, -0.35, 0),
    ]);
    const eye = std("#1d1424");
    for (let i = 0; i < 5; i++) {
      const gh = new THREE.Group();
      add(gh, ghostGeo, ghostMat, 0, 0, 0, { cast: false });
      for (const s of [-1, 1]) add(gh, new THREE.SphereGeometry(0.07, 6, 4), eye, s * 0.15, 0.1, 0.4, { cast: false }).scale.y = 1.5;
      add(gh, new THREE.SphereGeometry(0.06, 6, 4), eye, 0, -0.08, 0.42, { cast: false });
      g.add(gh);
      const r = 14 + i * 6;
      const sp = 0.08 + rand() * 0.06;
      const off = rand() * 6;
      this.animated.push((t) => {
        if (!g.visible) return;
        const a = off + t * sp * (i % 2 ? 1 : -1);
        gh.position.set(Math.sin(a) * r, 2.2 + Math.sin(t * 1.3 + i) * 0.4, Math.cos(a) * r);
        gh.rotation.y = a + (i % 2 ? Math.PI / 2 : -Math.PI / 2);
        gh.rotation.z = Math.sin(t * 2 + i) * 0.1;
      });
    }

    // bats circling the hall and the tower
    const batMat = std("#1d1424");
    const wingGeo = new THREE.BufferGeometry();
    wingGeo.setAttribute("position", new THREE.Float32BufferAttribute([0, 0, 0, 0.5, 0.05, 0.12, 0.42, 0, -0.18, 0, 0, 0, 0.42, 0, -0.18, 0.12, 0, -0.12], 3));
    wingGeo.computeVertexNormals();
    for (let i = 0; i < 10; i++) {
      const bat = new THREE.Group();
      add(bat, new THREE.SphereGeometry(0.1, 6, 4), batMat, 0, 0, 0, { cast: false });
      const wings = [];
      for (const s of [-1, 1]) {
        const w = new THREE.Mesh(wingGeo, new THREE.MeshStandardMaterial({ color: "#2a1f33", side: THREE.DoubleSide, flatShading: true }));
        w.scale.x = s;
        bat.add(w);
        wings.push(w);
      }
      g.add(bat);
      const cx = i < 6 ? 0 : 13.5;
      const cz = i < 6 ? -2 : -23.4;
      const r = 3 + rand() * 5;
      const h = 7 + rand() * 5;
      const sp = 0.8 + rand() * 0.8;
      const off = rand() * 6;
      this.animated.push((t) => {
        if (!g.visible) return;
        const a = off + t * sp;
        bat.position.set(cx + Math.sin(a) * r, h + Math.sin(t * 3 + i) * 0.5, cz + Math.cos(a) * r);
        bat.rotation.y = a + Math.PI / 2;
        const flap = Math.sin(t * 22 + i) * 0.9;
        wings[0].rotation.z = flap;
        wings[1].rotation.z = -flap;
      });
    }

    // a big orange moon
    const c = document.createElement("canvas");
    c.width = c.height = 128;
    const x = c.getContext("2d");
    const grd = x.createRadialGradient(64, 64, 20, 64, 64, 64);
    grd.addColorStop(0, "rgba(255,190,110,1)");
    grd.addColorStop(0.55, "rgba(255,150,70,0.95)");
    grd.addColorStop(0.62, "rgba(255,120,40,0.35)");
    grd.addColorStop(1, "rgba(255,100,30,0)");
    x.fillStyle = grd;
    x.fillRect(0, 0, 128, 128);
    const moon = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(c), fog: false, depthWrite: false, transparent: true }));
    moon.scale.setScalar(90);
    moon.position.set(-160, 150, -260);
    g.add(moon);
  }

  // ---- theme / lighting hooks --------------------------------------------
  applyPalette(p) {
    this.palette = p;
    this.skyUniforms.top.value.set(p.sky[0]);
    this.skyUniforms.mid.value.set(p.sky[1]);
    this.skyUniforms.bottom.value.set(p.sky[2]);
    this.skyUniforms.sunColor.value.set(p.sunDisc);
    this.skyUniforms.sunDir.value.copy(p.sunDir).normalize();
    this.stars.material.opacity = p.night * 0.9;
    this.grassMat.color.set(p.grassTint);
    this.tuftMat.color.set(p.tuft);
    this.canopyMat.color.set(p.canopy);
    this.pineMat.color.set(p.pine);
    this.cloudMat.color.set(p.cloud);
    this.cloudMat.emissive.set(p.cloud);
    this.cloudMat.emissiveIntensity = 0.35 * (1 - p.night * 0.7);
    this.underMat.color.set(p.under);
    this.particleUniforms.color.value.set(p.particle);
    this.particleUniforms.fall.value = p.petals ? 1 : 0;
    if (this.spooky) this.spooky.visible = Boolean(p.halloween);
    glow.warm.emissiveIntensity = 0.35 + p.night * 1.6;
    glow.pink.emissiveIntensity = 0.5 + p.night * 1.4;
    this.scene.traverse((o) => {
      if (o.userData.glow) o.material.opacity = 0.15 + p.night * 0.75;
    });
  }

  update(dt, playerPos, cameraPos) {
    this.time += dt;
    if (cameraPos) {
      for (const room of this.rooms.values()) {
        if (!room.label) continue;
        const d = room.group.position.distanceTo(playerPos);
        const target = d < 9 ? 0 : 1;
        const m = room.label.material;
        m.opacity += (target - m.opacity) * Math.min(1, dt * 6);
        room.label.visible = m.opacity > 0.02;
      }
    }
    const t = this.time;
    this.particleUniforms.time.value = t;
    for (const fn of this.animated) fn(t, dt);
    // build room furniture when the player first comes near
    for (const room of this.rooms.values()) {
      if (!room.interiorBuilt && room.buildInterior && room.group.position.distanceTo(playerPos) < 34) {
        room.interiorBuilt = true;
        room.buildInterior();
        if (this.palette) this.applyPalette(this.palette);
      }
    }
  }

  // a place to sit: local x/z in the room, the way you face, the seat height
  seat(room, [x, z], facing, h, label = "sit ♡") {
    const pos = this.toWorld(room, x, 0, z).setY(0);
    const f = room.group.rotation.y + facing;
    return this.interact(room, { id: `seat-${room.def.id}-${x}-${z}`, label, local: [x, 0, z], radius: 1.2, action: { type: "sit", seat: { pos, facing: f, h } } });
  }

  // ---- interactables -----------------------------------------------------
  interact(room, { id, label, local, radius = 2.2, action, screen, hit }) {
    const pos = this.toWorld(room, local[0], local[1] ?? 0, local[2]);
    const hits = [screen?.s?.mesh, hit].filter(Boolean);
    const item = { id, label, pos, radius, action, screen, room: room.def.id, hits };
    for (const m of hits) m.traverse((o) => (o.userData.item = item));
    this.interactables.push(item);
    return item;
  }
}

function mulberry(a) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shadeHex(hex, k) {
  const c = new THREE.Color(hex);
  c.multiplyScalar(k);
  c.r = Math.min(c.r, 1);
  c.g = Math.min(c.g, 1);
  c.b = Math.min(c.b, 1);
  return `#${c.getHexString()}`;
}

// a marker that bobs over every interactable
function marker(world, parent, x, y, z) {
  const m = add(parent, new THREE.OctahedronGeometry(0.16, 0), glow.pink, x, y, z, { cast: false });
  m.scale.y = 1.5;
  world.animated.push((t) => {
    m.position.y = y + Math.sin(t * 2.5 + x) * 0.12;
    m.rotation.y = t * 1.5;
  });
  return m;
}

function table(parent, w, d, h, woodMat, x, z, ry = 0) {
  const g = new THREE.Group();
  g.position.set(x, 0, z);
  g.rotation.y = ry;
  add(g, box(w, 0.12, d), woodMat, 0, h, 0);
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) add(g, box(0.1, h, 0.1), woodMat, sx * (w / 2 - 0.12), h / 2, sz * (d / 2 - 0.12));
  parent.add(g);
  return g;
}

function bookshelf(world, parent, x, z, ry, w = 2.2, h = 2.6) {
  const g = new THREE.Group();
  g.position.set(x, 0, z);
  g.rotation.y = ry;
  const wood = std("#ffffff", { map: texture("wood", ["#a8794f", "#7a5236"]) });
  add(g, box(w, h, 0.5), wood, 0, h / 2, 0);
  const colors = ["#e2557f", "#7b5cd6", "#6fa8e8", "#f6c453", "#8fd3b6", "#f29ac0", "#fff3e0"];
  const shelves = 4;
  const bookGeo = box(0.12, 0.42, 0.34);
  const count = shelves * Math.floor(w / 0.15);
  const books = new THREE.InstancedMesh(bookGeo, std("#ffffff", { key: "books" }), count);
  const m = new THREE.Matrix4();
  let i = 0;
  for (let s = 0; s < shelves; s++) {
    const y = 0.35 + s * (h / shelves);
    add(g, box(w - 0.1, 0.06, 0.46), wood, 0, y - 0.25, 0.04);
    for (let bx = -w / 2 + 0.15; bx < w / 2 - 0.15 && i < count; bx += 0.15) {
      const tall = 0.8 + ((i * 7) % 5) / 12;
      m.makeScale(1, tall, 1).setPosition(bx, y - 0.22 + 0.21 * tall, 0.1);
      books.setMatrixAt(i, m);
      books.setColorAt(i, new THREE.Color(colors[(i * 3) % colors.length]));
      i++;
    }
  }
  books.count = i;
  g.add(books);
  parent.add(g);
  void world;
  return g;
}

