    const onFace = (deg, w, h, y, style) => {
      const a = THREE.MathUtils.degToRad(deg);
      const screen = makeScreen(w, h, style);
      const frame = new THREE.Group();
      frame.position.set(Math.sin(a) * ap, y, Math.cos(a) * ap);
      frame.rotation.y = a + Math.PI;
      g.add(frame);
      add(frame, box(w + 0.16, h + 0.16, 0.06), wood, 0, 0, -0.05);
      frame.add(screen.mesh);
      marker(this, frame, 0, h / 2 + 0.38, 0.12);
      return { screen, x: Math.sin(a) * ap, z: Math.cos(a) * ap };
    };
    const dates = onFace(180, 2.6, 2.0, 2.15, { placeholder: "important dates", border: "#7cbf8e" });
    const love = onFace(216, 2.3, 1.7, 2.05, { placeholder: "together for", border: "#f29ac0" });
    this.interact(room, { id: "dates", label: "open important dates", local: [dates.x * 0.55, 0, dates.z * 0.55], radius: 1.9, action: { type: "focus", role: "dates", title: "📅 important dates" }, screen: { s: dates.screen, source: { type: "role", role: "dates" } } });
