      add(g, box(k, k, k), std(["#7b5cd6", "#6fa8e8", "#8fd3b6", "#f6c453", "#f29ac0"][i]), Math.sin(a) * 3.2, k / 2, Math.cos(a) * 3.2, { ry: a });
