    for (let k = 0; k < 4; k++) add(dresser, new THREE.IcosahedronGeometry(0.055, 0), std(["#ff8fb1", "#fff7f2", "#ffd166", "#f29ac0"][k]), -0.55 + Math.sin(k * 1.6) * 0.06, 1.38 + (k % 2) * 0.05, 0.1 + Math.cos(k * 1.6) * 0.06);
