  weather(room) {
    const g = room.group;
    const wood = std("#ffffff", { map: texture("wood", ["#d9a77c", "#b98a64"], 2) });
    add(g, cyl(4.5, 4.6, 0.3, 12), wood, 0, -0.13, 0);
    for (let i = 0; i < 18; i++) {
      const a = (i / 18) * Math.PI * 2;
      if (Math.abs(Math.sin(a / 2)) < 0.25) continue; // open on the path side
      add(g, box(0.12, 1.0, 0.12), wood, Math.sin(a) * 4.3, 0.55, Math.cos(a) * 4.3);
    }
    const railG = new THREE.Group();
    railG.rotation.y = -(Math.PI / 2 - 0.45);
    g.add(railG);
    add(railG, new THREE.TorusGeometry(4.3, 0.06, 3, 40, Math.PI * 2 - 0.9), wood, 0, 1.05, 0, { rx: -Math.PI / 2 });
    // weather vane
    const vane = new THREE.Group();
    vane.position.set(-1.6, 0, -1.2);
    g.add(vane);
    add(vane, cyl(0.06, 0.08, 3, 6), std("#5b4a5a"), 0, 1.5, 0);
    const head = new THREE.Group();
    head.position.y = 3.0;
    vane.add(head);
    add(head, box(1.2, 0.05, 0.05), std("#ffd166", { metalness: 0.5 }), 0, 0, 0);
    add(head, new THREE.ConeGeometry(0.12, 0.3, 4), std("#ffd166", { metalness: 0.5 }), 0.65, 0, 0, { rz: -Math.PI / 2 });
    add(head, box(0.05, 0.35, 0.35), std("#ffd166", { metalness: 0.5 }), -0.6, 0, 0, { ry: 0.78 });
    this.animated.push((t) => (head.rotation.y = Math.sin(t * 0.3) * 1.2 + t * 0.05));
    this.addCircle(...xz(this.toWorld(room, -1.6, 0, -1.2)), 0.3);
    // telescope
    const tel = new THREE.Group();
    tel.position.set(1.4, 0, -1.6);
    g.add(tel);
    for (let i = 0; i < 3; i++) add(tel, box(0.05, 1.2, 0.05), std("#5b4a5a"), Math.sin(i * 2.1) * 0.2, 0.58, Math.cos(i * 2.1) * 0.2, { rx: Math.cos(i * 2.1) * 0.25, rz: -Math.sin(i * 2.1) * 0.25 });
    add(tel, cyl(0.1, 0.16, 1.2, 10), std("#7b5cd6", { metalness: 0.4, roughness: 0.4 }), 0, 1.35, 0, { rx: 1.0 });
    this.addCircle(...xz(this.toWorld(room, 1.4, 0, -1.6)), 0.4);
    const screen = makeScreen(2.0, 1.3, { placeholder: "weather ☁", border: "#8fd3f0" });
    const board = new THREE.Group();
    board.position.set(0, 0, -3.2);
    g.add(board);
    add(board, box(0.1, 2.4, 0.1), wood, -1.12, 1.2, -0.06);
    add(board, box(0.1, 2.4, 0.1), wood, 1.12, 1.2, -0.06);
    add(board, box(2.2, 1.5, 0.08), wood, 0, 1.85, -0.1);
    screen.mesh.position.set(0, 1.85, 0.0);
    board.add(screen.mesh);
    marker(this, board, 0, 2.95, 0);
    this.addCircle(...xz(this.toWorld(room, 0, 0, -3.2)), 0.5);
    this.interact(room, { id: "weather", label: "check the weather", local: [0, 0, -2.2], radius: 2.2, action: { type: "focus", role: "weather", title: "☁️ weather" }, screen: { s: screen, source: { type: "role", role: "weather" } } });
  },

  heart(room) {
    const g = room.group;
    const wood = std("#ffffff", { map: texture("wood", ["#e8b4a0", "#c48a78"]) });
    // bench
    const bench = new THREE.Group();
    bench.position.set(0, 0, -0.6);
    g.add(bench);
    for (let i = 0; i < 3; i++) add(bench, box(2.2, 0.08, 0.16), wood, 0, 0.5, -0.2 + i * 0.2);
    for (let i = 0; i < 3; i++) add(bench, box(2.2, 0.14, 0.06), wood, 0, 0.75 + i * 0.2, -0.38, { rx: -0.1 });
    for (const s of [-1, 1]) {
      add(bench, box(0.08, 0.5, 0.5), std("#5b4a5a"), s * 1.0, 0.25, 0);
      add(bench, box(0.08, 0.6, 0.08), std("#5b4a5a"), s * 1.0, 0.85, -0.4);
    }
    // heart arch of flowers
    const curve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(-1.6, 0, -1.3), new THREE.Vector3(-1.9, 2.0, -1.3), new THREE.Vector3(-1.1, 3.1, -1.3),
      new THREE.Vector3(0, 2.5, -1.3), new THREE.Vector3(1.1, 3.1, -1.3), new THREE.Vector3(1.9, 2.0, -1.3), new THREE.Vector3(1.6, 0, -1.3),
    ]);
    add(g, new THREE.TubeGeometry(curve, 40, 0.08, 5), std("#7fbf7a"));
    for (let i = 0; i <= 24; i++) {
      const p = curve.getPoint(i / 24);
      add(g, new THREE.IcosahedronGeometry(0.14, 0), std(["#ff8fb1", "#fff7f2", "#ff6f91"][i % 3]), p.x, p.y, p.z + 0.05, { cast: false });
    }
    // jar of hearts
    const jar = new THREE.Group();
    jar.position.set(1.6, 0, 0.3);
    g.add(jar);
    add(jar, cyl(0.25, 0.25, 0.6, 6), std("#ffffff"), 0, 0.3, 0);
    add(jar, cyl(0.3, 0.3, 0.55, 10), std("#e8f8ff", { transparent: true, opacity: 0.35 }), 0, 0.92, 0);
    for (let i = 0; i < 8; i++) add(jar, new THREE.IcosahedronGeometry(0.07, 0), glow.pink, Math.sin(i * 2.4) * 0.16, 0.7 + (i % 4) * 0.1, Math.cos(i * 2.4) * 0.16, { cast: false });
    const screen = makeScreen(1.8, 1.1, { placeholder: "i miss you ♡", border: "#ff8fb1" });
    screen.mesh.position.set(0, 3.7, -1.3);
    g.add(screen.mesh);
    marker(this, g, 0, 1.6, -0.6);
    this.addCircle(...xz(this.toWorld(room, 0, 0, -0.7)), 1.1);
    this.addCircle(...xz(this.toWorld(room, 1.6, 0, 0.3)), 0.35);
    this.seat(room, [-0.5, -0.55], 0, 0.5, "sit on the bench");
    this.seat(room, [0.5, -0.55], 0, 0.5, "sit on the bench");
    this.interact(room, { id: "missyou", label: "open i miss you", local: [0, 0, 0.6], radius: 2.0, action: { type: "focus", role: "miss-you", title: "💗 i miss you" }, screen: { s: screen, source: { type: "role", role: "miss-you" } } });
  },

  wishlist(room) {
    const g = room.group;
    const stone = std("#ffffff", { map: texture("cobble", ["#d8ccd4", "#9a8a98"]) });
    add(g, cyl(1.2, 1.3, 0.9, 10), stone, 0, 0.45, 0);
    add(g, cyl(1.0, 1.0, 0.05, 16), std("#6fb6e8", { roughness: 0.15, metalness: 0.1 }), 0, 0.7, 0);
    const wood = std("#ffffff", { map: texture("wood", ["#a8794f", "#7a5236"]) });
    for (const s of [-1, 1]) add(g, box(0.15, 2.2, 0.15), wood, s * 1.05, 1.1, 0);
    add(g, new THREE.ConeGeometry(1.7, 0.9, 4), std("#ffffff", { map: texture("shingles", ["#7b5cd6", "#5b3ca6"], 1) }), 0, 2.6, 0, { ry: Math.PI / 4 });
    add(g, cyl(0.06, 0.06, 2.1, 6), wood, 0, 1.9, 0, { rz: Math.PI / 2 });
    const bucket = add(g, cyl(0.2, 0.15, 0.3, 8), wood, 0, 1.3, 0);
    this.animated.push((t) => (bucket.position.y = 1.3 + Math.sin(t * 0.8) * 0.1));
    // wish tags on a string
    for (let i = 0; i < 7; i++) {
      const tag = add(g, box(0.18, 0.28, 0.02), std(["#ff8fb1", "#ffd166", "#b79be8", "#8fd3f0"][i % 4]), -0.9 + i * 0.3, 2.0 - Math.sin((i / 6) * Math.PI) * 0.15, 0.2, { cast: false });
      this.animated.push((t) => (tag.rotation.z = Math.sin(t * 1.6 + i) * 0.2));
    }
    const sp = glowSprite("#a8d8ff", 2.4);
    sp.position.y = 0.8;
    g.add(sp);
    // sign with the wishlist
    const screen = makeScreen(1.6, 1.4, { placeholder: "wishlist ⋆", border: "#b79be8" });
    const sign = new THREE.Group();
    sign.position.set(2.0, 0, 0.6);
    sign.rotation.y = -0.4;
    g.add(sign);
    add(sign, box(0.1, 1.0, 0.1), wood, -0.75, 0.5, -0.06);
    add(sign, box(0.1, 1.0, 0.1), wood, 0.75, 0.5, -0.06);
    add(sign, box(1.75, 1.55, 0.06), wood, 0, 1.75, -0.06);
    screen.mesh.position.set(0, 1.75, 0);
    sign.add(screen.mesh);
    marker(this, g, 0, 3.4, 0);
    this.addCircle(room.def.pos.x, room.def.pos.z, 1.35);
    this.addCircle(...xz(this.toWorld(room, 2.0, 0, 0.6)), 0.3);
    this.interact(room, { id: "wishlist", label: "make a wish (wishlist)", local: [0, 0, 1.6], radius: 2.2, action: { type: "focus", role: "wishlist", title: "🌠 wishlist" }, screen: { s: screen, source: { type: "role", role: "wishlist" } } });
  },

