// Island life: cats (one follows you), bunnies, stray deer and a boy who
// wanders between the rooms. All low-poly, all procedural.
import * as THREE from "three";
import { textCanvas, FONT } from "./textures.js";

const matCache = new Map();
function mat(color) {
  if (!matCache.has(color)) matCache.set(color, new THREE.MeshStandardMaterial({ color, flatShading: true, roughness: 0.9 }));
  return matCache.get(color);
}
function part(parent, geo, color, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, typeof color === "string" ? mat(color) : color);
  m.position.set(x, y, z);
  parent.add(m);
  return m;
}
// a leg that swings from its top
function leg(parent, r, h, color, x, y, z) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  part(g, new THREE.CylinderGeometry(r, r * 0.85, h, 5), color, 0, -h / 2, 0);
  parent.add(g);
  return g;
}

let blobTex;
function blobShadow(size) {
  if (!blobTex) {
    const c = document.createElement("canvas");
    c.width = c.height = 64;
    const g = c.getContext("2d");
    const grd = g.createRadialGradient(32, 32, 0, 32, 32, 32);
    grd.addColorStop(0, "rgba(0,0,0,0.38)");
    grd.addColorStop(1, "rgba(0,0,0,0)");
    g.fillStyle = grd;
    g.fillRect(0, 0, 64, 64);
    blobTex = new THREE.CanvasTexture(c);
  }
  const m = new THREE.Mesh(new THREE.PlaneGeometry(size, size), new THREE.MeshBasicMaterial({ map: blobTex, transparent: true, depthWrite: false }));
  m.rotation.x = -Math.PI / 2;
  m.position.y = 0.02;
  m.renderOrder = 1;
  return m;
}

// ---- your own pet ------------------------------------------------------------
const PET_KEY = "tdd3d.pet.v1";
export const PET_OPTIONS = {
  kind: [
    { id: "cat", label: "kitty" },
    { id: "bunny", label: "bunny" },
    { id: "both", label: "kitty + bunny" },
  ],
  hat: [
    { id: "none", label: "none" },
    { id: "bow", label: "bow" },
    { id: "flower", label: "flower" },
    { id: "crown", label: "crown" },
    { id: "party", label: "party hat" },
    { id: "witch", label: "witch hat" },
    { id: "halo", label: "halo" },
    { id: "star", label: "star clip" },
  ],
  size: [
    { id: "small", label: "tiny" },
    { id: "regular", label: "regular" },
    { id: "big", label: "big" },
  ],
};
const PET_SIZES = { small: 0.75, regular: 1, big: 1.3 };
export const PET_COLORS = {
  fur: ["#f4a259", "#9a9aa8", "#2b2633", "#fff7f0", "#c98a5a", "#f3d9b1", "#b08968", "#f7c6d9", "#b79be8"],
  accent: ["#fff1e0", "#ffffff", "#2b2633", "#f7c6d9", "#e8e8f0", "#c98a5a"],
  collar: ["#e2557f", "#7b5cd6", "#6fa8e8", "#8fd3b6", "#ffd166", "#2b2633"],
};
export const DEFAULT_PET = { kind: "cat", fur: "#f4a259", accent: "#fff1e0", collar: "#e2557f", hat: "none", name: "", fur2: "#fff7f0", name2: "", size: "regular" };
export function loadPet() {
  try {
    const p = JSON.parse(localStorage.getItem(PET_KEY) || "null");
    // the puppy was retired: it becomes a kitty
    if (p && typeof p === "object") return { ...DEFAULT_PET, ...p, ...(p.kind === "puppy" ? { kind: "cat" } : {}) };
  } catch {}
  return { ...DEFAULT_PET };
}
export function savePet(p) {
  try {
    localStorage.setItem(PET_KEY, JSON.stringify(p));
  } catch {}
}

function makePuppy([fur, accent]) {
  const root = new THREE.Group();
  const body = new THREE.Group();
  body.position.y = 0.32;
  root.add(body);
  const torso = part(body, new THREE.CapsuleGeometry(0.16, 0.3, 2, 8), fur);
  torso.rotation.x = Math.PI / 2;
  part(body, new THREE.SphereGeometry(0.12, 7, 5), accent, 0, -0.07, 0.1).scale.set(1, 0.7, 1.3);
  const head = new THREE.Group();
  head.position.set(0, 0.18, 0.28);
  body.add(head);
  part(head, new THREE.SphereGeometry(0.15, 10, 8), fur);
  const snout = part(head, new THREE.SphereGeometry(0.08, 8, 6), accent, 0, -0.04, 0.12);
  snout.scale.set(1.1, 0.8, 1);
  part(head, new THREE.SphereGeometry(0.03, 6, 4), "#2b1d24", 0, -0.01, 0.2);
  for (const s of [-1, 1]) {
    part(head, new THREE.SphereGeometry(0.026, 6, 4), "#2b1d24", s * 0.06, 0.04, 0.125).scale.y = 1.3;
    const ear = part(head, new THREE.SphereGeometry(0.075, 7, 5), fur, s * 0.13, 0.02, -0.01);
    ear.scale.set(0.45, 1.25, 0.9);
    ear.rotation.z = s * 0.25;
  }
  part(head, new THREE.SphereGeometry(0.03, 6, 4), "#ff8fb1", 0, -0.09, 0.15).scale.set(1, 0.5, 1); // tongue
  const legs = [];
  for (const [x, z] of [[0.08, 0.13], [-0.08, 0.13], [0.08, -0.13], [-0.08, -0.13]]) legs.push(leg(body, 0.04, 0.27, fur, x, -0.04, z));
  const tail = [];
  let parent = body;
  let pos = [0, 0.06, -0.22];
  for (let i = 0; i < 3; i++) {
    const seg = new THREE.Group();
    seg.position.set(...pos);
    parent.add(seg);
    part(seg, new THREE.CylinderGeometry(0.028 - i * 0.005, 0.034 - i * 0.005, 0.1, 5), i === 2 ? accent : fur, 0, 0.05, 0);
    seg.rotation.x = i === 0 ? -0.7 : -0.3;
    tail.push(seg);
    parent = seg;
    pos = [0, 0.1, 0];
  }
  return { root, body, head, legs, tail };
}

function petHat(head, kind, y, collar) {
  const g = new THREE.Group();
  g.position.set(0, y, 0);
  head.add(g);
  if (kind === "bow") {
    g.position.x = 0.07;
    for (const s of [-1, 1]) part(g, new THREE.ConeGeometry(0.045, 0.08, 4), collar, s * 0.04, 0, 0).rotation.z = s * Math.PI / 2;
    part(g, new THREE.SphereGeometry(0.02, 5, 4), collar);
  } else if (kind === "flower") {
    g.position.x = -0.07;
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      part(g, new THREE.SphereGeometry(0.025, 5, 4), "#ff8fb1", Math.cos(a) * 0.03, Math.sin(a) * 0.03, 0.02);
    }
    part(g, new THREE.SphereGeometry(0.02, 5, 4), "#ffd166", 0, 0, 0.03);
  } else if (kind === "crown") {
    const gold = new THREE.MeshStandardMaterial({ color: "#ffd166", metalness: 0.5, roughness: 0.35, emissive: "#5a3a00", emissiveIntensity: 0.3, side: THREE.DoubleSide });
    part(g, new THREE.CylinderGeometry(0.06, 0.065, 0.04, 8, 1, true), gold);
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      part(g, new THREE.ConeGeometry(0.015, 0.04, 4), gold, Math.cos(a) * 0.06, 0.04, Math.sin(a) * 0.06);
    }
  } else if (kind === "party") {
    const hat = part(g, new THREE.ConeGeometry(0.06, 0.16, 10), collar, 0, 0.06, 0);
    hat.rotation.z = 0.2;
    part(g, new THREE.SphereGeometry(0.022, 6, 4), "#fff7f2", -0.016, 0.15, 0);
  } else if (kind === "witch") {
    part(g, new THREE.CylinderGeometry(0.11, 0.11, 0.012, 14), "#2b2633", 0, 0.005, 0);
    const cone = part(g, new THREE.ConeGeometry(0.06, 0.17, 10), "#2b2633", 0, 0.09, -0.01);
    cone.rotation.x = -0.25;
    part(g, new THREE.CylinderGeometry(0.062, 0.062, 0.02, 10), collar, 0, 0.022, 0);
  } else if (kind === "halo") {
    const ring = part(g, new THREE.TorusGeometry(0.075, 0.012, 4, 16), new THREE.MeshStandardMaterial({ color: "#fff2b0", emissive: "#ffe27a", emissiveIntensity: 1.2 }), 0, 0.09, 0);
    ring.rotation.x = Math.PI / 2;
  } else if (kind === "star") {
    g.position.x = 0.07;
    const st = part(g, new THREE.OctahedronGeometry(0.04, 0), "#ffd166", 0, 0, 0.02);
    st.scale.set(1, 1, 0.45);
    st.rotation.z = Math.PI / 4;
  }
}

function petTag(text) {
  const { ctx, tex } = textCanvas(256, 64);
  ctx.font = `700 30px ${FONT}`;
  const w = Math.min(250, ctx.measureText(text).width + 34);
  ctx.fillStyle = "rgba(226,85,127,0.8)";
  ctx.beginPath();
  ctx.roundRect((256 - w) / 2, 8, w, 48, 24);
  ctx.fill();
  ctx.fillStyle = "#fff";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(text, 128, 33);
  tex.needsUpdate = true;
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
  s.scale.set(1.0, 0.25, 1);
  s.renderOrder = 6;
  return s;
}

const CAT_COLORS = [
  ["#f4a259", "#fff1e0"], ["#9a9aa8", "#e8e8f0"], ["#2b2633", "#ffffff"], ["#fff7f0", "#f7c6d9"], ["#c98a5a", "#2b2633"],
];
const BUNNY_COLORS = ["#fffaf6", "#b08968", "#d9d4dc", "#f3d9b1", "#8a7a70"];

function makeCat(colors) {
  const [fur, accent] = colors;
  const root = new THREE.Group();
  const body = new THREE.Group();
  body.position.y = 0.3;
  root.add(body);
  const torso = part(body, new THREE.CapsuleGeometry(0.15, 0.34, 2, 7), fur, 0, 0, 0);
  torso.rotation.x = Math.PI / 2;
  part(body, new THREE.SphereGeometry(0.11, 7, 5), accent, 0, -0.06, 0.12).scale.set(1, 0.7, 1.2);
  const head = new THREE.Group();
  head.position.set(0, 0.16, 0.3);
  body.add(head);
  part(head, new THREE.SphereGeometry(0.15, 9, 7), fur).scale.set(1.1, 0.95, 0.95);
  for (const s of [-1, 1]) {
    const ear = part(head, new THREE.ConeGeometry(0.06, 0.12, 4), fur, s * 0.08, 0.14, -0.01);
    ear.rotation.z = -s * 0.25;
    part(head, new THREE.ConeGeometry(0.035, 0.07, 4), "#f7a8c4", s * 0.08, 0.13, 0.02).rotation.z = -s * 0.25;
    part(head, new THREE.SphereGeometry(0.026, 6, 4), "#2b1d24", s * 0.06, 0.02, 0.13).scale.y = 1.3;
    for (const w of [-1, 1]) {
      const whisker = part(head, new THREE.BoxGeometry(0.12, 0.004, 0.004), "#ffffff", s * 0.12, -0.03 + w * 0.012, 0.11);
      whisker.rotation.z = s * w * 0.15;
    }
  }
  part(head, new THREE.SphereGeometry(0.02, 5, 4), "#ff8fb1", 0, -0.02, 0.15);
  const legs = [];
  for (const [x, z] of [[0.08, 0.14], [-0.08, 0.14], [0.08, -0.14], [-0.08, -0.14]]) legs.push(leg(body, 0.035, 0.26, fur, x, -0.04, z));
  // tail: a chain that sways
  const tail = [];
  let parent = body;
  let pos = [0, 0.05, -0.24];
  for (let i = 0; i < 4; i++) {
    const seg = new THREE.Group();
    seg.position.set(...pos);
    parent.add(seg);
    part(seg, new THREE.CylinderGeometry(0.03 - i * 0.004, 0.034 - i * 0.004, 0.12, 5), i === 3 ? accent : fur, 0, 0.06, 0);
    seg.rotation.x = i === 0 ? -0.9 : -0.25;
    tail.push(seg);
    parent = seg;
    pos = [0, 0.12, 0];
  }
  return { root, body, head, legs, tail };
}

function makeBunny(color) {
  const root = new THREE.Group();
  const body = new THREE.Group();
  body.position.y = 0.18;
  root.add(body);
  part(body, new THREE.SphereGeometry(0.17, 9, 7), color).scale.set(1, 0.92, 1.18);
  const head = new THREE.Group();
  head.position.set(0, 0.16, 0.15);
  body.add(head);
  part(head, new THREE.SphereGeometry(0.11, 9, 7), color);
  const ears = [];
  for (const s of [-1, 1]) {
    const ear = new THREE.Group();
    ear.position.set(s * 0.045, 0.08, -0.02);
    ear.rotation.z = -s * 0.15;
    head.add(ear);
    part(ear, new THREE.CapsuleGeometry(0.032, 0.14, 2, 6), color, 0, 0.1, 0).scale.z = 0.6;
    part(ear, new THREE.CapsuleGeometry(0.018, 0.1, 2, 5), "#f7a8c4", 0, 0.1, 0.012).scale.z = 0.5;
    ears.push(ear);
    part(head, new THREE.SphereGeometry(0.02, 6, 4), "#2b1d24", s * 0.055, 0.02, 0.085);
  }
  part(head, new THREE.SphereGeometry(0.016, 5, 4), "#ff8fb1", 0, -0.015, 0.11);
  part(body, new THREE.SphereGeometry(0.06, 6, 5), "#ffffff", 0, 0.03, -0.2);
  for (const s of [-1, 1]) part(body, new THREE.SphereGeometry(0.06, 6, 4), color, s * 0.08, -0.14, -0.06).scale.set(0.8, 0.5, 1.6);
  return { root, body, head, ears };
}

function makeDeer(stag) {
  const fur = "#b9895c";
  const belly = "#f1dcc0";
  const root = new THREE.Group();
  const body = new THREE.Group();
  body.position.y = 0.95;
  root.add(body);
  const torso = part(body, new THREE.CapsuleGeometry(0.28, 0.7, 2, 8), fur);
  torso.rotation.x = Math.PI / 2;
  part(body, new THREE.SphereGeometry(0.24, 7, 5), belly, 0, -0.1, 0).scale.set(0.9, 0.6, 2);
  for (const [x, z] of [[0.12, 0.2], [-0.15, -0.1], [0.05, -0.25], [-0.1, 0.25], [0.18, -0.05]]) part(body, new THREE.SphereGeometry(0.03, 5, 4), "#fff7ea", x, 0.25, z);
  const neck = new THREE.Group();
  neck.position.set(0, 0.15, 0.42);
  body.add(neck);
  const n = part(neck, new THREE.CylinderGeometry(0.1, 0.14, 0.55, 6), fur, 0, 0.25, 0.05);
  n.rotation.x = 0.35;
  const head = new THREE.Group();
  head.position.set(0, 0.52, 0.18);
  neck.add(head);
  part(head, new THREE.SphereGeometry(0.15, 8, 6), fur).scale.set(0.9, 0.9, 1.1);
  part(head, new THREE.ConeGeometry(0.09, 0.22, 6), fur, 0, -0.04, 0.17).rotation.x = Math.PI / 2;
  part(head, new THREE.SphereGeometry(0.035, 5, 4), "#2b1d24", 0, -0.04, 0.28);
  for (const s of [-1, 1]) {
    part(head, new THREE.SphereGeometry(0.03, 6, 4), "#2b1d24", s * 0.1, 0.03, 0.08);
    const ear = part(head, new THREE.ConeGeometry(0.06, 0.18, 4), fur, s * 0.13, 0.12, -0.04);
    ear.rotation.z = -s * 1.0;
    if (stag) {
      const antler = new THREE.Group();
      antler.position.set(s * 0.07, 0.13, -0.02);
      antler.rotation.z = -s * 0.35;
      head.add(antler);
      const bone = "#efe2c8";
      part(antler, new THREE.CylinderGeometry(0.015, 0.02, 0.3, 4), bone, 0, 0.15, 0);
      for (const [y, a] of [[0.12, 0.8], [0.22, -0.7]]) {
        const tine = part(antler, new THREE.CylinderGeometry(0.01, 0.014, 0.14, 4), bone, s * 0.04, y, 0);
        tine.rotation.z = -s * a;
      }
    }
  }
  part(body, new THREE.SphereGeometry(0.07, 6, 4), "#ffffff", 0, 0.1, -0.52);
  const legs = [];
  for (const [x, z] of [[0.15, 0.32], [-0.15, 0.32], [0.15, -0.32], [-0.15, -0.32]]) legs.push(leg(body, 0.045, 0.85, fur, x, -0.05, z));
  return { root, body, neck, head, legs };
}

const SPECIES = {
  cat: { walk: 1.1, run: 3.6, radius: 0.28, home: 20 },
  bunny: { walk: 1.4, run: 4.6, radius: 0.22, home: 16 },
  deer: { walk: 1.0, run: 6.2, radius: 0.55, home: 24 },
  boy: { walk: 2.4, run: 5.5, radius: 0.38, home: 40 },
};

export function buildPetModels(cfg) {
  const c = { ...DEFAULT_PET, ...cfg };
  const one = (kind, fur, name) => {
    let model;
    let headR;
    if (kind === "bunny") {
      model = makeBunny(fur);
      headR = 0.11;
    } else if (kind === "puppy") {
      model = makePuppy([fur, c.accent]);
      headR = 0.15;
    } else {
      model = makeCat([fur, c.accent]);
      headR = 0.15;
    }
    const collar = part(model.head, new THREE.TorusGeometry(headR * 0.68, 0.018, 4, 12), c.collar, 0, -headR * 0.75, -0.03);
    collar.rotation.x = Math.PI / 2;
    part(model.head, new THREE.SphereGeometry(0.024, 6, 4), "#ffd166", 0, -headR * 0.95, headR * 0.5);
    if (c.hat !== "none") petHat(model.head, c.hat, headR * 0.92, c.collar);
    model.root.scale.setScalar(PET_SIZES[c.size] || 1);
    return { model, kind: kind === "bunny" ? "bunny" : "cat", species: kind, name };
  };
  if (c.kind === "both") return [one("cat", c.fur, c.name), one("bunny", c.fur2 || "#fff7f0", c.name2)];
  return [one(c.kind, c.fur, c.name)];
}

export class Creatures {
  constructor(scene, { lowEnd, collide, isWalkable, places }) {
    this.scene = scene;
    this.collide = collide;
    this.isWalkable = isWalkable;
    this.places = places;
    this.list = [];
    this.t = 0;
    const rnd = (a, b) => a + Math.random() * (b - a);
    const randomSpot = (r = 42) => {
      for (let i = 0; i < 40; i++) {
        const a = Math.random() * Math.PI * 2;
        const d = 12 + Math.random() * (r - 12);
        const p = new THREE.Vector3(Math.sin(a) * d, 0, Math.cos(a) * d);
        if (isWalkable(p)) return p;
      }
      return new THREE.Vector3(0, 0, 25);
    };
    this.randomSpot = randomSpot;

    const counts = lowEnd ? { cat: 3, bunny: 5, deer: 3 } : { cat: 5, bunny: 8, deer: 4 };
    for (let i = 1; i < counts.cat; i++) this.add("cat", makeCat(CAT_COLORS[i % CAT_COLORS.length]), randomSpot());
    for (let i = 0; i < counts.bunny; i++) this.add("bunny", makeBunny(BUNNY_COLORS[i % BUNNY_COLORS.length]), randomSpot());
    for (let i = 0; i < counts.deer; i++) this.add("deer", makeDeer(i % 2 === 0), randomSpot(44));

    // your own pet follows you around
    this.setPet(loadPet(), randomSpot());

    // no computer characters: just you two and the animals
    this.boy = null;
    void rnd;
  }

  add(kind, model, pos, extra = {}) {
    const c = {
      kind,
      model,
      pos: pos.clone(),
      facing: Math.random() * Math.PI * 2,
      speed: 0,
      mode: "idle",
      timer: Math.random() * 3,
      target: null,
      phase: Math.random() * 10,
      hop: 0,
      happy: 0,
      ...SPECIES[kind],
      ...extra,
    };
    model.root.position.copy(pos);
    model.root.userData.creature = c;
    if (kind !== "boy") {
      model.root.traverse((o) => {
        if (o.isMesh) o.castShadow = false;
      });
      const shadow = blobShadow(kind === "deer" ? 1.6 : kind === "boy" ? 1 : 0.7);
      c.shadow = shadow;
      this.scene.add(shadow);
    }
    this.scene.add(model.root);
    this.list.push(c);
    return c;
  }

  // build (or rebuild) your pets from their settings
  setPet(cfg, at) {
    const olds = this.pets || [];
    const pos = at ? at.clone() : olds[0] ? olds[0].pos.clone() : new THREE.Vector3(0, 0, 30);
    const stay = olds[0]?.stay || false;
    for (const old of olds) {
      this.remove(old);
      if (old.tag) this.scene.remove(old.tag);
    }
    this.petConfig = { ...DEFAULT_PET, ...cfg };
    this.pets = buildPetModels(this.petConfig).map((b, i) => {
      const p = pos.clone().add(new THREE.Vector3(i * 0.8, 0, i * 0.5));
      const pet = this.add(b.kind, b.model, p, { companion: true, species: b.species, petName: b.name, slot: i, stay });
      if (b.name) {
        pet.tag = petTag(b.name);
        this.scene.add(pet.tag);
      }
      return pet;
    });
    this.pet = this.pets[0];
    return this.pet;
  }

  // "sit" / "come here"
  toggleStay() {
    const stay = !this.pets?.[0]?.stay;
    for (const p of this.pets || []) {
      p.stay = stay;
      p.mode = "idle";
      p.target = null;
      p.timer = 2;
      p.happy = 1.2;
    }
    return stay;
  }

  // your person's pets: models only, moved by the network
  makeRemotePets(cfg) {
    return buildPetModels(cfg).map((b) => {
      const c = { kind: b.kind, model: b.model, pos: new THREE.Vector3(), facing: 0, speed: 0, mode: "idle", phase: Math.random() * 10, happy: 0, species: b.species, remote: true };
      b.model.root.traverse((o) => {
        if (o.isMesh) o.castShadow = false;
      });
      c.shadow = blobShadow(0.7);
      this.scene.add(c.shadow, b.model.root);
      if (b.name) {
        c.tag = petTag(b.name);
        this.scene.add(c.tag);
      }
      return c;
    });
  }
  dropRemotePets(list) {
    for (const c of list || []) this.scene.remove(c.model.root, c.shadow, ...(c.tag ? [c.tag] : []));
  }
  animateRemotePet(c, dt) {
    this.animate(c, dt, 99);
  }
  petStates() {
    return (this.pets || []).map((p) => [+p.pos.x.toFixed(2), +p.pos.z.toFixed(2), +p.facing.toFixed(2), +p.speed.toFixed(2), p.mode === "idle" ? 1 : 0]);
  }

  // golden bunnies for the catch game: they run from you
  spawnGolden(pos) {
    const model = makeBunny("#ffd166");
    const bow = part(model.head, new THREE.TorusGeometry(0.05, 0.02, 4, 8), "#e2557f", 0, 0.1, -0.06);
    bow.rotation.y = Math.PI / 2;
    const c = this.add("bunny", model, pos, { scared: true, run: 4.2, golden: true });
    c.mode = "flee";
    return c;
  }

  remove(c) {
    c.hidden = true;
    this.scene.remove(c.model.root);
    if (c.shadow) this.scene.remove(c.shadow);
    this.list = this.list.filter((x) => x !== c);
  }

  // nearest animal or the boy the player can interact with
  nearest(p, max = 2.0) {
    let best = null;
    let bd = max;
    for (const c of this.list) {
      if (c.hidden || c.golden) continue;
      const d = Math.hypot(c.pos.x - p.x, c.pos.z - p.z) - (c.kind === "deer" ? 0.5 : 0);
      if (d < bd) {
        bd = d;
        best = c;
      }
    }
    return best;
  }

  label(c) {
    if (c.companion) return `pet ${c.petName || `your ${c.species === "cat" ? "kitty" : c.species}`} ♡`;
    return { cat: "pet the kitty ♡", bunny: "pet the bunny ♡", deer: "pet the deer ♡", boy: "hug him ♡" }[c.kind];
  }

  // the player pets / greets c
  greet(c, player) {
    c.happy = 2.2;
    c.mode = "idle";
    c.timer = 2.5;
    c.facing = Math.atan2(player.pos.x - c.pos.x, player.pos.z - c.pos.z);
    if (c.kind === "boy") {
      c.avatar.playEmote("hug");
      c.bubble.userData.say(["hehe ♡", "hiii ♡", "warm ♡", "again ♡"][Math.floor(Math.random() * 4)]);
    }
    return c.kind;
  }

  update(dt, player) {
    this.t += dt;
    for (const c of this.list) this.think(c, dt, player);
  }

  // hit by the rifle: fall over, then get up (and run, or complain)
  knock(c) {
    c.knock = c.kind === "boy" ? 2.4 : 1.8;
    c.speed = 0;
    if (c.kind === "boy") c.bubble.userData.say(["ow!! >:(", "hey!!", "why 😭"][Math.floor(Math.random() * 3)]);
  }

  think(c, dt, player) {
    const dx = player.pos.x - c.pos.x;
    const dz = player.pos.z - c.pos.z;
    const pd = Math.hypot(dx, dz);
    if (c.knock > 0) {
      c.knock -= dt;
      if (c.knock <= 0 && c.kind !== "boy") {
        c.mode = "flee";
        c.timer = 2;
        c.target = c.pos.clone().add(new THREE.Vector3(-dx, 0, -dz).normalize().multiplyScalar(8));
      }
      this.animate(c, dt, pd);
      return;
    }
    c.timer -= dt;
    c.happy = Math.max(0, c.happy - dt);

    // decide
    if (c.companion) {
      // stays put when told to sit, and waits at the edge while you do the sky trail
      const away = player.offIsland;
      if (c.stay || away) {
        if (c.mode !== "idle") {
          c.mode = "idle";
          c.timer = 2;
        }
        c.target = null;
        if (!c.stay && away && pd > 6) c.facing = turnTo(c.facing, Math.atan2(dx, dz), dt * 3);
      } else if (pd > 28) {
        // after travelling, the kitty catches up
        c.pos.set(player.pos.x - Math.sin(player.facing) * 1.5, 0, player.pos.z - Math.cos(player.facing) * 1.5);
      }
      if (c.stay || away) {
        // waiting
      } else if (pd > 2.2 + (c.slot || 0) * 0.8 && c.happy <= 0) {
        c.mode = pd > 5 ? "run" : "walk";
        const side = (c.slot || 0) * 0.9;
        c.target = new THREE.Vector3(player.pos.x - (dx / pd) * 1.4 + (dz / pd) * side, 0, player.pos.z - (dz / pd) * 1.4 - (dx / pd) * side);
      } else if (c.mode !== "idle") {
        c.mode = "idle";
        c.timer = 1 + Math.random() * 2;
      }
    } else if (c.kind === "deer" || c.kind === "bunny") {
      const scary = (player.speed > 4 && pd < 6) || (c.kind === "deer" && pd < 2.4 && player.speed > 2.5) || (c.scared && pd < 7);
      if (scary && c.happy <= 0) {
        c.mode = "flee";
        c.timer = 1.5;
        const away = new THREE.Vector3(-dx, 0, -dz).normalize().multiplyScalar(7);
        c.target = c.pos.clone().add(away);
      }
    } else if (c.kind === "boy") {
      if (pd < 4 && player.pos.y < 0.6) {
        if (!c.greeted) {
          c.greeted = true;
          c.avatar.playEmote("wave");
          c.bubble.userData.say("hi ♡");
        }
        c.mode = "idle";
        c.timer = Math.max(c.timer, 1);
        c.facing = turnTo(c.facing, Math.atan2(dx, dz), dt * 6);
      } else if (pd > 9) c.greeted = false;
    }

    if (c.timer <= 0 && !c.companion) {
      if (c.mode === "idle") {
        c.mode = "walk";
        c.timer = 4 + Math.random() * 5;
        c.target = c.kind === "boy" ? this.places[Math.floor(Math.random() * this.places.length)].clone() : this.wanderTarget(c);
      } else {
        c.mode = "idle";
        c.timer = 1.5 + Math.random() * 4;
      }
    }

    // move
    let want = 0;
    if ((c.mode === "walk" || c.mode === "run" || c.mode === "flee") && c.target) {
      const tx = c.target.x - c.pos.x;
      const tz = c.target.z - c.pos.z;
      const td = Math.hypot(tx, tz);
      if (td < 0.4) {
        c.mode = "idle";
        c.timer = 1 + Math.random() * 3;
      } else {
        want = c.mode === "walk" ? c.walk : c.run;
        c.facing = turnTo(c.facing, Math.atan2(tx, tz), dt * (c.mode === "flee" ? 9 : 4));
      }
    }
    c.speed += (want - c.speed) * (1 - Math.exp(-dt * 6));
    if (c.speed > 0.02) {
      const before = c.pos.clone();
      c.pos.x += Math.sin(c.facing) * c.speed * dt;
      c.pos.z += Math.cos(c.facing) * c.speed * dt;
      this.collide(c.pos, c.radius);
      if (!this.isWalkable(c.pos)) c.pos.copy(before);
      // stuck: pick somewhere else
      if (before.distanceTo(c.pos) < c.speed * dt * 0.3 && c.mode !== "idle") {
        c.target = this.wanderTarget(c);
      }
    }
    this.animate(c, dt, pd);
  }

  wanderTarget(c) {
    for (let i = 0; i < 12; i++) {
      const a = Math.random() * Math.PI * 2;
      const d = 2 + Math.random() * 7;
      const p = new THREE.Vector3(c.pos.x + Math.sin(a) * d, 0, c.pos.z + Math.cos(a) * d);
      if (Math.hypot(p.x, p.z) < 44 && this.isWalkable(p)) return p;
    }
    return this.randomSpot();
  }

  animate(c, dt, pd) {
    const m = c.model;
    const t = this.t;
    const s = c.speed;
    m.root.position.set(c.pos.x, c.pos.y || 0, c.pos.z);
    m.root.rotation.y = c.facing;
    const fall = c.knock > 0 ? Math.min(1, c.knock * 3, (c.kind === "boy" ? 2.4 : 1.8) - c.knock + 0.0001 > 0 ? 1 : 0) : 0;
    c.fall = (c.fall || 0) + (fall - (c.fall || 0)) * Math.min(1, dt * 10);
    m.root.rotation.z = c.fall * 1.45;
    if (c.shadow) c.shadow.position.set(c.pos.x, 0.02, c.pos.z);
    if (c.tag) c.tag.position.set(c.pos.x, c.kind === "bunny" ? 0.85 : 0.95, c.pos.z);

    if (c.kind === "cat") {
      c.phase += dt * (2 + s * 5);
      const amp = Math.min(1, s / 1.2) * 0.6;
      m.legs.forEach((l, i) => (l.rotation.x = Math.sin(c.phase + (i === 0 || i === 3 ? 0 : Math.PI)) * amp));
      m.body.position.y = 0.3 + Math.abs(Math.sin(c.phase)) * 0.02 * amp;
      const sit = c.mode === "idle" ? (c.stay ? 1.4 : 1) : 0;
      m.body.rotation.x += ((-0.35 * sit) - m.body.rotation.x) * Math.min(1, dt * 4);
      m.tail.forEach((seg, i) => (seg.rotation.z = Math.sin(t * (c.happy > 0 ? 9 : 2.5) + i * 0.8 + c.phase * 0.1) * (0.25 + i * 0.05)));
      m.head.rotation.y = c.mode === "idle" ? Math.sin(t * 0.7 + c.phase) * 0.5 : 0;
      m.head.rotation.z = c.happy > 0 ? Math.sin(t * 6) * 0.2 : 0;
    } else if (c.kind === "bunny") {
      // bunnies hop
      if (s > 0.1) c.phase += dt * (6 + s * 3);
      const hop = s > 0.1 ? Math.abs(Math.sin(c.phase)) : 0;
      m.root.position.y = hop * (0.12 + s * 0.04);
      m.body.scale.set(1, 1 + hop * 0.12, 1 - hop * 0.08);
      m.ears.forEach((e, i) => (e.rotation.x = -0.2 - hop * 0.5 + Math.sin(t * 3 + i) * 0.05));
      m.head.rotation.x = c.mode === "idle" ? Math.sin(t * 8 + c.phase) * 0.06 : 0; // nose twitch
      if (c.happy > 0) m.root.position.y += Math.abs(Math.sin(t * 10)) * 0.08;
    } else if (c.kind === "deer") {
      c.phase += dt * (1.5 + s * 2.4);
      const amp = Math.min(1, s / 1.0) * (s > 3 ? 0.7 : 0.4);
      m.legs.forEach((l, i) => (l.rotation.x = Math.sin(c.phase + (i === 0 || i === 3 ? 0 : Math.PI)) * amp));
      m.body.position.y = 0.95 + (s > 3 ? Math.abs(Math.sin(c.phase)) * 0.12 : 0);
      // graze when idle
      const graze = c.mode === "idle" && pd > 5 ? 1 : 0;
      m.neck.rotation.x += ((graze ? 1.3 : 0) - m.neck.rotation.x) * Math.min(1, dt * 2.5);
      m.head.rotation.y = graze ? 0 : Math.sin(t * 0.5 + c.phase) * 0.4;
    } else if (c.kind === "boy") {
      c.avatar.update(dt, s, false, 0);
      const b = c.bubble;
      if (b.userData.life > 0) {
        b.userData.life -= dt;
        b.material.opacity = Math.min(1, b.userData.life * 3);
      } else b.material.opacity = 0;
      b.position.set(c.pos.x, 2.4, c.pos.z);
      this.boyTag?.position.set(c.pos.x, 1.95, c.pos.z);
    }
  }
}

function turnTo(a, b, k) {
  const d = Math.atan2(Math.sin(b - a), Math.cos(b - a));
  return a + d * Math.min(1, k);
}
