// Music and sound effects, all synthesized with Web Audio (no files).
// Three original tunes follow the theme: "picnic" (light themes, bouncy
// marimba), "night walk" (dark themes, mellow lo-fi) and "pumpkin waltz"
// (halloween, playful harpsichord). Music pauses while a song plays in the
// diary.

const MUSIC_KEY = "tdd3d.music";
const NOTE = (n) => 440 * Math.pow(2, (n - 69) / 12);

// melodies are 8 bars of eighth notes (0 = rest); chords loop every 4 bars
const SONGS = {
  cozy: {
    bpm: 112,
    swing: 0.3,
    lead: "marimba",
    chords: [[53, 57, 60, 64], [50, 53, 57, 60], [55, 58, 62, 65], [48, 52, 55, 58]], // Fmaj7 Dm7 Gm7 C7
    bass: [41, 38, 43, 36],
    melody: [
      72, 0, 69, 72, 74, 72, 69, 0,
      74, 0, 72, 69, 65, 0, 69, 0,
      70, 0, 74, 72, 70, 69, 67, 0,
      69, 70, 72, 0, 76, 0, 72, 0,
      77, 0, 76, 74, 72, 0, 69, 72,
      74, 0, 77, 0, 76, 74, 72, 0,
      70, 72, 74, 0, 70, 0, 67, 69,
      72, 0, 76, 0, 79, 0, 0, 0,
    ],
    drums: { kick: [0, 8, 11], snare: [4, 12], shaker: true },
    stabs: true,
  },
  night: {
    bpm: 76,
    swing: 0.18,
    lead: "bell",
    chords: [[51, 55, 58, 62], [48, 51, 55, 58, 62], [44, 48, 51, 55], [46, 50, 53, 55]], // Ebmaj7 Cm9 Abmaj7 Bb6
    bass: [39, 36, 44, 46],
    melody: [
      70, 0, 0, 72, 74, 0, 0, 0,
      75, 0, 74, 0, 72, 0, 0, 0,
      72, 0, 70, 0, 67, 0, 0, 63,
      65, 0, 67, 0, 70, 0, 0, 0,
      70, 0, 0, 74, 79, 0, 77, 0,
      75, 0, 74, 0, 72, 0, 70, 0,
      68, 0, 72, 0, 75, 0, 72, 0,
      74, 0, 0, 0, 0, 0, 0, 0,
    ],
    drums: { kick: [0, 7, 10], snare: [8], shaker: false },
    pad: true,
    crackle: true,
  },
  spooky: {
    bpm: 100,
    swing: 0,
    lead: "harpsi",
    chords: [[50, 53, 57], [46, 50, 53], [43, 46, 50], [45, 49, 52, 55]], // Dm Bb Gm A7
    bass: [38, 34, 31, 33],
    melody: [
      74, 0, 73, 74, 77, 0, 74, 0,
      70, 0, 69, 70, 74, 0, 70, 0,
      67, 0, 69, 70, 74, 73, 74, 0,
      73, 0, 69, 0, 64, 0, 61, 0,
      74, 77, 81, 0, 77, 74, 73, 74,
      70, 74, 77, 0, 74, 70, 69, 70,
      67, 70, 74, 0, 79, 77, 76, 74,
      73, 0, 0, 76, 73, 0, 69, 0,
    ],
    drums: { kick: [0, 6, 8], snare: [12], shaker: false },
    arp: true,
  },
};

export class Audio {
  constructor() {
    this.ctx = null;
    this.musicOn = (() => {
      try {
        return localStorage.getItem(MUSIC_KEY) !== "0";
      } catch {
        return true;
      }
    })();
    this.mood = "cozy";
    this.step = 0;
    this.nextTime = 0;
    this.ducked = false;
    this.unlock = () => this.ensure();
    window.addEventListener("pointerdown", this.unlock, { passive: true });
    window.addEventListener("keydown", this.unlock);
  }

  ensure() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      const ctx = new AC();
      this.ctx = ctx;
      this.master = ctx.createGain();
      this.master.gain.value = 0.75;
      // gentle glue so nothing pokes out
      const comp = ctx.createDynamicsCompressor();
      comp.threshold.value = -18;
      comp.ratio.value = 3;
      this.master.connect(comp).connect(ctx.destination);
      this.music = ctx.createGain();
      this.music.gain.value = this.musicOn ? 0.5 : 0;
      this.music.connect(this.master);
      this.sfxBus = ctx.createGain();
      this.sfxBus.gain.value = 0.6;
      this.sfxBus.connect(this.master);
      this.reverb = ctx.createConvolver();
      const len = ctx.sampleRate * 2.4;
      const ir = ctx.createBuffer(2, len, ctx.sampleRate);
      for (let ch = 0; ch < 2; ch++) {
        const d = ir.getChannelData(ch);
        for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 3.2);
      }
      this.reverb.buffer = ir;
      const wet = ctx.createGain();
      wet.gain.value = 0.25;
      this.reverb.connect(wet).connect(this.music);
      this.delay = ctx.createDelay(1);
      const fb = ctx.createGain();
      fb.gain.value = 0.28;
      const dl = ctx.createGain();
      dl.gain.value = 0.35;
      this.delay.connect(fb).connect(this.delay);
      this.delay.connect(dl).connect(this.music);
      this.noise = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
      const nd = this.noise.getChannelData(0);
      for (let i = 0; i < nd.length; i++) nd[i] = Math.random() * 2 - 1;
      this.nextTime = ctx.currentTime + 0.1;
      this.timer = setInterval(() => this.schedule(), 50);
    }
    if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
  }

  setMood(mood) {
    if (SONGS[mood] && mood !== this.mood) {
      this.mood = mood;
      this.step = 0;
    }
  }

  toggleMusic() {
    this.musicOn = !this.musicOn;
    try {
      localStorage.setItem(MUSIC_KEY, this.musicOn ? "1" : "0");
    } catch {}
    this.ensure();
    this.applyGain();
    return this.musicOn;
  }

  setDucked(d) {
    if (d === this.ducked) return;
    this.ducked = d;
    this.applyGain();
  }

  applyGain() {
    if (!this.ctx) return;
    this.music.gain.setTargetAtTime(this.musicOn && !this.ducked ? 0.5 : 0, this.ctx.currentTime, 0.4);
  }

  pause(p) {
    if (!this.ctx) return;
    if (p) this.ctx.suspend().catch(() => {});
    else this.ctx.resume().catch(() => {});
  }

  // ---- sequencer ------------------------------------------------------------
  schedule() {
    const ctx = this.ctx;
    if (!ctx || ctx.state !== "running") return;
    const song = SONGS[this.mood];
    const sd = 60 / song.bpm / 4;
    this.delay.delayTime.setTargetAtTime(sd * 3, ctx.currentTime, 0.1);
    if (this.nextTime < ctx.currentTime - 0.5) this.nextTime = ctx.currentTime + 0.05;
    while (this.nextTime < ctx.currentTime + 0.25) {
      if (this.musicOn && !this.ducked) this.playStep(this.step, this.nextTime, song, sd);
      this.step = (this.step + 1) % 128; // 8 bars of 16ths
      this.nextTime += sd;
    }
  }

  playStep(step, t0, song, sd) {
    const s16 = step % 16;
    const bar = Math.floor(step / 16);
    const chord = song.chords[bar % 4];
    const root = song.bass[bar % 4];
    // swing the off-beat eighths
    const t = s16 % 4 === 2 ? t0 + sd * song.swing : t0;

    // harmony
    if (song.pad && s16 === 0) this.pad(chord.map(NOTE), t, sd * 16);
    if (song.stabs && (s16 === 2 || s16 === 6 || s16 === 10 || s16 === 14)) this.stab(chord.map((n) => NOTE(n + 12)), t);
    if (song.arp && s16 % 2 === 0) this.harpsi(NOTE(chord[(s16 / 2) % chord.length] + 12), t, 0.035);
    if (song.arp && s16 === 0) this.organ(chord.map(NOTE), t, sd * 16);

    // bass
    if (song === SONGS.cozy) {
      if (s16 === 0) this.bass(NOTE(root), t, sd * 2);
      if (s16 === 6) this.bass(NOTE(root + 7), t, sd * 1.5);
      if (s16 === 8) this.bass(NOTE(root + 12), t, sd * 1.5);
      if (s16 === 14) this.bass(NOTE(song.bass[(bar + 1) % 4] - 1), t, sd * 1.5);
    } else if (song === SONGS.night) {
      if (s16 === 0) this.bass(NOTE(root), t, sd * 7);
      if (s16 === 10) this.bass(NOTE(root + 7), t, sd * 4);
    } else {
      if (s16 % 4 === 0) this.bass(NOTE(s16 % 8 === 0 ? root : root + 7), t, sd * 2);
    }

    // drums
    const d = song.drums;
    if (d.kick.includes(s16)) this.kick(t, song === SONGS.night ? 0.22 : 0.3);
    if (d.snare.includes(s16)) song === SONGS.night ? this.rim(t) : this.snare(t);
    if (d.shaker) this.shaker(t, s16 % 4 === 0 ? 0.035 : 0.018);
    else if (s16 % 4 === 2) this.shaker(t, 0.02);
    if (song.crackle && s16 % 4 === 0 && Math.random() < 0.5) this.crackle(t);

    // melody on the eighths
    if (s16 % 2 === 0) {
      const n = song.melody[(bar % 8) * 8 + s16 / 2];
      if (n) this[song.lead](NOTE(n), t);
    }
  }

  env(g, t, a, peak, d) {
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(peak, t + a);
    g.gain.exponentialRampToValueAtTime(0.0001, t + a + d);
  }

  voice(type, fr, t, dur, vol, { filter = 0, out = this.music, wet = 0, echo = false, detune = 0 } = {}) {
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.value = fr;
    o.detune.value = detune;
    const g = ctx.createGain();
    this.env(g, t, 0.004, vol, dur);
    let node = o;
    if (filter) {
      const f = ctx.createBiquadFilter();
      f.type = "lowpass";
      f.frequency.value = filter;
      node.connect(f);
      node = f;
    }
    node.connect(g);
    g.connect(out);
    if (wet) g.connect(this.reverb);
    if (echo) g.connect(this.delay);
    o.start(t);
    o.stop(t + dur + 0.1);
  }

  // ---- instruments -----------------------------------------------------------
  marimba(fr, t) {
    this.voice("sine", fr, t, 0.45, 0.16, { wet: 1, echo: true });
    this.voice("sine", fr * 4, t, 0.08, 0.04);
  }
  bell(fr, t, out = this.music, vol = 0.09) {
    this.voice("sine", fr, t, 1.2, vol, { out, wet: out === this.music, echo: out === this.music });
    this.voice("sine", fr * 3, t, 0.5, vol * 0.22, { out });
  }
  harpsi(fr, t, vol = 0.07) {
    this.voice("sawtooth", fr, t, 0.32, vol, { filter: 2600, wet: 1, echo: vol > 0.05 });
    this.voice("square", fr * 2, t, 0.12, vol * 0.25, { filter: 3200 });
  }
  stab(freqs, t) {
    for (const fr of freqs) this.voice("triangle", fr, t, 0.16, 0.035, { filter: 2200, wet: 1 });
  }
  pad(freqs, t, dur) {
    const ctx = this.ctx;
    const f = ctx.createBiquadFilter();
    f.type = "lowpass";
    f.frequency.value = 900;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.04, t + 0.6);
    g.gain.setValueAtTime(0.04, t + dur - 0.4);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur + 0.5);
    f.connect(g);
    g.connect(this.music);
    g.connect(this.reverb);
    for (const fr of freqs) {
      for (const det of [-7, 7]) {
        const o = ctx.createOscillator();
        o.type = "triangle";
        o.frequency.value = fr;
        o.detune.value = det;
        o.connect(f);
        o.start(t);
        o.stop(t + dur + 0.6);
      }
    }
  }
  organ(freqs, t, dur) {
    for (const fr of freqs) this.voice("sine", fr / 2, t, dur, 0.025, { wet: 1 });
  }
  bass(fr, t, dur) {
    this.voice("triangle", fr, t, dur, 0.2, { filter: 500 });
    this.voice("sine", fr, t, dur, 0.12);
  }

  kick(t, vol = 0.3) {
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    o.frequency.setValueAtTime(130, t);
    o.frequency.exponentialRampToValueAtTime(42, t + 0.12);
    const g = ctx.createGain();
    this.env(g, t, 0.003, vol, 0.18);
    o.connect(g).connect(this.music);
    o.start(t);
    o.stop(t + 0.25);
  }
  noiseHit(t, type, freq, vol, dur, bus = this.music) {
    const ctx = this.ctx;
    const s = ctx.createBufferSource();
    s.buffer = this.noise;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    const g = ctx.createGain();
    this.env(g, t, 0.002, vol, dur);
    s.connect(f).connect(g).connect(bus);
    s.start(t, Math.random() * 0.5);
    s.stop(t + dur + 0.05);
  }
  snare(t) {
    this.noiseHit(t, "bandpass", 2000, 0.07, 0.12);
  }
  rim(t) {
    this.voice("square", 1700, t, 0.03, 0.025, { filter: 3000 });
  }
  shaker(t, v) {
    this.noiseHit(t, "highpass", 8000, v, 0.035);
  }
  crackle(t) {
    for (let i = 0; i < 3; i++) this.noiseHit(t + Math.random() * 0.4, "highpass", 3000, 0.012 + Math.random() * 0.01, 0.006);
  }

  tone(type, f0, f1, t, dur, vol) {
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(f0, t);
    o.frequency.exponentialRampToValueAtTime(f1, t + dur);
    const g = ctx.createGain();
    this.env(g, t, 0.005, vol, dur);
    o.connect(g).connect(this.sfxBus);
    o.start(t);
    o.stop(t + dur + 0.05);
  }

  // ---- sound effects -----------------------------------------------------------
  sfx(name) {
    this.ensure();
    const ctx = this.ctx;
    if (!ctx || ctx.state !== "running") return;
    const t = ctx.currentTime + 0.01;
    const B = this.sfxBus;
    const bell = (n, dt = 0, v = 0.1) => this.bell(NOTE(n), t + dt, B, v);
    switch (name) {
      case "open":
        bell(88, 0, 0.12);
        bell(95, 0.08);
        break;
      case "close":
        bell(91, 0, 0.08);
        bell(84, 0.07, 0.07);
        break;
      case "jump":
        this.tone("sine", 320, 620, t, 0.14, 0.12);
        break;
      case "land":
        this.noiseHit(t, "lowpass", 400, 0.14, 0.08, B);
        break;
      case "bounce":
        this.tone("sine", 180, 900, t, 0.35, 0.18);
        break;
      case "collect":
        [84, 88, 91, 96].forEach((n, i) => bell(n, i * 0.05, 0.08));
        break;
      case "check":
        [79, 84, 88].forEach((n, i) => bell(n, i * 0.08));
        break;
      case "win":
        [72, 76, 79, 84, 88, 91, 96].forEach((n, i) => bell(n, i * 0.07, 0.09));
        this.noiseHit(t + 0.4, "highpass", 6000, 0.05, 0.6, B);
        break;
      case "end":
        [79, 76, 72].forEach((n, i) => bell(n, i * 0.1, 0.09));
        break;
      case "start":
        [72, 79].forEach((n, i) => bell(n, i * 0.12));
        break;
      case "fall":
        this.tone("sine", 1200, 260, t, 0.6, 0.1);
        break;
      case "kick":
        this.noiseHit(t, "lowpass", 900, 0.2, 0.06, B);
        this.tone("sine", 220, 90, t, 0.1, 0.12);
        break;
      case "bonk":
        this.tone("square", 520, 160, t, 0.12, 0.06);
        this.noiseHit(t, "bandpass", 2500, 0.08, 0.05, B);
        break;
      case "meow": {
        const o = ctx.createOscillator();
        o.type = "sawtooth";
        o.frequency.setValueAtTime(520, t);
        o.frequency.linearRampToValueAtTime(820, t + 0.15);
        o.frequency.linearRampToValueAtTime(480, t + 0.45);
        const f = ctx.createBiquadFilter();
        f.type = "bandpass";
        f.Q.value = 6;
        f.frequency.setValueAtTime(900, t);
        f.frequency.linearRampToValueAtTime(1600, t + 0.15);
        f.frequency.linearRampToValueAtTime(700, t + 0.45);
        const g = ctx.createGain();
        this.env(g, t, 0.05, 0.1, 0.42);
        o.connect(f).connect(g).connect(B);
        o.start(t);
        o.stop(t + 0.55);
        break;
      }
      case "purr":
        for (let i = 0; i < 10; i++) this.noiseHit(t + i * 0.09, "lowpass", 180, 0.12, 0.06, B);
        break;
      case "woof":
        for (const dt of [0, 0.22]) {
          this.tone("sawtooth", 420, 230, t + dt, 0.12, 0.08);
          this.noiseHit(t + dt, "bandpass", 900, 0.06, 0.08, B);
        }
        break;
      case "squeak":
        this.tone("sine", 1700, 2500, t, 0.07, 0.06);
        this.tone("sine", 1900, 2700, t + 0.1, 0.07, 0.05);
        break;
      case "deer":
        this.noiseHit(t, "lowpass", 600, 0.1, 0.25, B);
        break;
      case "hi":
        bell(79, 0, 0.09);
        bell(83, 0.12, 0.09);
        break;
      case "hug":
        [76, 79, 83, 88].forEach((n, i) => bell(n, i * 0.12, 0.08));
        break;
      case "pop":
        this.tone("sine", 600, 1200, t, 0.06, 0.1);
        break;
      case "join":
        [76, 81, 85, 88].forEach((n, i) => bell(n, i * 0.09));
        break;
      case "invite":
        [84, 88, 91, 88, 96].forEach((n, i) => bell(n, i * 0.08, 0.09));
        break;
      case "shot":
        this.noiseHit(t, "lowpass", 2400, 0.5, 0.18, B);
        this.tone("sine", 160, 40, t, 0.25, 0.35);
        this.noiseHit(t + 0.12, "bandpass", 700, 0.06, 0.9, B);
        break;
      case "equip":
        this.noiseHit(t, "highpass", 3000, 0.12, 0.05, B);
        this.noiseHit(t + 0.12, "highpass", 2500, 0.14, 0.06, B);
        break;
      case "ding":
        bell(96, 0, 0.14);
        break;
      case "tick":
        this.tone("sine", 1500, 1400, t, 0.05, 0.08);
        break;
      case "shutter":
        this.noiseHit(t, "highpass", 4000, 0.25, 0.04, B);
        this.noiseHit(t + 0.07, "highpass", 3000, 0.18, 0.05, B);
        break;
      case "kiss":
        this.tone("sine", 900, 2200, t, 0.08, 0.1);
        this.noiseHit(t + 0.05, "bandpass", 2500, 0.06, 0.04, B);
        [88, 91].forEach((n, i) => bell(n, 0.2 + i * 0.1, 0.06));
        break;
      case "horn":
        this.tone("square", 520, 500, t, 0.12, 0.05);
        this.tone("square", 660, 640, t + 0.16, 0.14, 0.05);
        break;
      case "engine":
        this.tone("sawtooth", 90, 160, t, 0.35, 0.04);
        break;
      case "chat":
        bell(91, 0, 0.05);
        break;
      case "thud":
        this.noiseHit(t, "lowpass", 500, 0.3, 0.12, B);
        break;
      case "ow":
        this.tone("triangle", 700, 300, t, 0.35, 0.12);
        break;
      case "fart": {
        const o = ctx.createOscillator();
        o.type = "sawtooth";
        o.frequency.setValueAtTime(95, t + 1.0);
        for (let i = 1; i < 10; i++) o.frequency.linearRampToValueAtTime(70 + Math.random() * 60, t + 1.0 + i * 0.07);
        const f = ctx.createBiquadFilter();
        f.type = "lowpass";
        f.frequency.value = 420;
        const g = ctx.createGain();
        this.env(g, t + 1.0, 0.03, 0.35, 0.65);
        o.connect(f).connect(g).connect(B);
        o.start(t + 1.0);
        o.stop(t + 1.8);
        this.noiseHit(t + 1.0, "lowpass", 300, 0.12, 0.6, B);
        bell(84, 2.0, 0.06);
        break;
      }
      default:
    }
  }

  destroy() {
    window.removeEventListener("pointerdown", this.unlock);
    window.removeEventListener("keydown", this.unlock);
    clearInterval(this.timer);
    this.ctx?.close().catch(() => {});
    this.ctx = null;
  }
}
