// A gentle day / night switch for any theme. The theme's own sky and colours
// are the default; the switch only nudges them the other way: a soft daytime
// for the dark themes (same colours, lighter), an evening for the light one.
import * as THREE from "three";

const KEY = "tdd3d.time";

export function loadTime() {
  try {
    const v = localStorage.getItem(KEY);
    if (v === "theme") return v;
    // older saves ("day" / "night") become the switch
    if (v === "flip" || v === "day" || v === "night") return "flip";
  } catch {}
  return "theme";
}
export function saveTime(v) {
  try {
    localStorage.setItem(KEY, v);
  } catch {}
}

// is the theme itself a night sky?
export const isNightTheme = (p) => (p.night || 0) >= 0.5;
export function timeIcon(p, mode) {
  const night = isNightTheme(p);
  if (mode === "theme") return night ? "🌙" : "☀️";
  return night ? "☀️" : "🌙";
}

const hsl = { h: 0, s: 0, l: 0 };
const col = new THREE.Color();
// same hue, a set lightness (and a little more colour)
function lightTo(hex, l, sat = 1) {
  col.set(hex).getHSL(hsl);
  col.setHSL(hsl.h, Math.min(1, hsl.s * sat), Math.max(hsl.l, l));
  return `#${col.getHexString()}`;
}
function lighten(hex, k) {
  col.set(hex).getHSL(hsl);
  col.setHSL(hsl.h, hsl.s, hsl.l + (1 - hsl.l) * k);
  return `#${col.getHexString()}`;
}
const mix = (a, b, t) => `#${col.set(a).lerp(new THREE.Color(b), t).getHexString()}`;
const dim = (a, k) => `#${col.set(a).multiplyScalar(k).getHexString()}`;

export function timeVariant(p, mode) {
  if (mode !== "flip") return p;
  const q = { ...p, sunDir: p.sunDir.clone ? p.sunDir.clone() : p.sunDir };
  if (isNightTheme(p)) {
    // a soft daytime in the theme's own colours
    q.sky = [lightTo(p.sky[0], 0.5, 1.15), lightTo(p.sky[1], 0.66, 1.1), lightTo(p.sky[2], 0.8)];
    q.sunDisc = lighten(p.sunDisc, 0.5);
    q.sunDir = new THREE.Vector3(0.45, 0.7, 0.4);
    q.sun = lighten(p.sun, 0.35);
    q.sunI = 1.9;
    q.hemiSky = lighten(p.hemiSky, 0.45);
    q.hemiGround = lighten(p.hemiGround, 0.3);
    q.hemiI = 1.15;
    q.fog = lightTo(p.fog, 0.72);
    q.fogNear = 60;
    q.fogFar = 230;
    q.exposure = 1.0;
    q.night = 0.15;
    q.grassTint = lighten(p.grassTint, 0.45);
    q.tuft = lighten(p.tuft, 0.2);
    q.canopy = lighten(p.canopy, 0.2);
    q.pine = lighten(p.pine, 0.15);
    q.cloud = lighten(p.cloud, 0.6);
    q.under = lighten(p.under, 0.4);
    if (!p.halloween) q.mood = "cozy";
  } else {
    // an evening sky for the light theme
    const hue = p.sky[1];
    q.sky = [mix(hue, "#0a0820", 0.82), mix(hue, "#1c1438", 0.65), mix(p.sky[2], "#3a2850", 0.55)];
    q.sunDisc = "#f4f1ff";
    q.sunDir = new THREE.Vector3(-0.4, 0.55, -0.35);
    q.sun = "#d4d8ff";
    q.sunI = 0.85;
    q.hemiSky = mix(p.hemiSky, "#5a5a8a", 0.55);
    q.hemiGround = dim(p.hemiGround, 0.4);
    q.hemiI = 0.8;
    q.fog = mix(p.fog, "#1c1638", 0.75);
    q.fogNear = 40;
    q.fogFar = 170;
    q.exposure = 1.1;
    q.night = 1;
    q.grassTint = mix(p.grassTint, "#8a90b8", 0.4);
    q.tuft = dim(p.tuft, 0.65);
    q.canopy = dim(p.canopy, 0.75);
    q.pine = dim(p.pine, 0.65);
    q.cloud = mix(p.cloud, "#46406a", 0.65);
    q.under = dim(p.under, 0.6);
    q.particle = "#fff2a8";
    q.petals = false;
    q.mood = "night";
  }
  return q;
}
