      const parts = (part, title = part) =>
        row(title, h("div", { class: "g3d-chips" }, AVATAR_OPTIONS[part].filter((o) => fits(o) || c[part] === o.id).map((o) => chip(o.label, (c[part] || AVATAR_OPTIONS[part][0].id) === o.id, () => set({ [part]: o.id })))));
      const colors = (group, title) => colorRow(title, c[colorKey(group)], AVATAR_COLORS[group], (v) => set({ [colorKey(group)]: v }));
      // surprise me: a whole new look, from only what fits a boy or a girl
