// Watch together. Two ways:
//  1. YouTube or a direct video link: each of you plays it, and every play,
//     pause and skip is sent to the other; a sync loop keeps you within a
//     second of each other the whole time.
//  2. Share my screen: one of you shares a tab or window (any site that isn't
//     copy-protected) and the other sees it live, so it's always in sync.
// On desktop the picture sits on the big screen in the world; on phones it
// docks at the top.
import * as THREE from "three";

function youtubeId(url) {
  try {
    const u = new URL(url.trim());
    if (u.hostname.includes("youtu.be")) return u.pathname.slice(1).split("/")[0];
    if (u.hostname.includes("youtube.com")) {
      if (u.searchParams.get("v")) return u.searchParams.get("v");
      const m = u.pathname.match(/\/(shorts|embed|live)\/([\w-]{6,})/);
      if (m) return m[2];
    }
  } catch {}
  return /^[\w-]{11}$/.test(url.trim()) ? url.trim() : null;
}
const isFile = (url) => /^https?:\/\/.+\.(mp4|webm|ogg|m4v|mov)(\?.*)?$/i.test(url.trim());

let ytReady = null;
function loadYouTube() {
  if (ytReady) return ytReady;
  ytReady = new Promise((resolve) => {
    if (window.YT?.Player) return resolve(window.YT);
    const prev = window.onYouTubeIframeAPIReady;
    window.onYouTubeIframeAPIReady = () => {
      prev?.();
      resolve(window.YT);
    };
    const s = document.createElement("script");
    s.src = "https://www.youtube.com/iframe_api";
    s.async = true;
    document.head.append(s);
  });
  return ytReady;
}

const ICE = [{ urls: ["stun:stun.l.google.com:19302", "stun:stun1.l.google.com:19302"] }];

export class Cinema {
  constructor({ net, toast, audio, h, onLeave }) {
    this.net = net;
    this.toast = toast;
    this.audio = audio;
    this.onLeave = onLeave;
    this.open = false;
    this.state = { kind: null, url: null, playing: false };
    this.quietUntil = 0;
    this.player = null;
    this.video = null;
    this.lastT = 0;
    this.lastPlaying = false;
    this.lastCheck = performance.now();
    this.driver = false; // the one who acted last keeps the other in step
    // screen sharing
    this.pc = null;
    this.shareStream = null;
    this.sharing = false;
    this.pendingIce = [];

    this.h = h;
    this.slot = h("div", { class: "g3d-cinema-slot" });
    this.smooth = true; // 60fps screen share for motion; off = sharper text at 30fps
    const icon = (label, title, fn, extra = "") => h("button", { class: `g3d-cbtn ${extra}`, type: "button", title, "aria-label": title, onclick: fn }, label);

    // what's on, and who's here
    this.nowTitle = h("span", { class: "g3d-cinema-title" }, "nothing on yet");
    this.who = h("span", { class: "g3d-cinema-who" }, "");
    this.status = h("span", { class: "g3d-cinema-status" }, "");
    // paste a link
    this.input = h("input", { class: "g3d-cinema-input", type: "url", placeholder: "paste a youtube or video link ♡" });
    this.input.addEventListener("keydown", (e) => {
      e.stopPropagation();
      if (e.key === "Enter") this.load(this.input.value);
    });
    const pasteBtn = icon("📋", "paste", async () => {
      try {
        const text = await navigator.clipboard.readText();
        if (text) {
          this.input.value = text.trim();
          this.load(this.input.value);
        }
      } catch {
        this.input.focus();
      }
    });
    // controls
    this.playBtn = icon("▶", "play / pause", () => this.togglePlay(), "big");
    this.shareBtn = icon("🖥️", "share my screen", () => (this.sharing ? this.stopShare() : this.shareScreen()));
    this.fpsBtn = h("button", { class: "g3d-cpill", type: "button", title: "screen share quality", onclick: () => this.toggleSmooth() }, "60fps");
    this.recentRow = h("div", { class: "g3d-cinema-recent" });
    this.bar = h("div", { class: "g3d-cinema-bar" },
      h("div", { class: "g3d-cinema-top" },
        h("div", { class: "g3d-cinema-now" }, h("span", { class: "g3d-cinema-label" }, "now showing"), this.nowTitle),
        this.who,
        icon("⌄", "tuck the menu away", () => this.el.classList.toggle("tucked"), "tuck"),
      ),
      h("div", { class: "g3d-cinema-row" }, this.input, pasteBtn, h("button", { class: "g3d-cwatch", type: "button", onclick: () => this.load(this.input.value) }, "watch ♡")),
      h("div", { class: "g3d-cinema-row g3d-cinema-controls" },
        icon("⏪", "back 10 seconds", () => this.skip(-10)),
        this.playBtn,
        icon("⏩", "forward 10 seconds", () => this.skip(10)),
        icon("🔄", "sync us up", () => this.syncNow()),
        h("span", { class: "g3d-cinema-gap" }),
        this.shareBtn,
        this.fpsBtn,
        icon("⛶", "full screen", () => this.fullscreen()),
        icon("✕", "leave the cinema", () => this.close(), "leave"),
      ),
      this.recentRow,
      this.status,
    );
    this.peek = h("button", { class: "g3d-cinema-peek", type: "button", onclick: () => this.el.classList.remove("tucked") }, "🎬 menu");
    this.el = h("div", { class: "g3d-cinema", hidden: true }, this.slot, this.bar, this.peek);
    for (const t of ["touchstart", "touchmove", "touchend", "keydown"]) this.el.addEventListener(t, (e) => e.stopPropagation(), { passive: true });
    document.body.append(this.el);
    this.renderRecent();

    this.loop = setInterval(() => this.tick(), 500);
  }

  togglePlay() {
    if (this.player?.getPlayerState) {
      if (this.isPlaying()) this.player.pauseVideo();
      else this.player.playVideo();
    } else if (this.video && this.state.kind === "file") {
      if (this.video.paused) this.video.play().catch(() => {});
      else this.video.pause();
    } else this.toast("put something on first ♡");
  }

  skip(sec) {
    const t = Math.max(0, this.currentTime() + sec);
    if (this.player?.seekTo) this.player.seekTo(t, true);
    else if (this.video && this.state.kind === "file") this.video.currentTime = t;
    else return;
    this.quietUntil = Date.now() + 300;
    setTimeout(() => this.broadcast(this.isPlaying()), 300);
  }

  setNow(text) {
    if (this.nowTitle.textContent !== text) this.nowTitle.textContent = text;
  }

  recent() {
    try {
      return JSON.parse(localStorage.getItem("tdd3d.cinema.recent") || "[]") || [];
    } catch {
      return [];
    }
  }
  addRecent(url, title) {
    const list = this.recent().filter((r) => r.url !== url);
    list.unshift({ url, title: title || url });
    try {
      localStorage.setItem("tdd3d.cinema.recent", JSON.stringify(list.slice(0, 6)));
    } catch {}
    this.renderRecent();
  }
  renderRecent() {
    const h = this.h;
    const list = this.recent();
    this.recentRow.hidden = !list.length;
    this.recentRow.replaceChildren(
      h("span", { class: "g3d-cinema-label" }, "watch again"),
      ...list.map((r) => h("button", { class: "g3d-cpill", type: "button", title: r.url, onclick: () => this.load(r.url) }, r.title.length > 34 ? r.title.slice(0, 33) + "…" : r.title)),
    );
  }

  fullscreen() {
    const el = this.slot;
    if (!el.firstChild) {
      this.toast("put something on first ♡");
      return;
    }
    if (document.fullscreenElement) document.exitFullscreen?.();
    else if (el.requestFullscreen) el.requestFullscreen().catch(() => {});
    else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen();
    else {
      // iPhone: only the video itself can go full screen
      const v = el.querySelector("video");
      v?.webkitEnterFullscreen?.();
    }
  }

  toggleSmooth() {
    this.smooth = !this.smooth;
    this.fpsBtn.textContent = this.smooth ? "60fps" : "30fps sharp";
    this.fpsBtn.classList.toggle("on", this.smooth);
    if (this.sharing) this.tuneSender();
  }

  // ask the browser for smooth 60fps (or crisp 30fps text) and enough bitrate
  tuneSender() {
    const track = this.shareStream?.getVideoTracks()[0];
    if (track) {
      track.contentHint = this.smooth ? "motion" : "detail";
      track.applyConstraints({ frameRate: { ideal: this.smooth ? 60 : 30, max: this.smooth ? 60 : 30 } }).catch(() => {});
    }
    for (const sender of this.pc?.getSenders() || []) {
      if (sender.track?.kind !== "video") continue;
      const p = sender.getParameters();
      if (!p.encodings?.length) p.encodings = [{}];
      p.encodings[0].maxFramerate = this.smooth ? 60 : 30;
      p.encodings[0].maxBitrate = this.smooth ? 8_000_000 : 5_000_000;
      p.degradationPreference = this.smooth ? "maintain-framerate" : "maintain-resolution";
      sender.setParameters(p).catch(() => {});
    }
  }

  setStatus(t) {
    this.status.textContent = t;
  }

  // ---- open / close ----------------------------------------------------------
  show() {
    this.open = true;
    this.el.hidden = false;
    this.el.classList.toggle("readonly", Boolean(this.readOnly));
    this.audio.setDucked(true);
    this.net.cinema({ type: "hello" });
    if (!this.state.url && !this.pc) this.setStatus(this.net.remotes.size ? "you’re here together ♡ paste a link or share your screen" : "paste a link or share your screen ♡");
  }
  close() {
    this.open = false;
    this.el.hidden = true;
    if (this.sharing) this.stopShare();
    else this.closePeer();
    this.pauseLocal();
    this.audio.setDucked(false);
    this.onLeave?.();
  }

  // ---- links -----------------------------------------------------------------
  async load(url, { remote = false, t = 0, playing = true } = {}) {
    if (this.readOnly && !remote) return;
    url = (url || "").trim();
    const id = youtubeId(url);
    if (!id && !isFile(url)) {
      if (!remote) {
        this.toast(/netflix|disney|primevideo|hulu|max\.com|shahid/i.test(url) ? "that site blocks embedding, try “share my screen” instead" : "paste a youtube link or a video file link");
      }
      return;
    }
    if (this.sharing) this.stopShare();
    this.closePeer();
    this.input.value = url;
    this.destroyMedia();
    this.state = { kind: id ? "yt" : "file", url, playing };
    this.driver = !remote;
    this.quietUntil = Date.now() + 1500;
    if (!remote) this.net.cinema({ type: "load", url, t: 0, playing: true });
    if (id) {
      const YT = await loadYouTube();
      const holder = document.createElement("div");
      this.slot.replaceChildren(holder);
      this.player = new YT.Player(holder, {
        videoId: id,
        playerVars: { playsinline: 1, rel: 0, modestbranding: 1, start: Math.floor(t) },
        events: {
          onReady: (e) => {
            this.quietUntil = Date.now() + 1500;
            if (t) e.target.seekTo(t, true);
            if (playing) e.target.playVideo();
            else e.target.pauseVideo();
          },
          onStateChange: (e) => {
            // 1 playing, 2 paused (3 buffering is ignored)
            if (e.data !== 1 && e.data !== 2) return;
            if (Date.now() < this.quietUntil) return;
            this.broadcast(e.data === 1);
          },
          onPlaybackRateChange: () => Date.now() > this.quietUntil && this.broadcast(this.isPlaying()),
        },
      });
    } else {
      const v = document.createElement("video");
      v.src = url;
      v.controls = true;
      v.playsInline = true;
      this.slot.replaceChildren(v);
      this.video = v;
      v.addEventListener("loadedmetadata", () => {
        this.quietUntil = Date.now() + 1200;
        if (t) v.currentTime = t;
        if (playing) v.play().catch(() => {});
      }, { once: true });
      for (const ev of ["play", "pause", "seeked", "ratechange"]) {
        v.addEventListener(ev, () => Date.now() > this.quietUntil && this.broadcast(!v.paused));
      }
    }
    this.lastT = t;
    this.lastCheck = performance.now();
    this.setStatus(remote ? "synced with your person ♡" : this.net.remotes.size ? "playing for both of you ♡" : "playing ♡ (it syncs when they join)");
  }

  destroyMedia() {
    try {
      this.player?.destroy();
    } catch {}
    this.player = null;
    if (this.video) {
      this.video.pause();
      this.video.srcObject = null;
    }
    this.video = null;
    this.slot.replaceChildren();
  }

  currentTime() {
    try {
      if (this.player?.getCurrentTime) return this.player.getCurrentTime() || 0;
    } catch {}
    return this.video && this.state.kind === "file" ? this.video.currentTime : 0;
  }
  rate() {
    try {
      if (this.player?.getPlaybackRate) return this.player.getPlaybackRate() || 1;
    } catch {}
    return this.video?.playbackRate || 1;
  }
  isPlaying() {
    try {
      if (this.player?.getPlayerState) return this.player.getPlayerState() === 1;
    } catch {}
    return this.video ? !this.video.paused : false;
  }

  // full screen on the picture: the game pauses drawing so the video stays smooth
  isFullscreen() {
    const f = document.fullscreenElement || document.webkitFullscreenElement;
    return Boolean(this.open && f && (f === this.slot || this.slot.contains(f)));
  }

  broadcast(playing) {
    if (this.readOnly) return;
    this.driver = true;
    this.state.playing = playing;
    this.lastT = this.currentTime();
    this.lastPlaying = playing;
    this.lastCheck = performance.now();
    this.net.cinema({ type: "state", url: this.state.url, t: this.lastT, playing, rate: this.rate(), sent: Date.now() });
  }

  // every half second: catch skips the player doesn't report (e.g. while paused),
  // and the one who acted last sends a gentle "here's where I am" every 2s
  tick() {
    if (!this.open) return;
    const people = [...this.net.remotes.values()].map((r) => r.name || "your person");
    const who = people.length ? `💗 ${people.join(", ")} is here` : "waiting for your person…";
    if (this.who.textContent !== who) this.who.textContent = who;
    this.who.classList.toggle("here", people.length > 0);
    if (this.state.kind === "yt") {
      let title = "";
      try {
        title = this.player?.getVideoData?.().title || "";
      } catch {}
      if (title && title !== this.state.title) {
        this.state.title = title;
        this.addRecent(this.state.url, title);
      }
      this.setNow(title || "loading…");
    } else if (this.state.kind === "file") {
      const name = decodeURIComponent((this.state.url || "").split("/").pop().split("?")[0] || "video");
      if (!this.state.title) {
        this.state.title = name;
        this.addRecent(this.state.url, name);
      }
      this.setNow(name);
    } else if (this.state.kind === "watching-share") this.setNow("🖥️ their screen");
    const playingNow = this.isPlaying();
    const icon = playingNow ? "⏸" : "▶";
    if (this.playBtn.textContent !== icon) this.playBtn.textContent = icon;
    if (this.state.kind !== "yt" && this.state.kind !== "file") return;
    const now = performance.now();
    // a video that hasn't started (autoplay blocked), is loading or buffering
    // isn't a choice anyone made, so it's never sent to your person
    let ytState = 1;
    try {
      if (this.player?.getPlayerState) ytState = this.player.getPlayerState();
    } catch {}
    if (this.state.kind === "yt" && ytState !== 1 && ytState !== 2) {
      if (ytState === -1 || ytState === 5) this.setStatus("press play on the video to join in ♡");
      this.lastCheck = now;
      return;
    }
    const t = this.currentTime();
    const playing = this.isPlaying();
    const expected = this.lastT + (this.lastPlaying ? ((now - this.lastCheck) / 1000) * this.rate() : 0);
    if (Date.now() > this.quietUntil) {
      if (Math.abs(t - expected) > 1.5 || playing !== this.lastPlaying) this.broadcast(playing);
      else if (this.driver && now - (this.lastBeat || 0) > 2000) {
        this.lastBeat = now;
        this.net.cinema({ type: "beat", url: this.state.url, t, playing, rate: this.rate(), sent: Date.now() });
      }
    }
    this.lastT = t;
    this.lastPlaying = playing;
    this.lastCheck = now;
  }

  // apply what your person's player is doing
  apply(p, hard) {
    if (p.url && p.url !== this.state.url) {
      this.load(p.url, { remote: true, t: p.t || 0, playing: p.playing });
      return;
    }
    const lag = p.sent ? Math.min(2, Math.max(0, (Date.now() - p.sent) / 1000)) : 0.2;
    const t = (p.t || 0) + (p.playing ? lag * (p.rate || 1) : 0);
    const off = Math.abs(this.currentTime() - t);
    const limit = hard ? 0.6 : 1.0;
    if (off < limit && this.isPlaying() === p.playing) return;
    this.quietUntil = Date.now() + 1200;
    try {
      if (this.player?.seekTo) {
        if (off > limit) this.player.seekTo(t, true);
        if (p.rate && this.player.setPlaybackRate) this.player.setPlaybackRate(p.rate);
        p.playing ? this.player.playVideo() : this.player.pauseVideo();
      } else if (this.video) {
        if (off > limit) this.video.currentTime = t;
        if (p.rate) this.video.playbackRate = p.rate;
        p.playing ? this.video.play().catch(() => {}) : this.video.pause();
      }
    } catch {}
    this.lastT = t;
    this.lastPlaying = p.playing;
    this.lastCheck = performance.now();
  }

  pauseLocal() {
    this.quietUntil = Date.now() + 800;
    try {
      this.player?.pauseVideo?.();
    } catch {}
    if (this.state.kind === "file") this.video?.pause();
  }

  // ---- screen sharing (WebRTC; the realtime channel carries the handshake) ----
  async shareScreen() {
    if (!navigator.mediaDevices?.getDisplayMedia) {
      this.toast("this device can’t share its screen (try a computer)");
      return;
    }
    let stream;
    try {
      stream = await navigator.mediaDevices.getDisplayMedia({
        video: { frameRate: { ideal: this.smooth ? 60 : 30, max: 60 }, width: { ideal: 1920 }, height: { ideal: 1080 } },
        audio: true,
      });
    } catch {
      return;
    }
    this.destroyMedia();
    this.closePeer();
    this.state = { kind: "share", url: null, playing: true };
    this.shareStream = stream;
    this.sharing = true;
    this.shareBtn.textContent = "⏹";
    this.shareBtn.classList.add("on");
    this.setNow("🖥️ your screen");
    const v = document.createElement("video");
    v.muted = true;
    v.playsInline = true;
    v.autoplay = true;
    v.srcObject = stream;
    this.slot.replaceChildren(v);
    this.video = v;
    stream.getVideoTracks()[0]?.addEventListener("ended", () => this.stopShare());
    this.setStatus(this.net.remotes.size ? "sharing with your person ♡" : "sharing ♡ (they’ll see it when they come to the cinema)");
    this.offer();
  }

  makePeer(sharer) {
    const pc = new RTCPeerConnection({ iceServers: ICE });
    pc.onicecandidate = (e) => {
      if (e.candidate) this.net.cinema({ type: "rtc-ice", c: e.candidate.toJSON(), to: sharer ? "viewer" : "sharer" });
    };
    pc.onconnectionstatechange = () => {
      if (pc.connectionState === "failed") this.setStatus("couldn’t connect the screen share (your networks may block it)");
      if (pc.connectionState === "connected") {
        this.setStatus(sharer ? "your person is watching your screen ♡" : "watching their screen ♡");
        if (sharer) this.tuneSender();
      }
    };
    return pc;
  }

  async offer() {
    if (!this.sharing || !this.shareStream) return;
    this.pc?.close();
    const pc = this.makePeer(true);
    this.pc = pc;
    this.shareStream.getTracks().forEach((t) => pc.addTrack(t, this.shareStream));
    this.tuneSender();
    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);
    this.net.cinema({ type: "rtc-offer", sdp: offer.sdp });
  }

  async answer(sdp) {
    this.destroyMedia();
    this.pc?.close();
    this.pendingIce = [];
    const pc = this.makePeer(false);
    this.pc = pc;
    this.state = { kind: "watching-share", url: null, playing: true };
    const v = document.createElement("video");
    v.playsInline = true;
    v.autoplay = true;
    this.slot.replaceChildren(v);
    this.video = v;
    pc.ontrack = (e) => {
      v.srcObject = e.streams[0];
      v.play().catch(() => {
        v.muted = true;
        v.play().catch(() => {});
        this.setStatus("tap the picture to turn the sound on");
        v.addEventListener("click", () => (v.muted = false), { once: true });
      });
    };
    await pc.setRemoteDescription({ type: "offer", sdp });
    for (const c of this.pendingIce.splice(0)) await pc.addIceCandidate(c).catch(() => {});
    const ans = await pc.createAnswer();
    await pc.setLocalDescription(ans);
    this.net.cinema({ type: "rtc-answer", sdp: ans.sdp });
    this.setStatus("connecting to their screen…");
  }

  stopShare() {
    this.shareStream?.getTracks().forEach((t) => t.stop());
    this.shareStream = null;
    this.sharing = false;
    this.shareBtn.textContent = "🖥️";
    this.shareBtn.classList.remove("on");
    this.setNow("nothing on yet");
    this.closePeer();
    this.destroyMedia();
    this.state = { kind: null, url: null, playing: false };
    this.net.cinema({ type: "rtc-stop" });
    this.setStatus("stopped sharing");
  }

  closePeer() {
    this.pc?.close();
    this.pc = null;
    this.pendingIce = [];
    if (this.state.kind === "watching-share") {
      this.destroyMedia();
      this.state = { kind: null, url: null, playing: false };
    }
  }

  // ---- messages from your person -------------------------------------------------
  onRemote(p, who) {
    const name = who || "your person";
    switch (p.type) {
      case "hello":
        // they just walked in: tell them what's on
        if (this.sharing) this.offer();
        else if (this.state.url) this.net.cinema({ type: "state", url: this.state.url, t: this.currentTime(), playing: this.isPlaying(), rate: this.rate(), sent: Date.now() });
        return;
      case "load":
        this.pending = p;
        if (this.open) this.load(p.url, { remote: true, t: p.t || 0, playing: p.playing });
        else this.toast(`${name} put on a video 🎬 come to the cinema`);
        return;
      case "state":
      case "beat":
        this.pending = { ...p, type: "state" };
        if (!this.open) return;
        this.driver = false;
        this.apply(p, p.type === "state");
        if (p.type === "state") this.setStatus(p.playing ? `${name} pressed play ♡` : `${name} paused`);
        return;
      case "rtc-offer":
        this.pendingOffer = p.sdp;
        if (this.open && !this.sharing) this.answer(p.sdp);
        else if (!this.open) this.toast(`${name} is sharing their screen 🎬 come to the cinema`);
        return;
      case "rtc-answer":
        if (this.sharing && this.pc && !this.pc.currentRemoteDescription) this.pc.setRemoteDescription({ type: "answer", sdp: p.sdp }).catch(() => {});
        return;
      case "rtc-ice": {
        const mine = this.sharing ? "sharer" : "viewer";
        if (p.to !== mine) return;
        if (this.pc?.remoteDescription) this.pc.addIceCandidate(p.c).catch(() => {});
        else this.pendingIce.push(p.c);
        return;
      }
      case "rtc-stop":
        this.pendingOffer = null;
        if (this.state.kind === "watching-share") {
          this.closePeer();
          this.setStatus(`${name} stopped sharing`);
        }
        return;
      default:
    }
  }

  // when you open the cinema after they started something
  catchUp() {
    if (this.pendingOffer && !this.sharing) {
      this.answer(this.pendingOffer);
      return;
    }
    const p = this.pending;
    if (p?.url && p.url !== this.state.url) this.load(p.url, { remote: true, t: p.t || 0, playing: p.playing });
  }

  // put the picture on the in-world screen (desktop) or dock it (phones)
  place(camera, screenMesh) {
    if (!this.open) return;
    const setCss = (css) => {
      if (this.lastCss !== css) {
        this.lastCss = css;
        this.slot.style.cssText = css;
      }
    };
    if (this.isFullscreen()) {
      setCss("");
      return;
    }
    const docked = window.innerWidth <= 720;
    if (this.docked !== docked) {
      this.docked = docked;
      this.el.classList.toggle("docked", docked);
    }
    if (docked || !screenMesh) {
      setCss("");
      return;
    }
    const box = new THREE.Box2(new THREE.Vector2(Infinity, Infinity), new THREE.Vector2(-Infinity, -Infinity));
    const geo = screenMesh.geometry;
    if (!geo.boundingBox) geo.computeBoundingBox();
    const b = geo.boundingBox;
    const v = new THREE.Vector3();
    for (const x of [b.min.x, b.max.x]) {
      for (const y of [b.min.y, b.max.y]) {
        v.set(x, y, 0).applyMatrix4(screenMesh.matrixWorld).project(camera);
        box.expandByPoint(new THREE.Vector2(((v.x + 1) / 2) * window.innerWidth, ((1 - v.y) / 2) * window.innerHeight));
      }
    }
    const r = (n) => Math.round(n);
    setCss(`left:${r(box.min.x)}px;top:${r(box.min.y)}px;width:${r(box.max.x - box.min.x)}px;height:${r(box.max.y - box.min.y)}px;`);
  }

  destroy() {
    clearInterval(this.loop);
    if (this.sharing) this.stopShare();
    this.closePeer();
    this.destroyMedia();
    this.el.remove();
  }
}
